  // 🔥 RESTAURAR SESIÓN AL MONTAR O VOLVER A LA VISTA DE SESIÓN
  useEffect(() => {
    const verificarSesionGuardada = async () => {
      const estadoGuardado = await cargarEstadoSesion();
      if (estadoGuardado && estadoGuardado.estado?.sesionActiva) {
        console.log('🔄 Sesión guardada detectada al montar componente');
        // Solo restaurar si no hay una sesión activa ya
        if (!sesionActiva) {
          setSesionPersistente(estadoGuardado);
        }
      }
    };
    verificarSesionGuardada();
  }, []); // Solo al montar

  // 🔥 MANTENER SESIÓN ACTIVA AL CAMBIAR DE MENÚ
  useEffect(() => {
    // Si hay una sesión activa guardada en localStorage y volvemos al menú de sesión
    if (selectedMenu === 'sesion' && !sesionActiva) {
      const estadoGuardado = cargarEstadoSesion();
      if (estadoGuardado && estadoGuardado.estado?.sesionActiva) {
        console.log('🔄 Detectada sesión activa al volver al menú, restaurando...');
        // Restaurar sin cambiar el menú (ya estamos en 'sesion')
        try {
          // Restaurar configuración
          setTiempoSesion(estadoGuardado.configuracion.tiempoSesion);
          setTiempoPersonalizado(estadoGuardado.configuracion.tiempoPersonalizado || '');
          setModoLibreActivo(estadoGuardado.configuracion.modoLibreActivo || false);
          setPrioridadSesion(estadoGuardado.configuracion.prioridadSesion);
          
          // Restaurar estado de sesión
          setSesionActiva(estadoGuardado.estado.sesionActiva);
          setSesionPausada(estadoGuardado.estado.sesionPausada);
          setFaseActual(estadoGuardado.estado.faseActual);
          setIndiceFaseActual(estadoGuardado.estado.indiceFaseActual);
          setTiempoRestante(estadoGuardado.estado.tiempoRestante);
          setTiempoFaseActual(estadoGuardado.estado.tiempoFaseActual);
          setTiempoTotalEfectivo(estadoGuardado.estado.tiempoTotalEfectivo);
          setTiempoPausaTotal(estadoGuardado.estado.tiempoPausaTotal || 0);
          setTiempoInicioSesion(estadoGuardado.estado.tiempoInicioSesion);
          setTimestampInicioPausa(estadoGuardado.estado.timestampInicioPausa);
          
          // Restaurar fases
          setFasesSesion(estadoGuardado.fases || []);
          
          // Restaurar estadísticas
          setEstadisticasSesion(estadoGuardado.estadisticas || {
            erroresReforzados: 0,
            flashcardsRepasadas: 0,
            practicasHechas: 0,
            notasTomadas: 0
          });
          
          // Restaurar datos de fases
          if (estadoGuardado.datos) {
            setDatosCalentamiento(estadoGuardado.datos.calentamiento);
            
            if (estadoGuardado.datos.errores) {
              setErroresActuales(estadoGuardado.datos.errores.lista || []);
              setIndiceErrorActual(estadoGuardado.datos.errores.indiceActual || 0);
            }
            
            if (estadoGuardado.datos.flashcards) {
              setFlashcardsSesion(estadoGuardado.datos.flashcards.lista || []);
              setIndiceFlashcardActual(estadoGuardado.datos.flashcards.indiceActual || 0);
            }
            
            if (estadoGuardado.datos.contenido) {
              setTabContenidoActivo(estadoGuardado.datos.contenido.tab || 0);
              setDocumentoActual(estadoGuardado.datos.contenido.documento);
              setCursoActual(estadoGuardado.datos.contenido.curso);
              setNotasVinculadas(estadoGuardado.datos.contenido.notasVinculadas || []);
              setPracticaGenerada(estadoGuardado.datos.contenido.practicaGenerada);
              setHistorialPracticas(estadoGuardado.datos.contenido.historialPracticas || []);
              setProgresoDocumento(estadoGuardado.datos.contenido.progresoDocumento || 0);
              setScrollPositions(estadoGuardado.datos.contenido.scrollPositions || { 0: 0, 1: 0, 2: 0 });
            }
            
            if (estadoGuardado.datos.cierre) {
              setResumenSesion(estadoGuardado.datos.cierre.resumen);
              setReflexionDificil(estadoGuardado.datos.cierre.reflexionDificil || '');
              setReflexionManana(estadoGuardado.datos.cierre.reflexionManana || '');
              setRecomendacionesSesion(estadoGuardado.datos.cierre.recomendaciones || []);
            }
          }
          
          // Restaurar notas en progreso
          if (estadoGuardado.notasEnProgreso) {
            setEditorNotaTitulo(estadoGuardado.notasEnProgreso.titulo || '');
            setEditorNotaContenido(estadoGuardado.notasEnProgreso.contenido || '');
            setEditorNotaTags(estadoGuardado.notasEnProgreso.tags || '');
          }
          
          setSesionPersistente(estadoGuardado);
          console.log('✅ Sesión restaurada al volver al menú');
        } catch (error) {
          console.error('❌ Error restaurando sesión:', error);
        }
      }
    }
  }, [selectedMenu, sesionActiva]);

  // Event listener para clicks en enlaces de referencia a notas
  useEffect(() => {
    const handleNotaClick = async (e) => {
      // Buscar el enlace más cercano con data-nota-id
      let target = e.target;
      let link = null;
      
      // Subir por el DOM buscando un enlace con data-nota-id
      while (target && target !== document.body) {
        if (target.tagName === 'A' && target.hasAttribute('data-nota-id')) {
          link = target;
          break;
        }
        target = target.parentElement;
      }
      
      if (link) {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        
        const notaId = link.getAttribute('data-nota-id');
        
        console.log('📝 Click en referencia a nota:', notaId);
        
        try {
          const notasActuales = await getDatos('notas');
          // Comparar como strings para soportar IDs tipo 'nota_123456'
          const nota = notasActuales.find(n => String(n.id) === String(notaId));
          
          if (nota) {
            console.log('✅ Nota encontrada:', nota.titulo);
            
            // Actualizar el estado de notas guardadas primero
            setNotasGuardadas(notasActuales);
            setSelectedMenu('notas');
            
            // Navegar a la carpeta de la nota
            if (nota.carpeta) {
              setRutaNotasActual(nota.carpeta);
              cargarCarpetasNotas(nota.carpeta);
            } else {
              setRutaNotasActual('');
              cargarCarpetasNotas('');
            }
            
            // Abrir la nota directamente
            setNotaActual(nota);
            setTituloNota(nota.titulo);
            setContenidoNota(nota.contenido);
            setCarpetaNota(nota.carpeta || '');
            setModoSoloLectura(true);
            setEditorNotaAbierto(true);
            console.log('📖 Editor de nota abierto:', nota.titulo);
          } else {
            console.warn('⚠️ Nota no encontrada con ID:', notaId);
            setMensaje({ tipo: 'warning', texto: '⚠️ La nota referenciada no existe' });
          }
        } catch (error) {
          console.error('❌ Error abriendo nota:', error);
        }
        
        return false;
      }
    };
    
    // Usar capture: true para interceptar antes que otros handlers
    document.addEventListener('click', handleNotaClick, true);
    return () => document.removeEventListener('click', handleNotaClick, true);
  }, []);

  // Cerrar dropdowns de notas al hacer clic fuera
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (!e.target.closest('.dropdown-nota')) {
        setDropdownNotaAbierto(null);
      }
    };
    
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Actualizar contenido del editor cuando se abre una nota o cuando cambia el contenido
  useEffect(() => {
    if (editorRef.current && editorNotaAbierto) {
      // Solo actualizar si el contenido es diferente para evitar loops
      if (editorRef.current.innerHTML !== contenidoNota) {
        console.log('📝 Actualizando contenido del editor:', contenidoNota?.substring(0, 50) + '...');
        editorRef.current.innerHTML = contenidoNota;
      }
      // Asegurar dirección LTR
      editorRef.current.setAttribute('dir', 'ltr');
      editorRef.current.style.direction = 'ltr';
      editorRef.current.style.textAlign = 'left';
      
      // Sistema completo de edición de imágenes
      window.imagenSeleccionada = null;
      window.modoEdicion = null; // 'resize', 'move', 'crop'
      window.datosInicio = {};
      
      window.mostrarControlesImagen = function(img) {
        if (modoSoloLectura) return;
        
        // Remover controles anteriores
        document.querySelectorAll('.controles-imagen').forEach(c => c.remove());
        document.querySelectorAll('.imagen-editable.seleccionada').forEach(i => i.classList.remove('seleccionada'));
        
        img.classList.add('seleccionada');
        window.imagenSeleccionada = img;
        
        // Crear controles avanzados con etiquetas visibles
        const controles = document.createElement('div');
        controles.className = 'controles-imagen';
        
        // Crear barra de arrastre para los controles
        const barraArrastre = document.createElement('div');
        barraArrastre.style.cssText = `
          background: rgba(100, 108, 255, 0.3);
          padding: 0.3rem;
          margin-bottom: 0.5rem;
          border-radius: 6px;
          cursor: move;
          text-align: center;
          font-size: 0.7rem;
          color: rgba(255,255,255,0.7);
          user-select: none;
          display: flex;
          justify-content: space-between;
          align-items: center;
        `;
        
        // Contenedor izquierdo (espaciador)
        const espaciadorIzq = document.createElement('span');
        espaciadorIzq.style.opacity = '0';
        espaciadorIzq.textContent = '✕';
        
        // Indicador central de arrastre
        const indicadorArrastre = document.createElement('span');
        indicadorArrastre.textContent = '⋮⋮⋮';
        
        // Botón de cerrar
        const btnCerrar = document.createElement('button');
        btnCerrar.textContent = '✕';
        btnCerrar.style.cssText = `
          background: transparent;
          border: none;
          color: rgba(255,255,255,0.8);
          cursor: pointer;
          font-size: 1rem;
          padding: 0 0.3rem;
          line-height: 1;
        `;
        btnCerrar.title = 'Cerrar controles';
        btnCerrar.onclick = (e) => {
          e.stopPropagation();
          controles.remove();
          img.classList.remove('seleccionada');
          window.imagenSeleccionada = null;
        };
        
        barraArrastre.appendChild(espaciadorIzq);
        barraArrastre.appendChild(indicadorArrastre);
        barraArrastre.appendChild(btnCerrar);
        
        let arrastrando = false;
        let offsetX = 0;
        let offsetY = 0;
        
        indicadorArrastre.addEventListener('mousedown', (e) => {
          e.preventDefault();
          arrastrando = true;
          const rect = controles.getBoundingClientRect();
          offsetX = e.clientX - rect.left;
          offsetY = e.clientY - rect.top;
          controles.style.position = 'fixed';
        });
        
        document.addEventListener('mousemove', (e) => {
          if (arrastrando) {
            controles.style.left = (e.clientX - offsetX) + 'px';
            controles.style.top = (e.clientY - offsetY) + 'px';
            controles.style.transform = 'none';
          }
        });
        
        document.addEventListener('mouseup', () => {
          if (arrastrando) {
            arrastrando = false;
          }
        });
        
        controles.appendChild(barraArrastre);
        
        const contenidoControles = document.createElement('div');
        contenidoControles.innerHTML = `
          <div class="control-seccion">
            <div class="control-titulo">Tamaño</div>
            <div class="control-grupo">
              <button class="control-btn" onclick="window.ajustarImagen('pequeña')">S</button>
              <button class="control-btn" onclick="window.ajustarImagen('mediana')">M</button>
              <button class="control-btn" onclick="window.ajustarImagen('grande')">L</button>
              <button class="control-btn" onclick="window.ajustarImagen('completa')">XL</button>
            </div>
          </div>
          <div class="control-separador"></div>
          <div class="control-seccion">
            <div class="control-titulo">Alinear</div>
            <div class="control-grupo">
              <button class="control-btn" onclick="window.alinearImagen('izquierda')" title="Izquierda">◀</button>
              <button class="control-btn" onclick="window.alinearImagen('centro')" title="Centro">◆</button>
              <button class="control-btn" onclick="window.alinearImagen('derecha')" title="Derecha">▶</button>
            </div>
          </div>
          <div class="control-separador"></div>
          <div class="control-seccion">
            <div class="control-titulo">Transparencia</div>
            <div class="control-grupo">
              <button class="control-btn" onclick="window.cambiarOpacidad(-0.2)">➖</button>
              <button class="control-btn" onclick="window.cambiarOpacidad(0.2)">➕</button>
            </div>
          </div>
          <div class="control-separador"></div>
          <div class="control-grupo">
            <button class="control-btn control-recortar" onclick="window.iniciarRecorte()">✂️ Recortar</button>
            <button class="control-btn control-eliminar" onclick="window.eliminarImagen()">🗑️ Eliminar</button>
          </div>
        `;
        
        controles.appendChild(contenidoControles);
        img.parentElement.appendChild(controles);
        
        // Agregar manejadores de redimensionado
        agregarManejadoresResize(img);
      };
      
      function agregarManejadoresResize(img) {
        // Remover manejadores anteriores
        document.querySelectorAll('.resize-handle').forEach(h => h.remove());
        
        const contenedor = img.parentElement;
        const handles = ['nw', 'ne', 'sw', 'se', 'n', 's', 'e', 'w'];
        
        handles.forEach(pos => {
          const handle = document.createElement('div');
          handle.className = `resize-handle resize-${pos}`;
          handle.dataset.position = pos;
          
          handle.addEventListener('mousedown', (e) => {
            e.preventDefault();
            e.stopPropagation();
            
            window.modoEdicion = 'resize';
            window.datosInicio = {
              x: e.clientX,
              y: e.clientY,
              width: img.offsetWidth,
              height: img.offsetHeight,
              position: pos
            };
            
            document.body.style.cursor = getComputedStyle(handle).cursor;
          });
          
          contenedor.appendChild(handle);
        });
      }
      
      // Event listeners para mouse
      const mouseMoveHandler = (e) => {
        if (!window.imagenSeleccionada || !window.modoEdicion) return;
        
        if (window.modoEdicion === 'resize') {
          const deltaX = e.clientX - window.datosInicio.x;
          const deltaY = e.clientY - window.datosInicio.y;
          const pos = window.datosInicio.position;
          
          let newWidth = window.datosInicio.width;
          let newHeight = window.datosInicio.height;
          
          // Calcular nuevo tamaño según la posición del handle
          if (pos.includes('e')) newWidth = window.datosInicio.width + deltaX;
          if (pos.includes('w')) newWidth = window.datosInicio.width - deltaX;
          if (pos.includes('s')) newHeight = window.datosInicio.height + deltaY;
          if (pos.includes('n')) newHeight = window.datosInicio.height - deltaY;
          
          // Mantener proporción si es esquina
          if (pos.length === 2) {
            const ratio = window.datosInicio.width / window.datosInicio.height;
            newHeight = newWidth / ratio;
          }
          
          // Límites mínimos
          newWidth = Math.max(50, Math.min(1200, newWidth));
          newHeight = Math.max(50, Math.min(1200, newHeight));
          
          window.imagenSeleccionada.style.width = newWidth + 'px';
          window.imagenSeleccionada.style.height = newHeight + 'px';
        }
        
        if (window.modoEdicion === 'move') {
          const deltaX = e.clientX - window.datosInicio.x;
          const deltaY = e.clientY - window.datosInicio.y;
          
          window.imagenSeleccionada.parentElement.style.left = (window.datosInicio.left + deltaX) + 'px';
          window.imagenSeleccionada.parentElement.style.top = (window.datosInicio.top + deltaY) + 'px';
        }
      };
      
      const mouseUpHandler = () => {
        window.modoEdicion = null;
        document.body.style.cursor = 'default';
      };
      
      document.addEventListener('mousemove', mouseMoveHandler);
      document.addEventListener('mouseup', mouseUpHandler);
      
      // Funciones globales
      window.ajustarImagen = function(tamaño) {
        if (!window.imagenSeleccionada) return;
        const anchos = { pequeña: 200, mediana: 400, grande: 600, completa: '100%' };
        window.imagenSeleccionada.style.width = typeof anchos[tamaño] === 'number' ? anchos[tamaño] + 'px' : anchos[tamaño];
        window.imagenSeleccionada.style.height = 'auto';
      };
      
      window.alinearImagen = function(alineacion) {
        if (!window.imagenSeleccionada) return;
        const contenedor = window.imagenSeleccionada.parentElement;
        
        // Crear wrapper si no existe para controlar alineación
        let wrapper = contenedor.parentElement;
        if (!wrapper.classList.contains('imagen-wrapper')) {
          wrapper = document.createElement('div');
          wrapper.className = 'imagen-wrapper';
          wrapper.style.display = 'block';
          wrapper.style.width = '100%';
          wrapper.style.margin = '0.5rem 0';
          contenedor.parentNode.insertBefore(wrapper, contenedor);
          wrapper.appendChild(contenedor);
        }
        
        // Reset
        wrapper.style.textAlign = '';
        contenedor.style.display = 'inline-block';
        
        switch(alineacion) {
          case 'izquierda':
            wrapper.style.textAlign = 'left';
            break;
          case 'centro':
            wrapper.style.textAlign = 'center';
            break;
          case 'derecha':
            wrapper.style.textAlign = 'right';
            break;
        }
      };
      
      // Función para texto envolvente (como en Word)
      window.textoEnvolvente = function(tipo) {
        if (!window.imagenSeleccionada) return;
        const contenedor = window.imagenSeleccionada.parentElement;
        
        // Reset estilos de flujo
        contenedor.style.float = 'none';
        contenedor.style.display = 'block';
        contenedor.style.clear = 'none';
        contenedor.style.marginTop = '';
        contenedor.style.marginBottom = '';
        
        switch(tipo) {
          case 'izquierda':
            // Imagen a la izquierda, texto fluye a la derecha
            contenedor.style.float = 'left';
            contenedor.style.marginRight = '15px';
            contenedor.style.marginBottom = '10px';
            break;
          case 'derecha':
            // Imagen a la derecha, texto fluye a la izquierda
            contenedor.style.float = 'right';
            contenedor.style.marginLeft = '15px';
            contenedor.style.marginBottom = '10px';
            break;
          case 'ninguno':
            // Imagen en línea con el texto (bloque)
            contenedor.style.display = 'block';
            contenedor.style.clear = 'both';
            contenedor.style.marginTop = '10px';
            contenedor.style.marginBottom = '10px';
            break;
          case 'inline':
            // Imagen en línea con el texto (como carácter)
            contenedor.style.display = 'inline-block';
            contenedor.style.verticalAlign = 'middle';
            break;
        }
      };
      
      window.moverImagenEnTexto = function(direccion) {
        if (!window.imagenSeleccionada) return;
        const contenedor = window.imagenSeleccionada.parentElement;
        const parent = contenedor.parentElement;
        
        if (direccion === 'arriba') {
          // Encontrar el elemento anterior (puede ser p, div, etc.)
          let anterior = contenedor.previousElementSibling;
          while (anterior && anterior.classList && anterior.classList.contains('controles-imagen')) {
            anterior = anterior.previousElementSibling;
          }
          if (anterior) {
            parent.insertBefore(contenedor, anterior);
          }
        } else if (direccion === 'abajo') {
          // Encontrar el elemento siguiente
          let siguiente = contenedor.nextElementSibling;
          while (siguiente && siguiente.classList && (siguiente.classList.contains('controles-imagen') || siguiente.classList.contains('resize-handle'))) {
            siguiente = siguiente.nextElementSibling;
          }
          if (siguiente) {
            // Insertar después del siguiente
            if (siguiente.nextElementSibling) {
              parent.insertBefore(contenedor, siguiente.nextElementSibling);
            } else {
              parent.appendChild(contenedor);
            }
          }
        }
        
        // Re-mostrar controles
        setTimeout(() => {
          window.mostrarControlesImagen(window.imagenSeleccionada);
        }, 50);
      };
      
      window.cambiarZIndex = function(direccion) {
        if (!window.imagenSeleccionada) return;
        const contenedor = window.imagenSeleccionada.parentElement;
        contenedor.style.position = 'relative';
        contenedor.style.zIndex = direccion === 'delante' ? '100' : '-1';
      };
      
      window.cambiarOpacidad = function(delta) {
        if (!window.imagenSeleccionada) return;
        const opacidadActual = parseFloat(window.imagenSeleccionada.style.opacity || '1');
        const nuevaOpacidad = Math.max(0.1, Math.min(1, opacidadActual + delta));
        window.imagenSeleccionada.style.opacity = nuevaOpacidad;
      };
      
      window.iniciarRecorte = function() {
        if (!window.imagenSeleccionada) return;
        
        const porcentaje = prompt('¿Qué porcentaje deseas recortar de cada lado?\nEjemplo: 10 (recorta 10% de cada lado)\n0-50:', '10');
        
        if (porcentaje === null) return;
        
        const pct = Math.max(0, Math.min(50, parseFloat(porcentaje) || 10));
        
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = window.imagenSeleccionada;
        
        // Crear imagen temporal para cargar
        const tempImg = new Image();
        tempImg.onload = function() {
          const cropPct = pct / 100;
          const cropX = tempImg.width * cropPct;
          const cropY = tempImg.height * cropPct;
          const cropWidth = tempImg.width * (1 - cropPct * 2);
          const cropHeight = tempImg.height * (1 - cropPct * 2);
          
          canvas.width = cropWidth;
          canvas.height = cropHeight;
          
          ctx.drawImage(tempImg, cropX, cropY, cropWidth, cropHeight, 0, 0, cropWidth, cropHeight);
          
          img.src = canvas.toDataURL();
          img.style.width = 'auto';
          img.style.height = 'auto';
          
          alert('✂️ Imagen recortada exitosamente');
        };
        tempImg.src = img.src;
      };
      
      
      window.eliminarImagen = async function() {
        if (!window.imagenSeleccionada || !confirm('¿Eliminar esta imagen?')) return;
        
        const img = window.imagenSeleccionada;
        const src = img.src;
        
        // Intentar eliminar del servidor si es una imagen subida
        if (src.includes('/api/imagen/')) {
          try {
            // Extraer la ruta de la imagen
            const rutaMatch = src.match(/\/api\/imagen\/(.+)$/);
            if (rutaMatch) {
              const rutaImagen = rutaMatch[1];
              const apiUrl = src.substring(0, src.indexOf('/api/imagen'));
              
              const response = await fetch(`${apiUrl}/api/imagen/${rutaImagen}`, {
                method: 'DELETE'
              });
              
              if (response.ok) {
                console.log('🗑️ Imagen eliminada del servidor');
              } else {
                console.warn('⚠️ No se pudo eliminar imagen del servidor');
              }
            }
          } catch (error) {
            console.error('Error eliminando imagen del servidor:', error);
          }
        }
        
        // Eliminar del DOM (incluyendo wrapper si existe)
        const contenedor = img.parentElement;
        const wrapper = contenedor.parentElement;
        if (wrapper && wrapper.classList.contains('imagen-wrapper')) {
          wrapper.remove();
        } else {
          contenedor.remove();
        }
        
        window.imagenSeleccionada = null;
      };
      
      // ===== FUNCIÓN PARA SINCRONIZAR CONTENIDO DESPUÉS DE DRAG & DROP =====
      const sincronizarContenido = () => {
        const editor = document.querySelector('.editor-html-simple');
        if (editor && editorRef.current) {
          // Clonar el contenido para limpiarlo
          const contenidoLimpio = editor.cloneNode(true);
          // Remover controles de elementos antes de guardar
          contenidoLimpio.querySelectorAll('.elemento-controles').forEach(c => c.remove());
          contenidoLimpio.querySelectorAll('.elemento-con-controles').forEach(el => {
            el.classList.remove('elemento-con-controles');
          });
          // Remover indicadores de drop
          contenidoLimpio.querySelectorAll('.indicador-drop-toggle, .indicador-drop-elemento, .indicador-drop-imagen').forEach(ind => ind.remove());
          
          setContenidoNota(contenidoLimpio.innerHTML);
          console.log('🔄 Contenido sincronizado después de drag & drop');
        }
      };
      
      // Hacer la función accesible globalmente para los handlers
      window.sincronizarContenidoEditor = sincronizarContenido;
      
      // ===== SISTEMA UNIFICADO DE CONTROLES DE ELEMENTOS =====
      // Agregar controles (drag handle + delete) a todos los elementos editables
      const inicializarControlesElementos = () => {
        const editor = document.querySelector('.editor-html-simple');
        if (!editor) {
          console.log('⚠️ Editor no encontrado para inicializar controles');
          return;
        }
        
        // Selectores de elementos que pueden tener controles
        const selectoresElementos = [
          'p:not(.checklist-item)',
          'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
          'ul', 'ol',
          'blockquote',
          '.tabla-contenedor',
          '.checklist-container'
        ];
        
        // Buscar solo elementos directos del editor (no anidados)
        selectoresElementos.forEach(selector => {
          const elementos = editor.querySelectorAll(`:scope > ${selector}`);
          elementos.forEach(el => {
            // No agregar a elementos vacíos o que ya tienen controles
            if (el.querySelector('.elemento-controles')) return;
            if (el.textContent.trim() === '' && !el.querySelector('table') && !el.querySelector('.checklist-item')) return;
            
            // Crear contenedor de controles
            const controles = document.createElement('div');
            controles.className = 'elemento-controles';
            controles.setAttribute('contenteditable', 'false');
            
            // Botón de arrastrar
            const dragHandle = document.createElement('button');
            dragHandle.type = 'button';
            dragHandle.className = 'elemento-drag-handle';
            dragHandle.setAttribute('draggable', 'true');
            dragHandle.setAttribute('title', 'Arrastrar para mover');
            dragHandle.textContent = '⠿';
            
            // Botón de eliminar
            const deleteBtn = document.createElement('button');
            deleteBtn.type = 'button';
            deleteBtn.className = 'elemento-delete-btn';
            deleteBtn.setAttribute('title', 'Eliminar elemento');
            deleteBtn.textContent = '🗑';
            deleteBtn.onclick = (e) => {
              e.preventDefault();
              e.stopPropagation();
              if (confirm('¿Eliminar este elemento?')) {
                el.remove();
              }
            };
            
            controles.appendChild(dragHandle);
            controles.appendChild(deleteBtn);
            
            // Agregar clase y controles al elemento
            el.classList.add('elemento-con-controles');
            el.insertBefore(controles, el.firstChild);
          });
        });
        
        // También inicializar toggles existentes con drag handles y botón eliminar
        const toggles = editor.querySelectorAll('.toggle-heading');
        console.log(`📝 Inicializando ${toggles.length} toggle headings existentes`);
        
        toggles.forEach(toggle => {
          const summary = toggle.querySelector('.toggle-summary');
          if (!summary) return;
          
          // Agregar drag handle si no existe
          if (!summary.querySelector('.toggle-drag-handle')) {
            const dragHandle = document.createElement('span');
            dragHandle.className = 'toggle-drag-handle';
            dragHandle.setAttribute('contenteditable', 'false');
            dragHandle.setAttribute('draggable', 'true');
            dragHandle.setAttribute('title', 'Arrastrar para mover');
            dragHandle.textContent = '☰';
            summary.insertBefore(dragHandle, summary.firstChild);
            console.log('✅ Drag handle agregado a toggle:', toggle.dataset.toggleId);
          }
          
          // Agregar botón eliminar si no existe
          if (!summary.querySelector('.toggle-delete-btn')) {
            const deleteBtn = document.createElement('button');
            deleteBtn.type = 'button';
            deleteBtn.className = 'toggle-delete-btn';
            deleteBtn.setAttribute('contenteditable', 'false');
            deleteBtn.setAttribute('title', 'Eliminar toggle');
            deleteBtn.textContent = '🗑️';
            deleteBtn.onclick = (e) => {
              e.preventDefault();
              e.stopPropagation();
              if (confirm('¿Eliminar este toggle?')) {
                toggle.remove();
              }
            };
            summary.appendChild(deleteBtn);
            console.log('✅ Botón eliminar agregado a toggle:', toggle.dataset.toggleId);
          }
        });
      };
      
      // Ejecutar inicialización después de que se cargue el contenido
      setTimeout(inicializarControlesElementos, 100);
      setTimeout(inicializarControlesElementos, 500);
      
      // ===== SISTEMA DE DRAG & DROP PARA IMÁGENES =====
      // Configurar drag & drop en el editor
      const editor = document.querySelector('.editor-html-simple');
      if (editor) {
        // Indicador visual de dónde se soltará la imagen
        let indicadorDrop = null;
        let imagenArrastrada = null;
        
        const crearIndicadorDrop = () => {
          if (!indicadorDrop) {
            indicadorDrop = document.createElement('div');
            indicadorDrop.className = 'indicador-drop-imagen';
            indicadorDrop.innerHTML = '📍 Soltar imagen aquí';
          }
          return indicadorDrop;
        };
        
        // Encontrar el elemento más cercano donde soltar
        const encontrarPuntoInsercion = (y) => {
          const elementos = editor.querySelectorAll('p, div:not(.imagen-contenedor):not(.controles-imagen):not(.resize-handle):not(.indicador-drop-imagen), h1, h2, h3, h4, h5, h6, ul, ol, blockquote, .imagen-contenedor');
          let mejorElemento = null;
          let mejorDistancia = Infinity;
          let insertarAntes = true;
          
          elementos.forEach(el => {
            if (el === indicadorDrop || el === imagenArrastrada?.parentElement) return;
            
            const rect = el.getBoundingClientRect();
            const centroY = rect.top + rect.height / 2;
            const distancia = Math.abs(y - centroY);
            
            if (distancia < mejorDistancia) {
              mejorDistancia = distancia;
              mejorElemento = el;
              insertarAntes = y < centroY;
            }
          });
          
          return { elemento: mejorElemento, antes: insertarAntes };
        };
        
        // Manejar dragstart en contenedores de imagen
        editor.addEventListener('dragstart', (e) => {
          const contenedor = e.target.closest('.imagen-contenedor');
          if (contenedor) {
            imagenArrastrada = contenedor.querySelector('img');
            contenedor.classList.add('arrastrando');
            e.dataTransfer.effectAllowed = 'move';
            e.dataTransfer.setData('text/plain', 'imagen');
            
            // Ocultar controles mientras se arrastra
            document.querySelectorAll('.controles-imagen').forEach(c => c.style.display = 'none');
            document.querySelectorAll('.resize-handle').forEach(h => h.style.display = 'none');
          }
        });
        
        editor.addEventListener('dragover', (e) => {
          if (!imagenArrastrada) return;
          e.preventDefault();
          e.dataTransfer.dropEffect = 'move';
          
          const indicador = crearIndicadorDrop();
          const { elemento, antes } = encontrarPuntoInsercion(e.clientY);
          
          if (elemento && elemento !== indicador) {
            if (antes) {
              elemento.parentNode.insertBefore(indicador, elemento);
            } else {
              if (elemento.nextSibling) {
                elemento.parentNode.insertBefore(indicador, elemento.nextSibling);
              } else {
                elemento.parentNode.appendChild(indicador);
              }
            }
          }
        });
        
        editor.addEventListener('dragleave', (e) => {
          // Solo remover si salimos del editor completamente
          if (!editor.contains(e.relatedTarget)) {
            if (indicadorDrop && indicadorDrop.parentNode) {
              indicadorDrop.remove();
            }
          }
        });
        
        editor.addEventListener('drop', (e) => {
          // Solo procesar si hay una imagen arrastrándose
          if (!imagenArrastrada) return;
          
          e.preventDefault();
          
          const contenedor = imagenArrastrada.parentElement;
          
          if (indicadorDrop && indicadorDrop.parentNode) {
            // Insertar el contenedor donde está el indicador
            indicadorDrop.parentNode.insertBefore(contenedor, indicadorDrop);
            indicadorDrop.remove();
          }
          
          contenedor.classList.remove('arrastrando');
          
          // Mostrar controles de nuevo
          setTimeout(() => {
            window.mostrarControlesImagen(imagenArrastrada);
            // Sincronizar contenido después del drop
            if (window.sincronizarContenidoEditor) {
              window.sincronizarContenidoEditor();
            }
          }, 100);
          
          imagenArrastrada = null;
        });
        
        editor.addEventListener('dragend', (e) => {
          const contenedor = e.target.closest('.imagen-contenedor');
          if (contenedor) {
            contenedor.classList.remove('arrastrando');
          }
          
          if (indicadorDrop && indicadorDrop.parentNode) {
            indicadorDrop.remove();
          }
          
          // Restaurar visibilidad de controles
          document.querySelectorAll('.controles-imagen').forEach(c => c.style.display = '');
          document.querySelectorAll('.resize-handle').forEach(h => h.style.display = '');
          
          imagenArrastrada = null;
        });
        
        // ===== SISTEMA DE DRAG & DROP PARA TOGGLE HEADINGS =====
        let toggleArrastrado = null;
        let indicadorDropToggle = null;
        let ultimaPosicionToggle = null; // Para evitar parpadeo
        
        const crearIndicadorDropToggle = () => {
          if (!indicadorDropToggle) {
            indicadorDropToggle = document.createElement('div');
            indicadorDropToggle.className = 'indicador-drop-toggle';
            indicadorDropToggle.innerHTML = '📍 Soltar toggle aquí';
          }
          return indicadorDropToggle;
        };
        
        const limpiarIndicadorToggle = () => {
          if (indicadorDropToggle && indicadorDropToggle.parentNode) {
            indicadorDropToggle.remove();
          }
          indicadorDropToggle = null;
          ultimaPosicionToggle = null;
        };
        
        // Encontrar el punto de inserción para toggle
        const encontrarPuntoInsercionToggle = (y, targetContent = null) => {
          const selector = targetContent 
            ? '.toggle-heading, p, div:not(.toggle-heading):not(.indicador-drop-toggle), h1, h2, h3, h4, h5, h6, ul, ol, blockquote'
            : '.toggle-heading, p, div:not(.indicador-drop-toggle), h1, h2, h3, h4, h5, h6, ul, ol, blockquote';
          
          const container = targetContent || editor;
          const elementos = container.querySelectorAll(selector);
          let mejorElemento = null;
          let mejorDistancia = Infinity;
          let insertarAntes = true;
          
          elementos.forEach(el => {
            if (el === indicadorDropToggle || el === toggleArrastrado || el.contains(toggleArrastrado)) return;
            
            const rect = el.getBoundingClientRect();
            const centroY = rect.top + rect.height / 2;
            const distancia = Math.abs(y - centroY);
            
            if (distancia < mejorDistancia) {
              mejorDistancia = distancia;
              mejorElemento = el;
              insertarAntes = y < centroY;
            }
          });
          
          return { elemento: mejorElemento, antes: insertarAntes };
        };
        
        // Manejar dragstart en toggle headings
        editor.addEventListener('dragstart', (e) => {
          const dragHandle = e.target.closest('.toggle-drag-handle');
          const contenedor = e.target.closest('.imagen-contenedor');
          
          // Si es una imagen, dejar que el handler de imagen lo maneje
          if (contenedor) return;
          
          // Solo permitir arrastrar desde el drag handle
          if (dragHandle) {
            const toggle = dragHandle.closest('.toggle-heading');
            if (toggle) {
              e.stopPropagation();
              toggleArrastrado = toggle;
              toggle.classList.add('toggle-arrastrando');
              e.dataTransfer.effectAllowed = 'move';
              e.dataTransfer.setData('text/plain', 'toggle');
              e.dataTransfer.setData('text/toggle-id', toggle.dataset.toggleId || '');
              console.log('🔄 Iniciando arrastre de toggle:', toggle.dataset.toggleId);
            }
          }
        });
        
        // Manejar dragover para toggle
        editor.addEventListener('dragover', (e) => {
          if (!toggleArrastrado) return;
          e.preventDefault();
          e.stopPropagation();
          e.dataTransfer.dropEffect = 'move';
          
          const indicador = crearIndicadorDropToggle();
          
          // Verificar si estamos sobre partes específicas de un toggle
          const targetToggle = e.target.closest('.toggle-heading');
          const targetContent = e.target.closest('.toggle-content');
          const targetSummary = e.target.closest('.toggle-summary');
          
          let nuevaPosicion = null;
          let elementoReferencia = null;
          let insertarAntes = true;
          
          // Si estamos sobre el summary/título de un toggle, colocar antes o después del toggle completo
          if (targetSummary && targetToggle && targetToggle !== toggleArrastrado && !toggleArrastrado.contains(targetToggle)) {
            document.querySelectorAll('.toggle-drop-target').forEach(el => el.classList.remove('toggle-drop-target'));
            
            const rect = targetToggle.getBoundingClientRect();
            const mitad = rect.top + rect.height / 2;
            insertarAntes = e.clientY < mitad;
            
            nuevaPosicion = `summary_${targetToggle.dataset.toggleId}_${insertarAntes ? 'antes' : 'despues'}`;
            elementoReferencia = targetToggle;
          }
          // Si estamos sobre el contenido expandido de un toggle, permitir anidación
          else if (targetContent && targetToggle && targetToggle !== toggleArrastrado && !toggleArrastrado.contains(targetToggle)) {
            targetContent.classList.add('toggle-drop-target');
            
            const { elemento, antes } = encontrarPuntoInsercionToggle(e.clientY, targetContent);
            
            if (elemento && elemento !== indicador && !elemento.classList.contains('indicador-drop-toggle')) {
              nuevaPosicion = `content_${targetToggle.dataset.toggleId}_${elemento.dataset?.toggleId || elemento.tagName}_${antes ? 'antes' : 'despues'}`;
              elementoReferencia = elemento;
              insertarAntes = antes;
            } else if (!elemento) {
              nuevaPosicion = `content_${targetToggle.dataset.toggleId}_final`;
              elementoReferencia = targetContent;
              insertarAntes = false; // appendChild
            }
          } else {
            // Fuera de cualquier toggle - insertar en el editor principal
            document.querySelectorAll('.toggle-drop-target').forEach(el => el.classList.remove('toggle-drop-target'));
            
            const { elemento, antes } = encontrarPuntoInsercionToggle(e.clientY);
            
            if (elemento && elemento !== indicador && !toggleArrastrado.contains(elemento) && !elemento.classList.contains('indicador-drop-toggle')) {
              nuevaPosicion = `editor_${elemento.dataset?.toggleId || elemento.tagName}_${antes ? 'antes' : 'despues'}`;
              elementoReferencia = elemento;
              insertarAntes = antes;
            }
          }
          
          // Solo mover el indicador si la posición cambió
          if (nuevaPosicion && nuevaPosicion !== ultimaPosicionToggle && elementoReferencia) {
            ultimaPosicionToggle = nuevaPosicion;
            
            if (insertarAntes) {
              elementoReferencia.parentNode.insertBefore(indicador, elementoReferencia);
            } else if (elementoReferencia.classList?.contains('toggle-content')) {
              // appendChild al contenido
              elementoReferencia.appendChild(indicador);
            } else {
              if (elementoReferencia.nextSibling && elementoReferencia.nextSibling !== indicador) {
                elementoReferencia.parentNode.insertBefore(indicador, elementoReferencia.nextSibling);
              } else if (!elementoReferencia.nextSibling) {
                elementoReferencia.parentNode.appendChild(indicador);
              }
            }
          }
        });
        
        // Manejar dragleave para toggle
        editor.addEventListener('dragleave', (e) => {
          if (!toggleArrastrado) return;
          
          const targetContent = e.target.closest('.toggle-content');
          if (targetContent && !targetContent.contains(e.relatedTarget)) {
            targetContent.classList.remove('toggle-drop-target');
          }
          
          if (!editor.contains(e.relatedTarget)) {
            limpiarIndicadorToggle();
          }
        });
        
        // Manejar drop para toggle
        editor.addEventListener('drop', (e) => {
          console.log('📦 Evento drop - toggleArrastrado:', !!toggleArrastrado);
          if (!toggleArrastrado) return;
          e.preventDefault();
          e.stopPropagation();
          
          console.log('📦 Procesando drop de toggle');
          document.querySelectorAll('.toggle-drop-target').forEach(el => el.classList.remove('toggle-drop-target'));
          
          if (indicadorDropToggle && indicadorDropToggle.parentNode) {
            console.log('✅ Insertando toggle en posición del indicador');
            indicadorDropToggle.parentNode.insertBefore(toggleArrastrado, indicadorDropToggle);
          }
          
          limpiarIndicadorToggle();
          toggleArrastrado.classList.remove('toggle-arrastrando');
          toggleArrastrado = null;
          
          // Sincronizar contenido después del drop
          setTimeout(() => {
            if (window.sincronizarContenidoEditor) {
              window.sincronizarContenidoEditor();
            }
          }, 100);
        });
        
        // Limpiar al terminar drag de toggle
        editor.addEventListener('dragend', (e) => {
          if (toggleArrastrado) {
            toggleArrastrado.classList.remove('toggle-arrastrando');
            toggleArrastrado = null;
          }
          
          document.querySelectorAll('.toggle-drop-target').forEach(el => el.classList.remove('toggle-drop-target'));
          limpiarIndicadorToggle();
        });
        
        // ===== SISTEMA DE DRAG & DROP PARA ELEMENTOS GENERALES =====
        let elementoArrastrado = null;
        let indicadorDropElemento = null;
        
        const crearIndicadorDropElemento = () => {
          // Reutilizar el indicador existente si existe
          if (indicadorDropElemento && indicadorDropElemento.parentNode) {
            return indicadorDropElemento;
          }
          // Limpiar cualquier indicador huérfano
          document.querySelectorAll('.indicador-drop-elemento').forEach(ind => ind.remove());
          indicadorDropElemento = document.createElement('div');
          indicadorDropElemento.className = 'indicador-drop-elemento';
          indicadorDropElemento.innerHTML = '📍 Soltar aquí';
          return indicadorDropElemento;
        };
        
        const limpiarIndicadorElemento = () => {
          document.querySelectorAll('.indicador-drop-elemento').forEach(ind => ind.remove());
          indicadorDropElemento = null;
        };
        
        // Encontrar punto de inserción para elemento general
        const encontrarPuntoInsercionElemento = (y) => {
          const elementos = editor.querySelectorAll(':scope > p, :scope > h1, :scope > h2, :scope > h3, :scope > h4, :scope > h5, :scope > h6, :scope > ul, :scope > ol, :scope > blockquote, :scope > .tabla-contenedor, :scope > .checklist-container, :scope > .toggle-heading, :scope > .imagen-contenedor');
          let mejorElemento = null;
          let mejorDistancia = Infinity;
          let insertarAntes = true;
          
          elementos.forEach(el => {
            if (el.classList.contains('indicador-drop-elemento') || el === elementoArrastrado) return;
            
            const rect = el.getBoundingClientRect();
            const centroY = rect.top + rect.height / 2;
            const distancia = Math.abs(y - centroY);
            
            if (distancia < mejorDistancia) {
              mejorDistancia = distancia;
              mejorElemento = el;
              insertarAntes = y < centroY;
            }
          });
          
          return { elemento: mejorElemento, antes: insertarAntes };
        };
        
        // Dragstart para elementos con controles
        editor.addEventListener('dragstart', (e) => {
          const dragHandle = e.target.closest('.elemento-drag-handle');
          if (!dragHandle) return;
          
          const elementoPadre = dragHandle.closest('.elemento-con-controles');
          if (elementoPadre) {
            e.stopPropagation();
            elementoArrastrado = elementoPadre;
            elementoPadre.classList.add('elemento-arrastrando');
            e.dataTransfer.effectAllowed = 'move';
            e.dataTransfer.setData('text/plain', 'elemento');
            console.log('🔄 Iniciando arrastre de elemento:', elementoPadre.tagName);
          }
        });
        
        // Dragover para elementos generales
        editor.addEventListener('dragover', (e) => {
          if (!elementoArrastrado) return;
          e.preventDefault();
          e.stopPropagation();
          e.dataTransfer.dropEffect = 'move';
          
          const indicador = crearIndicadorDropElemento();
          const { elemento, antes } = encontrarPuntoInsercionElemento(e.clientY);
          
          if (elemento && elemento !== elementoArrastrado) {
            if (antes) {
              elemento.parentNode.insertBefore(indicador, elemento);
            } else {
              if (elemento.nextSibling) {
                elemento.parentNode.insertBefore(indicador, elemento.nextSibling);
              } else {
                elemento.parentNode.appendChild(indicador);
              }
            }
          }
        });
        
        // Dragleave para elementos generales
        editor.addEventListener('dragleave', (e) => {
          if (!elementoArrastrado) return;
          
          if (!editor.contains(e.relatedTarget)) {
            limpiarIndicadorElemento();
          }
        });
        
        // Drop para elementos generales
        editor.addEventListener('drop', (e) => {
          if (!elementoArrastrado) return;
          e.preventDefault();
          e.stopPropagation();
          
          console.log('📦 Soltando elemento:', elementoArrastrado.tagName);
          
          if (indicadorDropElemento && indicadorDropElemento.parentNode) {
            indicadorDropElemento.parentNode.insertBefore(elementoArrastrado, indicadorDropElemento);
          }
          
          limpiarIndicadorElemento();
          document.querySelectorAll('.indicador-drop-elemento').forEach(ind => ind.remove());
          
          elementoArrastrado.classList.remove('elemento-arrastrando');
          elementoArrastrado = null;
          
          // Sincronizar contenido después del drop
          setTimeout(() => {
            if (window.sincronizarContenidoEditor) {
              window.sincronizarContenidoEditor();
            }
          }, 100);
        });
        
        // Dragend para elementos generales
        editor.addEventListener('dragend', (e) => {
          if (elementoArrastrado) {
            elementoArrastrado.classList.remove('elemento-arrastrando');
            elementoArrastrado = null;
          }
          
          limpiarIndicadorElemento();
          document.querySelectorAll('.indicador-drop-elemento').forEach(ind => ind.remove());
        });
      }
      
      // Click fuera para deseleccionar
      const clickHandler = (e) => {
        if (!e.target.closest('.imagen-contenedor') && !e.target.closest('.controles-imagen')) {
          document.querySelectorAll('.controles-imagen').forEach(c => c.remove());
          document.querySelectorAll('.resize-handle').forEach(h => h.remove());
          document.querySelectorAll('.imagen-editable.seleccionada').forEach(i => i.classList.remove('seleccionada'));
          window.imagenSeleccionada = null;
        }
      };
      
      document.addEventListener('click', clickHandler);
      
      return () => {
        document.removeEventListener('click', clickHandler);
        document.removeEventListener('mousemove', mouseMoveHandler);
        document.removeEventListener('mouseup', mouseUpHandler);
      };
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [editorNotaAbierto, modoSoloLectura, contenidoNota, notaActual?.id])

  // Cargar prompt del sistema al inicio (solo una vez)
  useEffect(() => {
    const cargarPromptInicial = async () => {
      try {
        console.log('🔄 Cargando prompt del sistema...')
        const promptResp = await fetch(`${API_URL}/api/prompt-personalizado`)
        const promptData = await promptResp.json()
        
        if (promptData.prompt) {
          // Hay un prompt guardado, usarlo
          console.log('✅ Prompt guardado cargado')
          setPromptSistema(promptData.prompt)
        } else {
          // No hay prompt guardado, cargar el template
          console.log('📝 Cargando template predeterminado...')
          const templateResp = await fetch(`${API_URL}/api/prompt-template`)
          const templateData = await templateResp.json()
          setPromptSistema(templateData.template)
          console.log('✅ Template cargado')
        }
      } catch (error) {
        console.error('❌ Error cargando prompt inicial:', error)
        // Si hay error, cargar un prompt por defecto simple
        setPromptSistema('Eres un profesor universitario experto. Crea preguntas basadas en:\n{contenido}\n\nGenera {total_preguntas} preguntas en formato JSON.')
      }
    }
    
    cargarPromptInicial()
  }, [])  // Solo se ejecuta una vez al montar el componente

  // Cargar configuración del modelo al inicio
  useEffect(() => {
    cargarConfiguracion()
  }, [])  // Solo una vez al montar
  
  // Cargar carpetas de exámenes (estructura paralela)
  const cargarCarpetasExamenes = async (ruta = '') => {
    setLoading(true)
    try {
      console.log('📂 Cargando carpetas de exámenes, ruta:', ruta)
      const response = await fetch(`${API_URL}/api/examenes/carpetas?ruta=${encodeURIComponent(ruta)}`)
      const data = await response.json()
      
      console.log('📊 Datos recibidos del backend:', data)
      console.log('   - Carpetas:', data.carpetas?.length || 0)
      console.log('   - Exámenes completados:', data.examenes_completados?.length || 0)
      console.log('   - Exámenes en progreso:', data.examenes_progreso?.length || 0)
      console.log('   - Exámenes en progreso global:', data.examenes_progreso_global?.length || 0)
      
      setCarpetasExamenes(data.carpetas || [])
      setExamenesCompletados(data.examenes_completados || [])
      setExamenesProgreso(data.examenes_progreso || [])
      setExamenesProgresoGlobal(data.examenes_progreso_global || [])
      setRutaActualExamenes(ruta)
      
      console.log('✅ Estado actualizado con los datos recibidos')
    } catch (error) {
      console.error('Error cargando exámenes:', error)
      setMensaje({
        tipo: 'error',
        texto: '❌ Error al cargar exámenes'
      })
    } finally {
      setLoading(false)
    }
  }

  // Cargar contenido de carpeta
  const cargarCarpeta = async (ruta = '') => {
    setLoading(true)
    try {
      const response = await fetch(`${API_URL}/api/carpetas?ruta=${encodeURIComponent(ruta)}`)
      const data = await response.json()
      setCarpetas(data.carpetas || [])
      setDocumentos(data.documentos || [])
      setRutaActual(ruta)
      // Guardar última carpeta visitada en localStorage
      localStorage.setItem('ultimaCarpetaCursos', ruta)
    } catch (error) {
      console.error('Error al cargar carpeta:', error)
      setMensaje({
        tipo: 'error',
        texto: `❌ Error al cargar carpeta: ${error.message}`
      })
    } finally {
      setLoading(false)
    }
  }

  // Crear carpeta - Ahora abre el modal de jerarquías
  const crearCarpeta = () => {
    // Inicializar jerarquía vacía
    setJerarquiaActual([])
    setNodoEditando(null)
    setNombreNuevoNodo('')
    setTipoNodoSeleccionado('plataforma')
    setModalJerarquiaAbierto(true)
  }

  // ========== FUNCIONES PARA SISTEMA DE JERARQUÍAS ==========
  
  // Agregar un nuevo nodo a la jerarquía
  const agregarNodoJerarquia = () => {
    if (!nombreNuevoNodo.trim()) return
    
    const tipoInfo = TIPOS_JERARQUIA.find(t => t.id === tipoNodoSeleccionado)
    const nuevoNodo = {
      id: Date.now().toString(),
      tipo: tipoNodoSeleccionado,
      nombre: nombreNuevoNodo.trim(),
      emoji: tipoInfo?.emoji || '📁',
      color: tipoInfo?.color || '#6366f1',
      hijos: [],
      padre: nodoEditando?.id || null,
      estadisticas: {
        examenes: { total: 0, aprobados: 0, reprobados: 0 },
        practicas: { total: 0, completadas: 0 },
        errores: { total: 0, corregidos: 0 },
        flashcards: { total: 0, dominadas: 0 }
      }
    }
    
    if (nodoEditando) {
      // Agregar como hijo del nodo seleccionado
      setJerarquiaActual(prev => {
        const actualizarNodo = (nodos) => {
          return nodos.map(nodo => {
            if (nodo.id === nodoEditando.id) {
              return { ...nodo, hijos: [...nodo.hijos, nuevoNodo] }
            }
            if (nodo.hijos.length > 0) {
              return { ...nodo, hijos: actualizarNodo(nodo.hijos) }
            }
            return nodo
          })
        }
        return actualizarNodo(prev)
      })
    } else {
      // Agregar a la raíz
      setJerarquiaActual(prev => [...prev, nuevoNodo])
    }
    
    setNombreNuevoNodo('')
    // Sugerir el siguiente tipo en la jerarquía
    const indexActual = TIPOS_JERARQUIA.findIndex(t => t.id === tipoNodoSeleccionado)
    if (indexActual < TIPOS_JERARQUIA.length - 1) {
      setTipoNodoSeleccionado(TIPOS_JERARQUIA[indexActual + 1].id)
    }
  }

  // Eliminar un nodo de la jerarquía
  const eliminarNodoJerarquia = (nodoId) => {
    const eliminarRecursivo = (nodos) => {
      return nodos.filter(nodo => {
        if (nodo.id === nodoId) return false
        if (nodo.hijos.length > 0) {
          nodo.hijos = eliminarRecursivo(nodo.hijos)
        }
        return true
      })
    }
    setJerarquiaActual(prev => eliminarRecursivo(prev))
    if (nodoEditando?.id === nodoId) {
      setNodoEditando(null)
    }
  }

  // Crear las carpetas de la jerarquía en el sistema de archivos
  const crearCarpetasDesdeJerarquia = async () => {
    if (jerarquiaActual.length === 0) {
      setMensaje({ tipo: 'error', texto: '❌ Agrega al menos un elemento a la jerarquía' })
      return
    }

    setLoading(true)
    let carpetasCreadas = 0
    let errores = []

    // Función recursiva para crear carpetas anidadas
    const crearRecursivo = async (nodos, rutaPadre) => {
      for (const nodo of nodos) {
        try {
          const tipoInfo = TIPOS_JERARQUIA.find(t => t.id === nodo.tipo)
          // Incluir emoji + tipo + nombre para mejor organización
          const nombreCarpeta = `${nodo.emoji} ${tipoInfo?.nombre || ''} - ${nodo.nombre}`
          const response = await fetch(`${API_URL}/api/carpetas`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ 
              ruta_padre: rutaPadre, 
              nombre: nombreCarpeta,
              metadata: {
                tipo_jerarquia: nodo.tipo,
                estadisticas: nodo.estadisticas,
                color: nodo.color
              }
            })
          })

          const data = await response.json()
          if (data.success) {
            carpetasCreadas++
            // Crear subcarpetas recursivamente DENTRO de esta carpeta
            if (nodo.hijos.length > 0) {
              // Usar backslash para Windows, construir ruta completa
              const nuevaRuta = rutaPadre 
                ? `${rutaPadre}\\${nombreCarpeta}` 
                : nombreCarpeta
              await crearRecursivo(nodo.hijos, nuevaRuta)
            }
          } else {
            errores.push(`${nodo.nombre}: ${data.error || 'Error desconocido'}`)
          }
        } catch (error) {
          errores.push(`${nodo.nombre}: ${error.message}`)
        }
      }
    }

    await crearRecursivo(jerarquiaActual, rutaActual)

    setLoading(false)
    setModalJerarquiaAbierto(false)

    if (errores.length > 0) {
      setMensaje({
        tipo: 'warning',
        texto: `⚠️ Se crearon ${carpetasCreadas} carpetas. Errores: ${errores.slice(0, 3).join(', ')}${errores.length > 3 ? '...' : ''}`
      })
    } else {
      setMensaje({
        tipo: 'success',
        texto: `✅ Jerarquía creada: ${carpetasCreadas} carpetas`
      })
    }

    cargarCarpeta(rutaActual)
  }

  // Renderizar la vista previa del árbol de jerarquía (estilo texto como en terminal)
  const renderizarArbolJerarquia = (nodos, nivel = 0, prefijo = '') => {
    return nodos.map((nodo, index) => {
      const esUltimo = index === nodos.length - 1
      const tipoInfo = TIPOS_JERARQUIA.find(t => t.id === nodo.tipo)
      
      // Construir las líneas del árbol según el nivel
      let lineaActual = ''
      let prefijoHijos = ''
      
      if (nivel === 0) {
        // Elementos raíz: sin línea, pero los hijos tendrán prefijo vacío
        lineaActual = ''
        prefijoHijos = ''
      } else {
        // Elementos hijos: mostrar líneas de conexión
        lineaActual = esUltimo ? '└── ' : '├── '
        prefijoHijos = prefijo + (esUltimo ? '    ' : '│   ')
      }
      
      return (
        <div key={nodo.id} className="jerarquia-nodo-container">
          <div 
            className={`jerarquia-nodo ${nodoEditando?.id === nodo.id ? 'activo seleccionado' : ''}`}
            onClick={() => setNodoEditando(nodoEditando?.id === nodo.id ? null : nodo)}
            title={nodoEditando?.id === nodo.id 
              ? `✓ Seleccionado - Los nuevos elementos se agregarán como hijos de "${nodo.nombre}"` 
              : `Click para agregar hijos dentro de "${nodo.nombre}"`}
          >
            <span className="jerarquia-prefijo">
              {prefijo}{lineaActual}
            </span>
            <span className="jerarquia-emoji">{nodo.emoji}</span>
            <span className="jerarquia-nombre">
              <strong>{tipoInfo?.nombre}:</strong> {nodo.nombre}
            </span>
            <span className="jerarquia-tipo-badge" style={{ backgroundColor: nodo.color }}>
              {tipoInfo?.nombre}
            </span>
            <button 
              className="btn-eliminar-nodo"
              onClick={(e) => { e.stopPropagation(); eliminarNodoJerarquia(nodo.id) }}
              title="Eliminar este nodo y sus hijos"
            >
              ✕
            </button>
          </div>
          {nodo.hijos.length > 0 && (
            <div className="jerarquia-hijos">
              {renderizarArbolJerarquia(nodo.hijos, nivel + 1, nivel === 0 ? '' : prefijoHijos)}
            </div>
          )}
        </div>
      )
    })
  }

  // Crear carpeta simple (sin jerarquía)
  const crearCarpetaSimple = async (nombre) => {
    if (!nombre?.trim()) return

    try {
      const response = await fetch(`${API_URL}/api/carpetas`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          ruta_padre: rutaActual, 
          nombre: nombre.trim() 
        })
      })

      const data = await response.json()
      if (data.success) {
        setMensaje({
          tipo: 'success',
          texto: `✅ Carpeta "${nombre}" creada`
        })
        setModalJerarquiaAbierto(false)
        cargarCarpeta(rutaActual)
      } else {
        setMensaje({
          tipo: 'error',
          texto: `❌ ${data.error || 'Error al crear carpeta'}`
        })
      }
    } catch (error) {
      setMensaje({
        tipo: 'error',
        texto: `❌ ${error.message}`
      })
    }
  }

  // Calcular rendimiento por jerarquía de carpetas
  const calcularRendimientoJerarquias = async () => {
    try {
      // Obtener todos los datos
      const flashcards = await getDatos('flashcards') || []
      const examenes = await getDatos('examenes') || []
      const practicasData = await getDatos('practicas') || []
      const notas = await getDatos('notas') || []
      
      // 🔥 EXTRAER ERRORES DE EXÁMENES Y PRÁCTICAS (no de archivo separado)
      // Pasar false para obtener TODOS los errores, no solo los atrasados
      const todosLosItems = [
        ...examenes.map(e => ({ ...e, es_practica: false })),
        ...practicasData.map(p => ({ ...p, es_practica: true }))
      ]
      const errores = extraerErroresDeExamenes(todosLosItems, false) || []
      
      console.log('📊 calcularRendimientoJerarquias - Datos:', {
        errores: errores.length,
        flashcards: flashcards.length,
        examenes: examenes.length,
        practicas: practicasData.length,
        notas: notas.length
      })
      
      const rendimiento = {}
      
      // Función para normalizar ruta
      const normalizarRuta = (ruta) => (ruta || '').replace(/\//g, '\\').replace(/\\\\/g, '\\')
      
      // Función para obtener todas las carpetas padre de una ruta
      const obtenerCarpetasPadre = (ruta) => {
        const partes = normalizarRuta(ruta).split('\\').filter(Boolean)
        const carpetas = []
        let acumulado = ''
        for (const parte of partes) {
          acumulado = acumulado ? `${acumulado}\\${parte}` : parte
          carpetas.push(acumulado)
        }
        return carpetas
      }
      
      // Función para inicializar una carpeta en rendimiento
      const inicializarCarpeta = (carpeta) => {
        if (!rendimiento[carpeta]) {
          const partes = carpeta.split('\\')
          rendimiento[carpeta] = {
            nombre: partes[partes.length - 1] || carpeta,
            nivel: partes.length,
            padre: partes.length > 1 ? partes.slice(0, -1).join('\\') : null,
            errores: { total: 0, corregidos: 0, pendientes: 0 },
            flashcards: { total: 0, dominadas: 0, pendientes: 0, enProgreso: 0 },
            examenes: { total: 0, aprobados: 0, reprobados: 0, puntosTotal: 0, notaPromedio: 0 },
            practicas: { total: 0, completadas: 0, puntosTotal: 0, puntosObtenidos: 0 },
            notas: { total: 0, revisadas: 0 },
            hijos: []
          }
        }
      }
      
      // Procesar errores por carpeta
      errores.forEach(error => {
        // 🔥 USAR carpeta_ruta primero, luego carpeta, luego ruta_documento
        const ruta = normalizarRuta(error.carpeta_ruta || error.carpeta || error.ruta_documento?.split('\\').slice(0, -1).join('\\') || '')
        if (!ruta) return
        
        // Inicializar toda la jerarquía de carpetas
        obtenerCarpetasPadre(ruta).forEach(inicializarCarpeta)
        
        rendimiento[ruta].errores.total++
        // 🔥 USAR estado_error del sistema de repetición espaciada
        if (error.estado_error === 'ok' || error.corregido || error.estado === 'corregido') {
          rendimiento[ruta].errores.corregidos++
        } else {
          rendimiento[ruta].errores.pendientes++
        }
      })
      
      // Procesar flashcards por carpeta
      flashcards.forEach(fc => {
        const ruta = normalizarRuta(fc.carpeta || fc.ruta || '')
        if (!ruta) return
        
        obtenerCarpetasPadre(ruta).forEach(inicializarCarpeta)
        
        rendimiento[ruta].flashcards.total++
        const facilidad = fc.facilidad || 2.5
        const intervalo = fc.intervalo || 1
        
        if (facilidad >= 2.8 && intervalo >= 21) {
          rendimiento[ruta].flashcards.dominadas++
        } else if (intervalo > 1) {
          rendimiento[ruta].flashcards.enProgreso++
        } else {
          rendimiento[ruta].flashcards.pendientes++
        }
      })
      
      // Procesar exámenes por carpeta
      examenes.forEach(ex => {
        const ruta = normalizarRuta(ex.carpeta || ex.ruta || '')
        if (!ruta) return
        
        obtenerCarpetasPadre(ruta).forEach(inicializarCarpeta)
        
        rendimiento[ruta].examenes.total++
        const nota = ex.calificacion || ex.nota || ex.porcentaje || 0
        rendimiento[ruta].examenes.puntosTotal += nota
        
        if (nota >= 60) {
          rendimiento[ruta].examenes.aprobados++
        } else {
          rendimiento[ruta].examenes.reprobados++
        }
      })
      
      // Procesar prácticas por carpeta
      practicasData.forEach(pr => {
        const ruta = normalizarRuta(pr.carpeta || pr.carpeta_ruta || '')
        if (!ruta) return
        
        obtenerCarpetasPadre(ruta).forEach(inicializarCarpeta)
        
        rendimiento[ruta].practicas.total++
        if (pr.completada) {
          rendimiento[ruta].practicas.completadas++
        }
        if (pr.resultado) {
          rendimiento[ruta].practicas.puntosTotal += pr.resultado.puntos_totales || 0
          rendimiento[ruta].practicas.puntosObtenidos += pr.resultado.puntos_obtenidos || 0
        }
      })
      
      // Procesar notas por carpeta
      notas.forEach(nota => {
        const ruta = normalizarRuta(nota.carpeta || '')
        if (!ruta) return
        
        obtenerCarpetasPadre(ruta).forEach(inicializarCarpeta)
        
        rendimiento[ruta].notas.total++
        if (nota.ultimoRepaso || nota.repeticiones > 0) {
          rendimiento[ruta].notas.revisadas++
        }
      })
      
      // Construir jerarquía de hijos
      Object.keys(rendimiento).forEach(carpeta => {
        const r = rendimiento[carpeta]
        
        // Agregar como hijo a su padre
        if (r.padre && rendimiento[r.padre]) {
          if (!rendimiento[r.padre].hijos.includes(carpeta)) {
            rendimiento[r.padre].hijos.push(carpeta)
          }
        }
      })
      
      // Si está activada la suma de hijos, propagar datos de hijos a padres
      if (sumarHijosEnRendimiento) {
        // Función recursiva para sumar datos de los hijos
        const sumarDatosHijos = (carpeta) => {
          const r = rendimiento[carpeta]
          if (!r.hijos || r.hijos.length === 0) return r
          
          // Primero procesar todos los hijos recursivamente
          r.hijos.forEach(hijo => sumarDatosHijos(hijo))
          
          // Luego sumar los datos de los hijos a este nodo
          r.hijos.forEach(hijo => {
            const h = rendimiento[hijo]
            if (h) {
              // Sumar errores
              r.errores.total += h.errores.total
              r.errores.corregidos += h.errores.corregidos
              r.errores.pendientes += h.errores.pendientes
              // Sumar flashcards
              r.flashcards.total += h.flashcards.total
              r.flashcards.dominadas += h.flashcards.dominadas
              r.flashcards.pendientes += h.flashcards.pendientes
              r.flashcards.enProgreso += h.flashcards.enProgreso
              // Sumar exámenes
              r.examenes.total += h.examenes.total
              r.examenes.aprobados += h.examenes.aprobados
              r.examenes.reprobados += h.examenes.reprobados
              r.examenes.puntosTotal += h.examenes.puntosTotal
              // Sumar prácticas
              r.practicas.total += h.practicas.total
              r.practicas.completadas += h.practicas.completadas
              r.practicas.puntosTotal += h.practicas.puntosTotal
              r.practicas.puntosObtenidos += h.practicas.puntosObtenidos
              // Sumar notas
              r.notas.total += h.notas.total
              r.notas.revisadas += h.notas.revisadas
            }
          })
          
          return r
        }
        
        // Procesar solo las carpetas raíz (nivel 1)
        Object.keys(rendimiento)
          .filter(c => rendimiento[c].nivel === 1)
          .forEach(c => sumarDatosHijos(c))
      }
      
      // Calcular porcentajes para todas las carpetas
      Object.keys(rendimiento).forEach(carpeta => {
        const r = rendimiento[carpeta]
        
        // Calcular nota promedio de exámenes
        if (r.examenes.total > 0) {
          r.examenes.notaPromedio = Math.round(r.examenes.puntosTotal / r.examenes.total)
        }
        
        // Calcular porcentaje general
        let totalItems = 0
        let itemsCompletados = 0
        
        totalItems += r.errores.total
        itemsCompletados += r.errores.corregidos
        
        totalItems += r.flashcards.total
        itemsCompletados += r.flashcards.dominadas
        
        totalItems += r.examenes.total
        itemsCompletados += r.examenes.aprobados
        
        totalItems += r.practicas.total
        itemsCompletados += r.practicas.completadas
        
        totalItems += r.notas.total
        itemsCompletados += r.notas.revisadas
        
        r.porcentajeGeneral = totalItems > 0 ? Math.round((itemsCompletados / totalItems) * 100) : 0
        r.totalItems = totalItems
      })
      
      console.log('📊 Rendimiento calculado:', Object.keys(rendimiento).length, 'carpetas')
      setRendimientoJerarquias(rendimiento)
      return rendimiento
    } catch (error) {
      console.error('Error calculando rendimiento:', error)
      return {}
    }
  }

  // Eliminar carpeta
  const eliminarCarpeta = async (ruta, nombre) => {
    const confirmMsg = `¿Eliminar la carpeta "${nombre}"?\n\nSi tiene contenido, se eliminará TODO (carpetas y documentos dentro).`
    if (!confirm(confirmMsg)) return

    try {
      const response = await fetch(`${API_URL}/api/carpetas?ruta=${encodeURIComponent(ruta)}&forzar=true`, {
        method: 'DELETE'
      })

      const data = await response.json()
      if (data.success) {
        setMensaje({
          tipo: 'success',
          texto: '✅ Carpeta eliminada'
        })
        cargarCarpeta(rutaActual)
      }
    } catch (error) {
      setMensaje({
        tipo: 'error',
        texto: `❌ ${error.message}`
      })
    }
  }

  // ========== SISTEMA DE MARCADO DE CARPETAS Y GENERACIÓN MASIVA ==========
  
  // Cargar carpetas marcadas desde localStorage
  useEffect(() => {
    const marcadas = localStorage.getItem('carpetasMarcadas');
    if (marcadas) {
      setCarpetasMarcadas(JSON.parse(marcadas));
    }
  }, []);
  
  // Cargar cursos recientes cuando cambien las carpetas marcadas
  useEffect(() => {
    cargarCursosRecientes();
  }, [carpetasMarcadas]);
  
  // Marcar carpeta con un tipo específico
  const marcarCarpeta = (ruta, tipo) => {
    const nuevasMarcadas = {
      ...carpetasMarcadas,
      [ruta]: {
        tipo,
        fecha: new Date().toISOString()
      }
    };
    setCarpetasMarcadas(nuevasMarcadas);
    localStorage.setItem('carpetasMarcadas', JSON.stringify(nuevasMarcadas));
    setMensaje({
      tipo: 'success',
      texto: `✅ Carpeta marcada como ${tipo.toUpperCase()}`
    });
    // Actualizar carpetas recientes según el tipo
    cargarCarpetasRecientesPorTipo(tipo);
  };
  
  // Cargar carpetas recientes según tipo
  const cargarCarpetasRecientesPorTipo = async (tipo) => {
    try {
      // Filtrar carpetas por tipo
      const carpetasFiltradas = Object.entries(carpetasMarcadas)
        .filter(([ruta, info]) => info.tipo === tipo)
        .sort((a, b) => new Date(b[1].fecha) - new Date(a[1].fecha))
        .slice(0, 5);
      
      // Obtener información detallada de cada carpeta
      const carpetasConInfo = await Promise.all(
        carpetasFiltradas.map(async ([ruta, info]) => {
          try {
            const response = await fetch(`${API_URL}/api/carpetas/info?ruta=${encodeURIComponent(ruta)}`);
            const data = await response.json();
            return {
              ruta,
              nombre: ruta.split('\\').pop() || tipo.charAt(0).toUpperCase() + tipo.slice(1),
              num_documentos: data.num_documentos || 0,
              num_subcarpetas: data.num_subcarpetas || 0,
              fecha: info.fecha
            };
          } catch (error) {
            console.error(`Error cargando info de ${ruta}:`, error);
            return {
              ruta,
              nombre: ruta.split('\\').pop() || tipo.charAt(0).toUpperCase() + tipo.slice(1),
              num_documentos: 0,
              num_subcarpetas: 0,
              fecha: info.fecha
            };
          }
        })
      );
      
      // Actualizar el estado correspondiente
      switch(tipo) {
        case 'curso':
          setCursosRecientes(carpetasConInfo);
          break;
        case 'capitulo':
          setCapitulosRecientes(carpetasConInfo);
          break;
        case 'clase':
          setClasesRecientes(carpetasConInfo);
          break;
        case 'leccion':
          setLeccionesRecientes(carpetasConInfo);
          break;
      }
    } catch (error) {
      console.error(`Error cargando ${tipo}s recientes:`, error);
    }
  };
  
  // Obtener últimos 5 de cada tipo
  const cargarCursosRecientes = async () => {
    await cargarCarpetasRecientesPorTipo('curso');
    await cargarCarpetasRecientesPorTipo('capitulo');
    await cargarCarpetasRecientesPorTipo('clase');
    await cargarCarpetasRecientesPorTipo('leccion');
  };
  
  // ========== FUNCIONES PARA SESIÓN DE ESTUDIO ==========
  
  // Calcular tiempo de descanso óptimo
  const calcularTiempoDescanso = (tiempoTotalMinutos) => {
    // Solo se aplica descanso si la sesión es mayor a 80 minutos
    // El descanso inicia con un contador de 70 minutos
    
    if (tiempoTotalMinutos <= 0 || !isFinite(tiempoTotalMinutos)) {
      // Modo infinito: descanso cada 70 minutos
      return 4200; // 70 minutos en segundos
    }
    
    if (tiempoTotalMinutos > 80) {
      // Sesiones largas (>80 min): descanso cada 70 min
      return 4200; // 70 minutos en segundos
    } else {
      // Sesiones de 80 min o menos: sin descanso
      return tiempoTotalMinutos * 60; // Todo el tiempo sin interrupciones
    }
  };
  
  const iniciarSesion = () => {
    const tiempoEnSegundos = tiempoSesion * 60;
    const tiempoDescansoOptimo = calcularTiempoDescanso(tiempoSesion);
    
    setTiempoRestante(tiempoEnSegundos);
    setTiempoFaseActual(tiempoEnSegundos / 3); // Dividir en 3 fases
    setFaseActual('repaso');
    setSesionActiva(true);
    setTiempoHastaDescanso(tiempoDescansoOptimo); // Calcular según tiempo total
    setIntervaloDescansoInicial(tiempoDescansoOptimo); // Guardar para reiniciar
    setModalSesionAbierto(false);
  };
  
  const detenerSesion = async () => {
    console.log('⏹️ Deteniendo sesión...');
    
    // 🔥 CRÍTICO: Detener PRIMERO sesionActiva para que los useEffect dejen de ejecutarse
    setSesionActiva(false);
    
    // Pequeña espera para que React procese el cambio de estado
    await new Promise(resolve => setTimeout(resolve, 100));
    
    // 1️⃣ Cambiar menú para ocultar indicadores visuales
    setSelectedMenu('inicio');
    
    // 2️⃣ Limpiar estado de sesión completo
    setTiempoRestante(0);
    setFaseActual(null);
    setIndiceFaseActual(0);
    setSesionPausada(false);
    setTiempoHastaDescanso(1500); // Resetear contador de descanso
    setEnDescanso(false);
    setTimestampInicioPausa(null);
    setTiempoFaseActual(0);
    setTiempoTotalEfectivo(0);
    setTiempoAcumuladoEstudio(0);
    setTiempoPausaRestante(0);
    
    // 3️⃣ Limpiar estadísticas
    setEstadisticasSesion({
      erroresReforzados: 0,
      flashcardsRepasadas: 0,
      practicasHechas: 0,
      notasTomadas: 0
    });
    
    // 4️⃣ Limpiar datos de fases
    setErroresActuales([]);
    setFlashcardsSesion([]);
    setDocumentoActual(null);
    setCursoActual(null);
    setNotasVinculadas([]);
    setFasesSesion([]);
    setIndiceErrorActual(0);
    setIndiceFlashcardActual(0);
    
    // 5️⃣ ELIMINAR SESIÓN GUARDADA DEL BACKEND Y LOCALSTORAGE
    try {
      // Eliminar del backend
      const response = await fetch(`${API_URL}/sesion`, {
        method: 'DELETE'
      });
      
      if (response.ok) {
        console.log('✅ Sesión eliminada del backend');
      }
      
      // Eliminar de localStorage
      localStorage.removeItem('examinator_sesion_activa');
      setSesionPersistente(null);
      
      console.log('✅ Sesión detenida y eliminada completamente');
    } catch (error) {
      console.error('❌ Error eliminando sesión al detener:', error);
      // Aunque falle el backend, limpiamos localStorage
      localStorage.removeItem('examinator_sesion_activa');
      setSesionPersistente(null);
    }
  };
  
  const obtenerNombreFase = (fase) => {
    const fases = {
      'calentamiento': 'Calentamiento 🔥',
      'errores': 'Refuerzo de Errores ❌',
      'flashcards': 'Flashcards 🎴',
      'repaso': 'Repaso de Aciertos 🔄',
      'contenido': 'Estudio Nuevo 📚',
      'notas': 'Repaso de Notas 📝',
      'generar_practicas': 'Generar Prácticas 🧑‍💻',
      'cierre': 'Cierre y Resumen ✅',
      'practica': 'Práctica Activa ✍️',
      'examen': 'Evaluación Final 🎯',
      'descanso': 'Descanso 🧘'
    };
    return fases[fase] || fase;
  };
  
  const obtenerSiguienteFase = (faseActual) => {
    const fases = {
      'calentamiento': 'Errores / Flashcards',
      'errores': 'Repaso de Aciertos',
      'flashcards': 'Contenido Nuevo',
      'repaso': 'Notas',
      'contenido': 'Generar Prácticas',
      'notas': 'Cierre',
      'generar_practicas': 'Cierre',
      'practica': 'Evaluación Final',
      'examen': 'Sesión Completa'
    };
    return fases[faseActual] || '';
  };
  
  // Timer de la sesión con descansos automáticos basados en ciencia
  useEffect(() => {
    let intervalo;
    
    // 🔥 CRÍTICO: Solo ejecutar si sesionActiva es true
    if (!sesionActiva) {
      // Si la sesión no está activa, limpiar cualquier intervalo
      if (intervalo) clearInterval(intervalo);
      return;
    }
    
    if (sesionActiva && !sesionPausada && tiempoRestante > 0) {
      intervalo = setInterval(() => {
        setTiempoRestante(prev => {
          if (prev <= 1) {
            // Si estamos en descanso, volver al estudio
            if (enDescanso) {
              setEnDescanso(false);
              setFaseActual(fasesSesion[indiceFaseActual]?.tipo || 'calentamiento');
              const tiempoFase = fasesSesion[indiceFaseActual]?.duracion || 1500; // 25 min por defecto
              setTiempoRestante(tiempoFase);
              setTiempoFaseActual(tiempoFase);
              return tiempoFase;
            }
            
            // Tiempo de fase terminado, avanzar automáticamente
            avanzarFase();
            return 0;
          }
          return prev - 1;
        });
        
        // Solo incrementar tiempo efectivo si no estamos en descanso
        if (!enDescanso) {
          setTiempoTotalEfectivo(prev => prev + 1);
          setTiempoAcumuladoEstudio(prev => {
            const nuevoTiempo = prev + 1;
            
            // Técnica Pomodoro basada en ciencia:
            // - Cada 25 minutos (1500 seg) → 5 min descanso
            // - Cada 2 horas (7200 seg) → 15-20 min descanso
            
            if (nuevoTiempo >= 7200) { // 2 horas
              // Descanso largo (15 min)
              iniciarDescanso(900);
              return 0;
            } else if (nuevoTiempo >= 1500) { // 25 minutos
              // Descanso corto (5 min)
              iniciarDescanso(300);
              return 0;
            }
            
            return nuevoTiempo;
          });
        }
      }, 1000);
    }
    
    // 🔥 CLEANUP: Siempre limpiar el intervalo al desmontar o cuando cambien las dependencias
    return () => {
      if (intervalo) {
        clearInterval(intervalo);
        console.log('⏹️ Timer principal detenido');
      }
    };
  }, [sesionActiva, sesionPausada, tiempoRestante, indiceFaseActual, enDescanso]);
  
  // Contador de tiempo de pausa (cuenta regresiva)
  useEffect(() => {
    let intervaloPausa;
    
    // 🔥 CRÍTICO: Solo ejecutar si sesionActiva es true
    if (!sesionActiva) {
      if (intervaloPausa) clearInterval(intervaloPausa);
      return;
    }
    
    if (sesionPausada && tiempoPausaRestante > 0) {
      intervaloPausa = setInterval(() => {
        setTiempoPausaRestante(prev => {
          if (prev <= 1) {
            // Pausa terminada, reanudar automáticamente
            setSesionPausada(false);
            setMensaje({ tipo: 'info', texto: '⏰ Pausa terminada. ¡Continuemos!' });
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    
    return () => {
      if (intervaloPausa) {
        clearInterval(intervaloPausa);
        console.log('⏹️ Contador de pausa detenido');
      }
    };
  }, [sesionActiva, sesionPausada, tiempoPausaRestante]);
  
  // Contador hasta el próximo descanso (independiente del timer principal)
  useEffect(() => {
    let intervaloDescanso;
    
    // 🔥 CRÍTICO: Solo ejecutar si sesionActiva es true
    if (!sesionActiva) {
      if (intervaloDescanso) clearInterval(intervaloDescanso);
      return;
    }
    
    if (sesionActiva && !sesionPausada && !enDescanso && tiempoHastaDescanso > 0) {
      intervaloDescanso = setInterval(() => {
        setTiempoHastaDescanso(prev => {
          if (prev <= 1) {
            // Tiempo de descanso alcanzado - AUTO-PAUSA
            setSesionPausada(true);
            setTiempoPausaRestante(300); // 5 minutos de pausa
            setMensaje({ 
              tipo: 'warning', 
              texto: '⏸️ ¡Tiempo de descanso! Levántate, estírate, ve al baño. Pausa de 5 minutos.' 
            });
            // Reiniciar contador usando el valor inicial calculado
            return intervaloDescansoInicial;
          }
          return prev - 1;
        });
      }, 1000);
    }
    
    return () => {
      if (intervaloDescanso) {
        clearInterval(intervaloDescanso);
        console.log('⏹️ Contador de descanso detenido');
      }
    };
  }, [sesionActiva, sesionPausada, enDescanso, tiempoHastaDescanso]);

  // Sincronizar estado de la sesión con el backend cada 5 segundos (para red)
  useEffect(() => {
    let intervaloSincronizacion;
    
    // 🔥 CRÍTICO: Solo sincronizar si sesionActiva es true
    if (!sesionActiva) {
      if (intervaloSincronizacion) clearInterval(intervaloSincronizacion);
      return;
    }
    
    if (sesionActiva) {
      intervaloSincronizacion = setInterval(async () => {
        try {
          // Guardar estado ligero para sincronización en red
          const estadoSincronizado = {
            timer: tiempoRestante,
            fase: faseActual,
            pausada: sesionPausada,
            timestamp: Date.now()
          };
          await setSesionActiva(estadoSincronizado);
        } catch (error) {
          console.error('Error sincronizando timer:', error);
        }
      }, 5000); // Cada 5 segundos
    }
    
    // 🔥 CLEANUP: Siempre limpiar el intervalo
    return () => {
      if (intervaloSincronizacion) {
        clearInterval(intervaloSincronizacion);
        console.log('⏹️ Sincronización detenida');
      }
    };
  }, [sesionActiva, tiempoRestante, faseActual, sesionPausada]);
  
  const iniciarDescanso = (duracion) => {
    setEnDescanso(true);
    setFaseActual('descanso');
    setTiempoRestante(duracion);
    setTiempoFaseActual(duracion);
    
    // Notificar al usuario
    setMensaje({
      tipo: 'info',
      texto: `🧘 Momento de descansar ${duracion === 900 ? '15' : '5'} minutos según la ciencia del aprendizaje`
    });
  };
  
  // ============================================
  // 🎯 FUNCIONES DEL MODO SESIÓN DE ESTUDIO
  // ============================================
  
  const abrirConfiguracionSesion = () => {
    setModalConfigSesion(true);
  };
  
  const iniciarSesionEstudio = async () => {
    // Limpiar cualquier sesión persistente anterior antes de iniciar nueva
    await eliminarSesionGuardada();
    
    // Calcular tiempo de descanso óptimo según el tiempo de sesión
    const tiempoDescansoOptimo = modoLibreActivo 
      ? 4200 // Modo libre: 70 min (límite óptimo de atención según estudios científicos)
      : calcularTiempoDescanso(tiempoSesion);
    
    // Si es modo libre, configurar fases sin límite de tiempo
    let fases;
    
    if (modoLibreActivo) {
      // Modo libre: todas las fases disponibles, sin tiempo límite
      fases = [
        { tipo: 'calentamiento', nombre: 'Calentamiento', duracion: Infinity, emoji: '🔥' },
        { tipo: 'errores', nombre: 'Refuerzo de Errores', duracion: Infinity, emoji: '🎯' },
        { tipo: 'flashcards', nombre: 'Flashcards', duracion: Infinity, emoji: '🃏' },
        { tipo: 'contenido', nombre: 'Estudio Nuevo', duracion: Infinity, emoji: '📚' },
        { tipo: 'cierre', nombre: 'Cierre', duracion: Infinity, emoji: '✅' }
      ];
    } else {
      // Modo con tiempo: calcular distribución según prioridad y fases excluidas
      fases = calcularFasesSesion(tiempoSesion, prioridadSesion, fasesExcluidas);
    }
    
    setFasesSesion(fases);
    setIndiceFaseActual(0);
    setFaseActual(fases[0]?.tipo || 'calentamiento');
    setTiempoRestante(fases[0]?.duracion || 0);
    setTiempoFaseActual(fases[0]?.duracion || 0);
    setTiempoTotalEfectivo(0);
    setSesionActiva(true);
    setSesionPausada(false);
    setTiempoHastaDescanso(tiempoDescansoOptimo); // Usar tiempo calculado según sesión
    setIntervaloDescansoInicial(tiempoDescansoOptimo); // Guardar para reiniciar
    setModalConfigSesion(false);
    setModalSesionAbierto(false);
    setEstadisticasSesion({
      erroresReforzados: 0,
      flashcardsRepasadas: 0,
      practicasHechas: 0,
      notasTomadas: 0
    });
    
    // Cargar datos para cada fase
    await cargarDatosSesion();
    
    // Cargar carpetas para fase de calentamiento
    await cargarCarpetasCalentamiento('');
    
    // Cambiar a la vista de sesión
    setSelectedMenu('sesion');
    
    // Guardar estado inicial
    setTimeout(() => guardarEstadoSesion(), 1000);
  };
  
  const calcularFasesSesion = (minutos, prioridad, excluidas = []) => {
    const segundos = minutos * 60;
    let fases = [];
    
    // Modo TODO: incluye todas las fases disponibles con tiempo equitativo
    if (prioridad === 'todo') {
      const todasLasFases = [
        { tipo: 'calentamiento', nombre: 'Calentamiento', emoji: '🔥' },
        { tipo: 'errores', nombre: 'Refuerzo de Errores', emoji: '🎯' },
        { tipo: 'flashcards', nombre: 'Flashcards', emoji: '🃏' },
        { tipo: 'notas', nombre: 'Repaso de Notas', emoji: '📝' },
        { tipo: 'contenido', nombre: 'Estudio Nuevo', emoji: '📚' },
        { tipo: 'repaso', nombre: 'Repaso de Aciertos', emoji: '🔄' },
        { tipo: 'generar_practicas', nombre: 'Generar Prácticas', emoji: '🧑‍💻' },
        { tipo: 'cierre', nombre: 'Cierre y Resumen', emoji: '✅' }
      ];
      
      // Filtrar fases excluidas
      const fasesActivas = todasLasFases.filter(f => !excluidas.includes(f.tipo));
      const numFases = fasesActivas.length;
      
      if (numFases > 0) {
        // Distribuir tiempo: calentamiento y cierre 10% cada uno, resto equitativo
        const tiempoCalentamiento = fasesActivas.some(f => f.tipo === 'calentamiento') ? Math.floor(segundos * 0.10) : 0;
        const tiempoCierre = fasesActivas.some(f => f.tipo === 'cierre') ? Math.floor(segundos * 0.10) : 0;
        const tiempoRestante = segundos - tiempoCalentamiento - tiempoCierre;
        const fasesIntermedias = fasesActivas.filter(f => f.tipo !== 'calentamiento' && f.tipo !== 'cierre');
        const tiempoPorFase = fasesIntermedias.length > 0 ? Math.floor(tiempoRestante / fasesIntermedias.length) : 0;
        
        fasesActivas.forEach(fase => {
          if (fase.tipo === 'calentamiento') {
            fases.push({ ...fase, duracion: tiempoCalentamiento });
          } else if (fase.tipo === 'cierre') {
            fases.push({ ...fase, duracion: tiempoCierre });
          } else {
            fases.push({ ...fase, duracion: tiempoPorFase });
          }
        });
      }
      
      return fases;
    }
    
    // ===== MODOS ESPECÍFICOS - Fases simples y enfocadas =====
    
    if (prioridad === 'errores') {
      // REFORZAR ERRORES: Solo calentamiento + errores + cierre
      fases = [
        { tipo: 'calentamiento', nombre: 'Calentamiento', duracion: Math.floor(segundos * 0.15), emoji: '🔥' },
        { tipo: 'errores', nombre: 'Refuerzo de Errores', duracion: Math.floor(segundos * 0.70), emoji: '🎯' },
        { tipo: 'cierre', nombre: 'Cierre', duracion: Math.floor(segundos * 0.15), emoji: '✅' }
      ];
    } else if (prioridad === 'contenido') {
      // AVANZAR CONTENIDO: Calentamiento + Estudio Nuevo + Generar Prácticas + Cierre
      fases = [
        { tipo: 'calentamiento', nombre: 'Calentamiento', duracion: Math.floor(segundos * 0.10), emoji: '🔥' },
        { tipo: 'contenido', nombre: 'Estudio Nuevo', duracion: Math.floor(segundos * 0.45), emoji: '📚' },
        { tipo: 'practicas', nombre: 'Generar Prácticas', duracion: Math.floor(segundos * 0.35), emoji: '✍️' },
        { tipo: 'cierre', nombre: 'Cierre', duracion: Math.floor(segundos * 0.10), emoji: '✅' }
      ];
    } else if (prioridad === 'flashcards') {
      // MANTENER MEMORIA: Calentamiento + Flashcards + Notas + Repaso Aciertos + Cierre
      fases = [
        { tipo: 'calentamiento', nombre: 'Calentamiento', duracion: Math.floor(segundos * 0.10), emoji: '🔥' },
        { tipo: 'flashcards', nombre: 'Flashcards', duracion: Math.floor(segundos * 0.35), emoji: '🃏' },
        { tipo: 'notas', nombre: 'Repaso de Notas', duracion: Math.floor(segundos * 0.20), emoji: '📝' },
        { tipo: 'repaso', nombre: 'Repaso de Aciertos', duracion: Math.floor(segundos * 0.25), emoji: '🔄' },
        { tipo: 'cierre', nombre: 'Cierre', duracion: Math.floor(segundos * 0.10), emoji: '✅' }
      ];
    } else if (prioridad === 'notas') {
      // REPASAR NOTAS: Solo calentamiento + notas + cierre
      fases = [
        { tipo: 'calentamiento', nombre: 'Calentamiento', duracion: Math.floor(segundos * 0.15), emoji: '🔥' },
        { tipo: 'notas', nombre: 'Repaso de Notas', duracion: Math.floor(segundos * 0.70), emoji: '📝' },
        { tipo: 'cierre', nombre: 'Cierre', duracion: Math.floor(segundos * 0.15), emoji: '✅' }
      ];
    } else if (prioridad === 'practicas') {
      // GENERAR PRÁCTICAS: Solo calentamiento + generar prácticas + cierre
      fases = [
        { tipo: 'calentamiento', nombre: 'Calentamiento', duracion: Math.floor(segundos * 0.10), emoji: '🔥' },
        { tipo: 'practicas', nombre: 'Generar Prácticas', duracion: Math.floor(segundos * 0.80), emoji: '✍️' },
        { tipo: 'cierre', nombre: 'Cierre', duracion: Math.floor(segundos * 0.10), emoji: '✅' }
      ];
    }
    
    // Filtrar fases excluidas y redistribuir tiempo (solo aplica en modo 'todo')
    if (excluidas.length > 0 && prioridad === 'todo') {
      const fasesOriginales = [...fases];
      const tiempoExcluido = fasesOriginales
        .filter(f => excluidas.includes(f.tipo))
        .reduce((acc, f) => acc + f.duracion, 0);
      
      fases = fasesOriginales.filter(f => !excluidas.includes(f.tipo));
      
      // Redistribuir el tiempo excluido entre las fases restantes (excepto calentamiento y cierre)
      const fasesRedistribuir = fases.filter(f => f.tipo !== 'calentamiento' && f.tipo !== 'cierre');
      if (fasesRedistribuir.length > 0 && tiempoExcluido > 0) {
        const tiempoExtra = Math.floor(tiempoExcluido / fasesRedistribuir.length);
        fases = fases.map(f => {
          if (f.tipo !== 'calentamiento' && f.tipo !== 'cierre') {
            return { ...f, duracion: f.duracion + tiempoExtra };
          }
          return f;
        });
      }
    }
    
    return fases;
  };
  
  // Función para excluir/incluir una fase
  const toggleFaseExcluida = (tipoFase) => {
    setFasesExcluidas(prev => {
      if (prev.includes(tipoFase)) {
        return prev.filter(f => f !== tipoFase);
      } else {
        return [...prev, tipoFase];
      }
    });
  };
  
  const cargarDatosSesion = async () => {
    try {
      // 🔥 CARGAR TANTO EXÁMENES COMO PRÁCTICAS
      // Cargar exámenes
      const responseExamenes = await fetch(`${API_URL}/datos/examenes`);
      const examenes = await responseExamenes.json();
      
      // Cargar prácticas
      const responsePracticas = await fetch(`${API_URL}/datos/practicas`);
      const practicas = await responsePracticas.json();
      
      console.log('📊 Datos cargados para errores:', {
        examenes: examenes.length,
        practicas: practicas.length
      });
      
      // Combinar exámenes y prácticas para extraer errores
      const todosLosItems = [
        ...examenes.map(e => ({ ...e, es_practica: false })),
        ...practicas.map(p => ({ ...p, es_practica: true }))
      ];
      
      setDatosCalentamiento({
        ultimosExamenes: todosLosItems.slice(0, 5) || [],
        carpetaActual: rutaActual
      });
      
      // Cargar errores (preguntas con bajo rendimiento)
      const errores = extraerErroresDeExamenes(todosLosItems);
      console.log('❌ Errores encontrados:', errores.length);
      setErroresActuales(errores);
      setIndiceErrorActual(0);
      
      // 🔥 CARGAR ACIERTOS PARA REPASO
      const aciertos = extraerAciertosParaRepaso(todosLosItems);
      console.log('✅ Aciertos para repaso:', aciertos.length);
      setAciertosRepaso(aciertos);
      setIndiceAciertoActual(0);
      
      // 🔥 CARGAR NOTAS PARA REPASO
      const cargarNotasParaRepaso = async () => {
        try {
          const todasNotas = await getDatos('notas');
          const hoy = new Date();
          const hoyStr = hoy.toISOString().split('T')[0]; // YYYY-MM-DD
          hoy.setHours(0, 0, 0, 0);
          
          console.log('📝 Filtrando notas para repaso. Total:', todasNotas.length);
          
          // Filtrar notas que necesitan repaso (según repetición espaciada)
          // Y que NO hayan sido repasadas HOY
          const notasParaRepasar = todasNotas.filter(nota => {
            // Si ya fue repasada hoy, no mostrar
            const ultimoRepaso = nota.ultimoRepaso || nota.ultima_revision || nota.ultimaRevision;
            if (ultimoRepaso) {
              const ultimoRepasoStr = new Date(ultimoRepaso).toISOString().split('T')[0];
              if (ultimoRepasoStr === hoyStr) {
                console.log(`🚫 Nota ya repasada hoy: ${nota.titulo}`);
                return false; // Ya repasada hoy
              }
            }
            
            // Si es nueva (sin proximaRevision), SIEMPRE mostrar
            if (!nota.proximaRevision) {
              console.log(`✅ Nota nueva para repasar: ${nota.titulo}`);
              return true;
            }
            
            // Si tiene proximaRevision, verificar si ya toca
            const fechaRepaso = new Date(nota.proximaRevision);
            const tocaHoy = fechaRepaso <= hoy;
            if (tocaHoy) {
              console.log(`✅ Nota programada para hoy: ${nota.titulo}`);
            }
            return tocaHoy;
          });
          
          // Filtrar por carpeta actual si existe
          const notasFiltradas = rutaActual 
            ? notasParaRepasar.filter(n => n.carpeta === rutaActual)
            : notasParaRepasar;
          
          console.log('📝 Notas para repasar:', {
            total: todasNotas.length,
            paraRepasar: notasParaRepasar.length,
            enCarpeta: notasFiltradas.length
          });
          
          setNotasRepasoSesion(notasFiltradas);
          setIndiceNotaRepasoActual(0);
        } catch (error) {
          console.error('Error cargando notas:', error);
          setNotasRepasoSesion([]);
        }
      };
      cargarNotasParaRepaso();
      
      // Cargar flashcards desde archivo
      const cargarFlashcardsAsync = async () => {
        try {
          const todasFlashcards = await cargarTodasFlashcards();
          
          // Filtrar flashcards que necesitan repaso (según repetición espaciada)
          const flashcardsParaRepasar = filtrarItemsParaRepasar(todasFlashcards);
          
          // Filtrar por carpeta actual si existe
          let flashcardsFiltradas = rutaActual 
            ? flashcardsParaRepasar.filter(f => f.carpeta === rutaActual)
            : flashcardsParaRepasar;
          
          // 🔥 ELIMINAR DUPLICADOS por ID
          const idsVistos = new Set();
          flashcardsFiltradas = flashcardsFiltradas.filter(f => {
            if (idsVistos.has(f.id)) {
              console.log(`⚠️ Flashcard duplicada eliminada: ${f.id}`);
              return false;
            }
            idsVistos.add(f.id);
            return true;
          });
          
          console.log('📚 Flashcards para repasar:', {
            total: todasFlashcards.length,
            paraRepasar: flashcardsParaRepasar.length,
            enCarpeta: flashcardsFiltradas.length,
            nuevas: flashcardsParaRepasar.filter(f => !f.fechaRevision).length,
            enProgreso: flashcardsParaRepasar.filter(f => f.estadoRevision === 'en_progreso').length
          });
          
          // 🔥 SOLO mostrar flashcards que realmente necesitan repaso
          // NO hacer fallback a todas las flashcards
          setFlashcardsSesion(flashcardsFiltradas);
          setIndiceFlashcardActual(0);
        } catch (error) {
          console.error('Error parseando flashcards:', error);
          setFlashcardsSesion([]);
        }
      };
      cargarFlashcardsAsync();
      
    } catch (error) {
      console.error('Error cargando datos de sesión:', error);
    }
  };
  
  // 🔥 SISTEMA DE ERRORES CON REPETICIÓN ESPACIADA
  // Estados: nuevo → fallo → critical → ok
  // - nuevo: primer error, no tiene estado aún
  // - fallo: falló, revisar mañana (D+1)
  // - critical: falló 2+ veces seguidas, revisar mañana con prioridad
  // - ok: finalmente acertó, intervalo expandido (D+3 a D+6)
  
  const extraerErroresDeExamenes = (examenes, soloAtrasados = true) => {
    const errores = [];
    const hoy = new Date();
    hoy.setHours(0, 0, 0, 0); // Inicio del día
    
    console.log('🔍 Extrayendo errores de', examenes.length, 'exámenes/prácticas');
    console.log('   📅 Solo atrasados:', soloAtrasados, '| Hoy:', hoy.toISOString().split('T')[0]);
    
    examenes.forEach(examen => {
      // 🔥 BUSCAR EN AMBAS ESTRUCTURAS: resultados directos Y resultado.resultados
      let resultados = null;
      
      if (examen.resultados && Array.isArray(examen.resultados)) {
        resultados = examen.resultados;
      } else if (examen.resultado?.resultados && Array.isArray(examen.resultado.resultados)) {
        resultados = examen.resultado.resultados;
      }
      
      // 🔥 Obtener preguntas originales para recuperar opciones
      const preguntasOriginales = examen.preguntas || [];
      
      if (resultados) {
        resultados.forEach((resultado, idx) => {
          const porcentaje = (resultado.puntos / resultado.puntos_maximos) * 100;
          
          // 🔥 Buscar opciones: primero en resultado, luego en preguntas originales
          let opcionesFinales = resultado.opciones || [];
          if ((!opcionesFinales || opcionesFinales.length === 0) && preguntasOriginales[idx]) {
            opcionesFinales = preguntasOriginales[idx].opciones || [];
          }
          // También buscar por pregunta si el índice no coincide
          if ((!opcionesFinales || opcionesFinales.length === 0)) {
            const preguntaOriginal = preguntasOriginales.find(p => 
              p.pregunta === resultado.pregunta || 
              p.id === resultado.pregunta_id
            );
            if (preguntaOriginal) {
              opcionesFinales = preguntaOriginal.opciones || [];
            }
          }
          
          // Considerar error si obtuvo menos del 60%
          if (porcentaje < 60) {
            // 🔥 SI YA FUE CORREGIDO CON ESTADO "ok" Y aún no toca repaso
            // Solo ignorar si soloAtrasados = true (para sesión de estudio)
            // Para conteo total (soloAtrasados = false), incluirlos marcados como corregidos
            if (soloAtrasados && resultado.corregido && resultado.estado_error === 'ok') {
              const proximaRev = resultado.proximaRevisionError ? new Date(resultado.proximaRevisionError) : null;
              if (proximaRev && proximaRev > hoy) {
                console.log('✅ Error OK, aún no toca:', {
                  pregunta: resultado.pregunta.substring(0, 40) + '...',
                  proximaRevision: proximaRev.toISOString().split('T')[0]
                });
                return; // Skip this error (solo en modo soloAtrasados)
              }
            }
            
            // 🔥 DETERMINAR SI ES ATRASADO
            // Un error es "atrasado" o "pendiente de revisión" si:
            // 1. Es NUEVO (sin estado_error) - SIEMPRE se debe revisar
            // 2. proximaRevisionError <= hoy (toca revisión)
            // 3. estado_error es 'fallo' o 'critical'
            
            const fechaExamen = examen.fecha_completado ? new Date(examen.fecha_completado) : new Date();
            fechaExamen.setHours(0, 0, 0, 0);
            const esDeHoy = fechaExamen.getTime() === hoy.getTime();
            
            const proximaRev = resultado.proximaRevisionError ? new Date(resultado.proximaRevisionError) : null;
            let esAtrasado = false;
            
            if (!resultado.estado_error) {
              // 🔥 Error NUEVO: SIEMPRE incluir - nunca se ha intentado corregir
              esAtrasado = true;
            } else if (proximaRev) {
              // Tiene fecha de revisión: atrasado si ya pasó o es hoy
              esAtrasado = proximaRev <= hoy;
            } else {
              // Tiene estado pero no fecha: considerarlo pendiente
              esAtrasado = true;
            }
            
            // 🔥 FILTRAR: Si soloAtrasados y no es atrasado, skip
            if (soloAtrasados && !esAtrasado) {
              console.log('⏳ Error ya corregido (ignorado):', {
                pregunta: resultado.pregunta.substring(0, 40) + '...',
                estado: resultado.estado_error,
                proximaRevision: proximaRev?.toISOString().split('T')[0]
              });
              return;
            }
            
            console.log('❌ Error para revisión:', {
              examen_id: examen.id,
              pregunta: resultado.pregunta.substring(0, 40) + '...',
              porcentaje: porcentaje.toFixed(2) + '%',
              estado: resultado.estado_error || 'nuevo',
              veces_fallada: resultado.veces_fallada || 0,
              esAtrasado,
              tieneOpciones: opcionesFinales.length > 0
            });
            
            errores.push({
              ...resultado,
              examen_id: examen.id,
              archivo: examen.archivo,
              carpeta_ruta: examen.carpeta_ruta || examen.carpeta,
              fecha: examen.fecha_completado,
              carpeta: examen.carpeta_nombre,
              es_practica: examen.es_practica === true,
              tipo_item: examen.es_practica ? 'practica' : 'examen',
              porcentaje_obtenido: porcentaje,
              // 🔥 CAMPOS IMPORTANTES PARA RENDERIZADO - usar opciones recuperadas
              tipo: resultado.tipo || examen.tipo_pregunta,
              opciones: opcionesFinales,
              respuesta_correcta: resultado.respuesta_correcta,
              respuesta_usuario: resultado.respuesta_usuario,
              // 🔥 CAMPOS DE REPETICIÓN ESPACIADA
              estado_error: resultado.estado_error || 'nuevo',
              veces_fallada: resultado.veces_fallada || 0,
              proximaRevisionError: resultado.proximaRevisionError,
              ultimaRevisionError: resultado.ultimaRevisionError
            });
          }
        });
      }
    });
    
    // Ordenar: primero los críticos, luego por veces falladas, luego por fecha más antigua
    const erroresOrdenados = errores.sort((a, b) => {
      // Prioridad por estado
      const prioridad = { 'critical': 0, 'fallo': 1, 'nuevo': 2, 'ok': 3 };
      const prioA = prioridad[a.estado_error] ?? 2;
      const prioB = prioridad[b.estado_error] ?? 2;
      if (prioA !== prioB) return prioA - prioB;
      
      // Luego por veces falladas (más falladas primero)
      if (a.veces_fallada !== b.veces_fallada) {
        return (b.veces_fallada || 0) - (a.veces_fallada || 0);
      }
      
      // Finalmente por fecha más antigua
      const fechaA = new Date(a.fecha || 0);
      const fechaB = new Date(b.fecha || 0);
      return fechaA - fechaB;
    });
    
    console.log('📊 Total errores para revisión:', erroresOrdenados.length);
    return erroresOrdenados;
  };
  
  // 🔥 SISTEMA DE REPASO DE ACIERTOS
  // Extrae preguntas que el usuario acertó (>=60%) y cuya proximaRevision ya llegó
  // Si falla ahora → retrocede a estado "fallo", pierde intervalo, revisa mañana
  const extraerAciertosParaRepaso = (examenes) => {
    const aciertos = [];
    const hoy = new Date();
    hoy.setHours(0, 0, 0, 0);
    
    console.log('🎯 Extrayendo aciertos para repaso de', examenes.length, 'exámenes/prácticas');
    
    examenes.forEach(examen => {
      let resultados = null;
      
      if (examen.resultados && Array.isArray(examen.resultados)) {
        resultados = examen.resultados;
      } else if (examen.resultado?.resultados && Array.isArray(examen.resultado.resultados)) {
        resultados = examen.resultado.resultados;
      }
      
      if (resultados) {
        resultados.forEach(resultado => {
          const porcentaje = (resultado.puntos / resultado.puntos_maximos) * 100;
          
          // Solo considerar ACIERTOS (>=60%)
          if (porcentaje >= 60) {
            // Verificar si tiene proximaRevision y ya llegó el momento
            const proximaRev = resultado.proximaRevision ? new Date(resultado.proximaRevision) : null;
            
            // Una pregunta acertada necesita repaso si:
            // 1. Tiene proximaRevision y ya pasó o es hoy
            // 2. Tiene estado 'ok' (de error corregido) y proximaRevisionError llegó
            let necesitaRepaso = false;
            let fuente = 'pregunta'; // 'pregunta' o 'error_corregido'
            
            if (proximaRev && proximaRev <= hoy) {
              necesitaRepaso = true;
              fuente = 'pregunta';
            }
            
            // También incluir errores corregidos (estado='ok') cuya proximaRevisionError llegó
            if (resultado.estado_error === 'ok' && resultado.proximaRevisionError) {
              const proximaRevError = new Date(resultado.proximaRevisionError);
              if (proximaRevError <= hoy) {
                necesitaRepaso = true;
                fuente = 'error_corregido';
              }
            }
            
            if (necesitaRepaso) {
              console.log('✅ Acierto para repaso:', {
                pregunta: resultado.pregunta.substring(0, 40) + '...',
                porcentaje: porcentaje.toFixed(2) + '%',
                fuente,
                proximaRevision: proximaRev?.toISOString().split('T')[0]
              });
              
              aciertos.push({
                ...resultado,
                examen_id: examen.id,
                archivo: examen.archivo,
                carpeta_ruta: examen.carpeta_ruta || examen.carpeta,
                fecha: examen.fecha_completado,
                carpeta: examen.carpeta_nombre,
                es_practica: examen.es_practica === true,
                tipo_item: examen.es_practica ? 'practica' : 'examen',
                porcentaje_obtenido: porcentaje,
                fuente_repaso: fuente,
                // Campos de repetición espaciada
                intervalo: resultado.intervalo || 1,
                repeticiones: resultado.repeticiones || 0,
                facilidad: resultado.facilidad || 2.5,
                estado_repaso: resultado.estado_repaso || 'pendiente' // pendiente, correcto, fallado
              });
            }
          }
        });
      }
    });
    
    // Ordenar por fecha de próxima revisión más antigua primero
    const aciertosOrdenados = aciertos.sort((a, b) => {
      const fechaA = new Date(a.proximaRevision || a.proximaRevisionError || 0);
      const fechaB = new Date(b.proximaRevision || b.proximaRevisionError || 0);
      return fechaA - fechaB;
    });
    
    console.log('📊 Total aciertos para repaso:', aciertosOrdenados.length);
    return aciertosOrdenados;
  };
  
  const avanzarFase = async () => {
    const siguienteIndice = indiceFaseActual + 1;
    
    if (siguienteIndice < fasesSesion.length) {
      const siguienteFase = fasesSesion[siguienteIndice];
      
      // 💡 TRANSFERIR TIEMPO SOBRANTE de la fase actual a la siguiente
      const tiempoSobrante = tiempoRestante > 0 ? tiempoRestante : 0;
      const nuevaDuracion = siguienteFase.duracion + tiempoSobrante;
      
      if (tiempoSobrante > 0) {
        console.log(`⏱️ Transferencia de tiempo: +${Math.floor(tiempoSobrante/60)} min ${tiempoSobrante%60} seg a ${siguienteFase.nombre}`);
      }
      
      setIndiceFaseActual(siguienteIndice);
      setFaseActual(siguienteFase.tipo);
      setTiempoRestante(nuevaDuracion);
      setTiempoFaseActual(nuevaDuracion);
      
      // Si avanzamos desde calentamiento y hay una carpeta seleccionada, establecerla para las siguientes fases
      if (faseActual === 'calentamiento' && rutaCalentamientoActual) {
        // Establecer carpeta para flashcards
        setCarpetaFlashcardActual({
          nombre: rutaCalentamientoActual.split('\\').pop() || rutaCalentamientoActual,
          ruta: rutaCalentamientoActual
        });
        
        // Establecer carpeta para notas
        setRutaNotasActual(rutaCalentamientoActual);
        
        // Establecer carpeta para contenido
        setRutaContenidoActual(rutaCalentamientoActual);
      }
    } else {
      // Sesión completada
      finalizarSesion();
    }
  };
  
  // Generar título automático basado en el contenido
  const generarTituloAutomatico = (contenido) => {
    if (!contenido) return `Nota ${new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })}`;
    
    // Buscar primera línea con contenido
    const lineas = contenido.split('\n').filter(l => l.trim());
    if (lineas.length === 0) return `Nota ${new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })}`;
    
    let titulo = lineas[0]
      .replace(/^#+\s*/, '') // Quitar # de markdown
      .replace(/\*+/g, '') // Quitar asteriscos
      .replace(/`+/g, '') // Quitar backticks
      .trim();
    
    // Limitar longitud
    if (titulo.length > 50) {
      titulo = titulo.substring(0, 47) + '...';
    }
    
    return titulo || `Nota ${new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })}`;
  };
  
  const pausarReanudarSesion = () => {
    if (!sesionPausada) {
      // Al pausar, establecer 5 minutos de pausa
      setTiempoPausaRestante(300);
    }
    setSesionPausada(!sesionPausada);
  };
  
  const finalizarSesion = async () => {
    console.log('🏁 Finalizando sesión...');
    
    // 🔥 CRÍTICO: Detener PRIMERO sesionActiva para que los useEffect dejen de ejecutarse
    setSesionActiva(false);
    
    // Pequeña espera para que React procese el cambio de estado
    await new Promise(resolve => setTimeout(resolve, 100));
    
    // Cambiar a fase de cierre
    setFaseActual('cierre');
    
    // Limpiar todos los timers
    setTiempoRestante(0);
    setSesionPausada(false);
    setEnDescanso(false);
    setTiempoHastaDescanso(0);
    setTiempoPausaRestante(0);
    
    // Eliminar sesión del backend
    try {
      await setSesionActiva({});
      localStorage.removeItem('examinator_sesion_activa');
      setSesionPersistente(null);
    } catch (error) {
      console.error('❌ Error eliminando sesión al finalizar:', error);
    }
    
    setMensaje({
      tipo: 'success',
      texto: '🎉 ¡Sesión completada! Revisa tu resumen de estudio.'
    });
  };
  
  const salirSesion = async () => {
    if (window.confirm('¿Seguro que quieres salir de la sesión? Se perderá el progreso actual.')) {
      setSesionActiva(false);
      setSesionPausada(false);
      setFaseActual(null);
      
      // Eliminar sesión guardada del backend
      try {
        await setSesionActiva({});
        setSesionPersistente(null);
        console.log('🗑️ Sesión abandonada y eliminada');
      } catch (error) {
        console.error('❌ Error eliminando sesión al salir:', error);
      }
      
      setSelectedMenu('inicio');
    }
  };
  
  const siguienteError = () => {
    if (indiceErrorActual < erroresActuales.length - 1) {
      setIndiceErrorActual(indiceErrorActual + 1);
      setEstadisticasSesion(prev => ({
        ...prev,
        erroresReforzados: prev.erroresReforzados + 1
      }));
    } else {
      // No hay más errores, avanzar fase
      avanzarFase();
    }
  };
  
  // Función para seleccionar respuesta al error (MCQ y V/F)
  const seleccionarRespuestaError = (opcion) => {
    setRespuestaErrorSeleccionada(opcion);
    setErrorYaRespondido(true);
    
    const errorActual = erroresActuales[indiceErrorActual];
    
    // 🔥 VERIFICAR CORRECTA: MCQ usa startsWith, V/F usa normalización
    let esCorrecta = false;
    const respCorrecta = errorActual.respuesta_correcta?.trim().toLowerCase();
    const opcionLower = opcion.toLowerCase();
    
    // Detectar si es V/F
    const esVerdaderoFalso = errorActual.tipo === 'verdadero_falso' || 
      errorActual.tipo === 'true_false' ||
      errorActual.tipo === 'verdadero-falso' ||
      ['verdadero', 'falso', 'v', 'f', 'true', 'false'].includes(respCorrecta);
    
    if (esVerdaderoFalso) {
      // Normalizar respuesta correcta y comparar
      const correctaEsVerdadero = ['verdadero', 'v', 'true'].includes(respCorrecta);
      const opcionEsVerdadero = opcionLower === 'verdadero';
      esCorrecta = (correctaEsVerdadero && opcionEsVerdadero) || (!correctaEsVerdadero && !opcionEsVerdadero);
    } else {
      // MCQ: comparar inicio
      esCorrecta = opcion.startsWith(errorActual.respuesta_correcta);
    }
    
    if (esCorrecta) {
      console.log('✅ ¡Respuesta correcta! El error fue comprendido.');
    } else {
      console.log('❌ Respuesta incorrecta. Intenta nuevamente.');
    }
  };

  // 🔥 NUEVA: Función para evaluar respuesta textual con IA (usando backend con modelo configurado)
  const evaluarRespuestaTextual = async () => {
    if (!respuestaTextual.trim()) {
      alert('Por favor escribe una respuesta antes de enviar');
      return;
    }

    const errorActual = erroresActuales[indiceErrorActual];
    setEvaluandoRespuesta(true);

    try {
      // Obtener el modelo activo desde la configuración
      const modelo = configuracion?.modelo_ollama_activo || modeloSeleccionado;
      
      if (!modelo) {
        alert('⚠️ No hay un modelo seleccionado. Por favor, activa un modelo en la configuración.');
        setEvaluandoRespuesta(false);
        return;
      }
      
      console.log('🤖 Evaluando con modelo configurado:', modelo);
      console.log('   📝 Pregunta:', errorActual.pregunta);
      console.log('   💭 Respuesta usuario:', respuestaTextual);
      
      // Llamar al nuevo endpoint del backend que usa el modelo configurado
      const response = await fetch(`${API_URL}/api/evaluar-respuesta-textual`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          pregunta: errorActual.pregunta,
          respuesta_usuario: respuestaTextual,
          respuesta_correcta: errorActual.respuesta_correcta,
          intentos_previos: historialIntentos,
          modelo: modelo
        })
      });
      
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || `Error del servidor: ${response.status}`);
      }

      const data = await response.json();
      const evaluacion = data.evaluacion;
      
      console.log('✅ Evaluación recibida:', evaluacion);

      // Convertir puntuación 0-10 a 0-100 para compatibilidad
      const puntaje = Math.round((evaluacion.puntuacion / 10) * 100);
      
      // Construir feedback en formato compatible
      const feedbackTexto = `Puntaje: ${puntaje}/100 (${evaluacion.puntuacion}/10)

${evaluacion.feedback}

${evaluacion.sugerencias ? `💡 Sugerencias: ${evaluacion.sugerencias}` : ''}`;

      // Guardar en historial
      setHistorialIntentos(prev => [...prev, {
        respuesta: respuestaTextual,
        feedback: feedbackTexto,
        puntaje: puntaje,
        timestamp: new Date().toISOString()
      }]);

      setFeedbackIA({
        texto: feedbackTexto,
        puntaje: puntaje,
        esSuficiente: evaluacion.aprobada || puntaje >= 70
      });

      // Si la respuesta fue aprobada, marcar como respondido
      if (evaluacion.aprobada || puntaje >= 70) {
        setRespuestaErrorSeleccionada(respuestaTextual);
        setErrorYaRespondido(true);
      }

    } catch (error) {
      console.error('❌ Error al evaluar respuesta:', error);
      
      let mensajeError = 'Error al evaluar con el modelo.';
      
      if (error.message.includes('conectar') || error.message.includes('503')) {
        mensajeError = '❌ No se pudo conectar con Ollama. Verifica que esté corriendo.';
      } else if (error.message.includes('modelo')) {
        mensajeError = '❌ Error con el modelo. Verifica que esté correctamente configurado.';
      } else {
        mensajeError = `❌ ${error.message}`;
      }
      
      alert(mensajeError);
    } finally {
      setEvaluandoRespuesta(false);
    }
  };

  const marcarErrorComprendido = async () => {
    const errorActual = erroresActuales[indiceErrorActual];
    let esCorrecta = false;
    
    console.log('🔍 MARCANDO ERROR COMPRENDIDO:', {
      pregunta: errorActual.pregunta.substring(0, 50) + '...',
      respuestaSeleccionada: respuestaErrorSeleccionada,
      respuestaTextual: respuestaTextual,
      feedbackIA: feedbackIA,
      estado_error: errorActual.estado_error,
      veces_fallada: errorActual.veces_fallada
    });
    
    // 🔥 VERIFICAR SI ES CORRECTA - Considerar MCQ, V/F y texto
    const respCorrecta = errorActual.respuesta_correcta?.trim().toLowerCase();
    
    // Detectar si es V/F
    const esVerdaderoFalso = errorActual.tipo === 'verdadero_falso' || 
      errorActual.tipo === 'true_false' ||
      errorActual.tipo === 'verdadero-falso' ||
      ['verdadero', 'falso', 'v', 'f', 'true', 'false'].includes(respCorrecta);
    
    if (respuestaErrorSeleccionada) {
      if (esVerdaderoFalso) {
        // V/F: normalizar y comparar
        const correctaEsVerdadero = ['verdadero', 'v', 'true'].includes(respCorrecta);
        const opcionEsVerdadero = respuestaErrorSeleccionada.toLowerCase() === 'verdadero';
        esCorrecta = (correctaEsVerdadero && opcionEsVerdadero) || (!correctaEsVerdadero && !opcionEsVerdadero);
      } else {
        // MCQ: comparar inicio
        esCorrecta = respuestaErrorSeleccionada.startsWith(errorActual.respuesta_correcta);
      }
      if (esCorrecta) console.log('✅ Respuesta MCQ/V/F CORRECTA');
    } else if (feedbackIA && (feedbackIA.esSuficiente || feedbackIA.puntaje >= 70)) {
      esCorrecta = true;
      console.log('✅ Respuesta de texto CORRECTA (aprobada por IA)');
    }
    
    // 🔥 CALCULAR NUEVO ESTADO DE ERROR
    const ahora = new Date();
    const hoy = new Date(ahora);
    hoy.setHours(0, 0, 0, 0);
    
    let nuevoEstado = errorActual.estado_error || 'nuevo';
    let nuevasVecesFallada = errorActual.veces_fallada || 0;
    let nuevaProximaRevision = null;
    
    if (esCorrecta) {
      // ✅ RESPONDIÓ CORRECTAMENTE → estado 'ok', intervalo 3-6 días
      nuevoEstado = 'ok';
      nuevasVecesFallada = 0; // Resetear contador
      
      // Intervalo aleatorio 3-6 días
      const diasIntervalo = 3 + Math.floor(Math.random() * 4); // 3, 4, 5 o 6
      nuevaProximaRevision = new Date(hoy);
      nuevaProximaRevision.setDate(nuevaProximaRevision.getDate() + diasIntervalo);
      
      console.log(`✅ Error corregido → estado='ok', próxima revisión en ${diasIntervalo} días`);
    } else {
      // ❌ RESPONDIÓ INCORRECTAMENTE → incrementar fallos
      nuevasVecesFallada += 1;
      
      if (nuevasVecesFallada >= 3) {
        // 🔥 "Incendio cognitivo" - 3+ fallos seguidos
        nuevoEstado = 'critical';
        console.log(`🔥 INCENDIO COGNITIVO: ${nuevasVecesFallada} fallos consecutivos → critical`);
      } else if (nuevasVecesFallada >= 2 || errorActual.estado_error === 'fallo') {
        // 2+ fallos → critical
        nuevoEstado = 'critical';
        console.log(`❌ 2+ fallos → estado='critical'`);
      } else {
        // Primer fallo → fallo
        nuevoEstado = 'fallo';
        console.log(`⚠️ Primer fallo → estado='fallo'`);
      }
      
      // Siempre revisar mañana cuando falla
      nuevaProximaRevision = new Date(hoy);
      nuevaProximaRevision.setDate(nuevaProximaRevision.getDate() + 1);
      
      console.log(`📅 Error mal respondido → revisión mañana, veces_fallada=${nuevasVecesFallada}`);
    }
    
    // 🔥 ACTUALIZAR EN EL ARCHIVO JSON
    try {
      const esExamen = errorActual.es_practica !== true;
      const tipoItem = errorActual.tipo_item || (esExamen ? 'examen' : 'practica');
      const listaABuscar = esExamen ? await getDatos('examenes') : await getDatos('practicas');
      
      console.log(`📦 Buscando en ${listaABuscar.length} ${tipoItem}s`);
      
      const itemEncontrado = listaABuscar.find(item => item.id === errorActual.examen_id);
      
      if (!itemEncontrado) {
        console.error('❌ No se encontró el item con ID:', errorActual.examen_id);
        throw new Error(`Item con ID ${errorActual.examen_id} no encontrado`);
      }
      
      // Obtener resultados
      let resultados = null;
      let esEstructuraDirecta = false;
      
      if (itemEncontrado.resultado?.resultados) {
        resultados = itemEncontrado.resultado.resultados;
        esEstructuraDirecta = false;
      } else if (itemEncontrado.resultados && Array.isArray(itemEncontrado.resultados)) {
        resultados = itemEncontrado.resultados;
        esEstructuraDirecta = true;
      }
      
      if (!resultados) throw new Error('No se encontraron resultados');
      
      // Buscar la pregunta específica
      const preguntaIndex = resultados.findIndex(r => r.pregunta === errorActual.pregunta);
      if (preguntaIndex === -1) throw new Error('Pregunta no encontrada');
      
      // 🔥 ACTUALIZAR CAMPOS DE REPETICIÓN ESPACIADA
      resultados[preguntaIndex].estado_error = nuevoEstado;
      resultados[preguntaIndex].veces_fallada = nuevasVecesFallada;
      resultados[preguntaIndex].proximaRevisionError = nuevaProximaRevision?.toISOString();
      resultados[preguntaIndex].ultimaRevisionError = ahora.toISOString();
      
      if (esCorrecta) {
        // Solo si es correcta, actualizar respuesta y puntos
        if (respuestaErrorSeleccionada) {
          resultados[preguntaIndex].respuesta_usuario = errorActual.respuesta_correcta;
        } else if (respuestaTextual) {
          resultados[preguntaIndex].respuesta_usuario = respuestaTextual;
        }
        resultados[preguntaIndex].puntos = resultados[preguntaIndex].puntos_maximos;
        resultados[preguntaIndex].corregido = true;
        resultados[preguntaIndex].fechaCorreccion = ahora.toISOString();
        
        // Recalcular puntos totales
        const nuevosPuntosObtenidos = resultados.reduce((sum, r) => sum + (r.puntos || 0), 0);
        const puntosTotales = esEstructuraDirecta ? itemEncontrado.puntos_totales : itemEncontrado.resultado.puntos_totales;
        const nuevoPorcentaje = (nuevosPuntosObtenidos / puntosTotales) * 100;
        
        if (esEstructuraDirecta) {
          itemEncontrado.puntos_obtenidos = nuevosPuntosObtenidos;
          itemEncontrado.porcentaje = nuevoPorcentaje;
        } else {
          itemEncontrado.resultado.puntos_obtenidos = nuevosPuntosObtenidos;
          itemEncontrado.resultado.porcentaje = nuevoPorcentaje;
        }
      }
      
      console.log('   📝 Pregunta actualizada:', {
        estado_error: resultados[preguntaIndex].estado_error,
        veces_fallada: resultados[preguntaIndex].veces_fallada,
        proximaRevisionError: resultados[preguntaIndex].proximaRevisionError,
        corregido: resultados[preguntaIndex].corregido
      });
      
      // Guardar
      console.log('   💾 Guardando...');
      if (esExamen) {
        await guardarExamenEnCarpeta(itemEncontrado);
      } else {
        await guardarPracticaEnCarpeta(itemEncontrado, imagenesLocales);
      }
      
      console.log('✅ Item actualizado y guardado');
      
    } catch (error) {
      console.error('❌ Error actualizando item:', error);
    }
    
    // Si fue corregido, eliminarlo de la lista de errores actuales
    if (esCorrecta) {
      const nuevosErrores = erroresActuales.filter((_, idx) => idx !== indiceErrorActual);
      setErroresActuales(nuevosErrores);
      
      // Si ya no quedan errores, avanzar fase
      if (nuevosErrores.length === 0) {
        setMensaje({
          tipo: 'success',
          texto: '🎉 ¡Felicidades! Has corregido todos los errores'
        });
        setRespuestaErrorSeleccionada(null);
        setErrorYaRespondido(false);
        setRespuestaTextual('');
        setHistorialIntentos([]);
        setFeedbackIA(null);
        avanzarFase();
        return;
      }
      
      // Ajustar índice si es necesario
      if (indiceErrorActual >= nuevosErrores.length) {
        setIndiceErrorActual(nuevosErrores.length - 1);
      }
    }
    
    // Resetear estados de respuesta
    setRespuestaErrorSeleccionada(null);
    setErrorYaRespondido(false);
    setRespuestaTextual('');
    setHistorialIntentos([]);
    setFeedbackIA(null);
    
    // Si no fue corregido, pasar al siguiente
    if (!esCorrecta) {
      siguienteError();
    }
  };
  
  // ============================================
  // 🔄 FASE DE REPASO DE ACIERTOS
  // ============================================
  
  // Función para seleccionar respuesta en repaso de aciertos (MCQ y V/F)
  const seleccionarRespuestaAcierto = (opcion) => {
    setRespuestaAciertoSeleccionada(opcion);
    setAciertoYaRespondido(true);
    
    const aciertoActual = aciertosRepaso[indiceAciertoActual];
    
    // Verificar si es correcta (MCQ, V/F)
    let esCorrecta = false;
    const respCorrecta = aciertoActual.respuesta_correcta?.trim().toLowerCase();
    const opcionLower = opcion.toLowerCase();
    
    const esVerdaderoFalso = aciertoActual.tipo === 'verdadero_falso' || 
      aciertoActual.tipo === 'true_false' ||
      aciertoActual.tipo === 'verdadero-falso' ||
      ['verdadero', 'falso', 'v', 'f', 'true', 'false'].includes(respCorrecta);
    
    if (esVerdaderoFalso) {
      const correctaEsVerdadero = ['verdadero', 'v', 'true'].includes(respCorrecta);
      const opcionEsVerdadero = opcionLower === 'verdadero';
      esCorrecta = (correctaEsVerdadero && opcionEsVerdadero) || (!correctaEsVerdadero && !opcionEsVerdadero);
    } else {
      esCorrecta = opcion.startsWith(aciertoActual.respuesta_correcta);
    }
    
    if (esCorrecta) {
      console.log('✅ ¡Respuesta correcta en repaso de acierto!');
    } else {
      console.log('❌ Respuesta incorrecta en repaso. El acierto retrocede a fallo.');
    }
  };

  // Evaluar respuesta textual en repaso de aciertos
  const evaluarRespuestaTextualAcierto = async () => {
    if (!respuestaTextualAcierto.trim()) {
      alert('Por favor escribe una respuesta antes de enviar');
      return;
    }

    const aciertoActual = aciertosRepaso[indiceAciertoActual];
    setEvaluandoRespuestaAcierto(true);

    try {
      const modelo = configuracion?.modelo_ollama_activo || modeloSeleccionado;
      
      if (!modelo) {
        alert('⚠️ No hay un modelo seleccionado. Por favor, activa un modelo en la configuración.');
        setEvaluandoRespuestaAcierto(false);
        return;
      }
      
      const response = await fetch(`${API_URL}/api/evaluar-respuesta-textual`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          pregunta: aciertoActual.pregunta,
          respuesta_usuario: respuestaTextualAcierto,
          respuesta_correcta: aciertoActual.respuesta_correcta,
          intentos_previos: historialIntentosAcierto,
          modelo: modelo
        })
      });
      
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || `Error del servidor: ${response.status}`);
      }

      const data = await response.json();
      const evaluacion = data.evaluacion;
      const puntaje = Math.round((evaluacion.puntuacion / 10) * 100);
      
      const feedbackTexto = `Puntaje: ${puntaje}/100 (${evaluacion.puntuacion}/10)\n\n${evaluacion.feedback}\n\n${evaluacion.sugerencias ? `💡 Sugerencias: ${evaluacion.sugerencias}` : ''}`;

      setHistorialIntentosAcierto(prev => [...prev, {
        respuesta: respuestaTextualAcierto,
        feedback: feedbackTexto,
        puntaje: puntaje,
        timestamp: new Date().toISOString()
      }]);

      setFeedbackIAAcierto({
        texto: feedbackTexto,
        puntaje: puntaje,
        esSuficiente: evaluacion.aprobada || puntaje >= 70
      });

      if (evaluacion.aprobada || puntaje >= 70) {
        setRespuestaAciertoSeleccionada(respuestaTextualAcierto);
        setAciertoYaRespondido(true);
      }

    } catch (error) {
      console.error('❌ Error al evaluar respuesta:', error);
      alert(`❌ ${error.message}`);
    } finally {
      setEvaluandoRespuestaAcierto(false);
    }
  };

  // Marcar acierto como repasado y actualizar su estado
  const marcarAciertoRepasado = async () => {
    const aciertoActual = aciertosRepaso[indiceAciertoActual];
    let esCorrecta = false;
    
    console.log('🔄 MARCANDO ACIERTO REPASADO:', {
      pregunta: aciertoActual.pregunta.substring(0, 50) + '...',
      respuestaSeleccionada: respuestaAciertoSeleccionada,
      respuestaTextual: respuestaTextualAcierto,
      feedbackIA: feedbackIAAcierto
    });
    
    // Verificar si es correcta
    const respCorrecta = aciertoActual.respuesta_correcta?.trim().toLowerCase();
    const esVerdaderoFalso = aciertoActual.tipo === 'verdadero_falso' || 
      aciertoActual.tipo === 'true_false' ||
      aciertoActual.tipo === 'verdadero-falso' ||
      ['verdadero', 'falso', 'v', 'f', 'true', 'false'].includes(respCorrecta);
    
    if (respuestaAciertoSeleccionada) {
      if (esVerdaderoFalso) {
        const correctaEsVerdadero = ['verdadero', 'v', 'true'].includes(respCorrecta);
        const opcionEsVerdadero = respuestaAciertoSeleccionada.toLowerCase() === 'verdadero';
        esCorrecta = (correctaEsVerdadero && opcionEsVerdadero) || (!correctaEsVerdadero && !opcionEsVerdadero);
      } else {
        esCorrecta = respuestaAciertoSeleccionada.startsWith(aciertoActual.respuesta_correcta);
      }
    } else if (feedbackIAAcierto && (feedbackIAAcierto.esSuficiente || feedbackIAAcierto.puntaje >= 70)) {
      esCorrecta = true;
    }
    
    // Calcular nuevo estado según resultado
    const ahora = new Date();
    const hoy = new Date(ahora);
    hoy.setHours(0, 0, 0, 0);
    
    let nuevoEstado, nuevaProximaRevision, nuevoIntervalo, nuevaFacilidad, nuevasRepeticiones;
    
    if (esCorrecta) {
      // ✅ RESPONDIÓ CORRECTAMENTE → mantener/aumentar intervalo
      nuevoEstado = 'correcto';
      nuevasRepeticiones = (aciertoActual.repeticiones || 0) + 1;
      nuevaFacilidad = Math.min(3.0, (aciertoActual.facilidad || 2.5) + 0.1);
      
      // Calcular nuevo intervalo según repeticiones
      if (nuevasRepeticiones === 1) {
        nuevoIntervalo = 3; // 3 días
      } else if (nuevasRepeticiones === 2) {
        nuevoIntervalo = 7; // 1 semana
      } else {
        nuevoIntervalo = Math.round((aciertoActual.intervalo || 1) * nuevaFacilidad);
      }
      nuevoIntervalo = Math.min(nuevoIntervalo, 365); // Máximo 1 año
      
      nuevaProximaRevision = new Date(hoy);
      nuevaProximaRevision.setDate(nuevaProximaRevision.getDate() + nuevoIntervalo);
      
      console.log(`✅ Acierto mantenido → intervalo=${nuevoIntervalo} días, próxima=${nuevaProximaRevision.toISOString().split('T')[0]}`);
    } else {
      // ❌ FALLÓ UN ACIERTO → RETROCEDE EN LA CURVA DE MEMORIA
      // Se convierte en un "error" y se reactiva para revisión mañana
      nuevoEstado = 'fallo';
      nuevasRepeticiones = 0; // Reiniciar
      nuevaFacilidad = Math.max(1.3, (aciertoActual.facilidad || 2.5) - 0.2);
      nuevoIntervalo = 1; // Revisar mañana
      
      nuevaProximaRevision = new Date(hoy);
      nuevaProximaRevision.setDate(nuevaProximaRevision.getDate() + 1);
      
      console.log(`❌ ACIERTO FALLÓ → retrocede a estado='fallo', revisar mañana`);
    }
    
    // Actualizar en el archivo JSON
    try {
      const esExamen = aciertoActual.es_practica !== true;
      const listaABuscar = esExamen ? await getDatos('examenes') : await getDatos('practicas');
      
      const itemEncontrado = listaABuscar.find(item => item.id === aciertoActual.examen_id);
      
      if (!itemEncontrado) {
        throw new Error(`Item con ID ${aciertoActual.examen_id} no encontrado`);
      }
      
      let resultados = null;
      let esEstructuraDirecta = false;
      
      if (itemEncontrado.resultado?.resultados) {
        resultados = itemEncontrado.resultado.resultados;
      } else if (itemEncontrado.resultados && Array.isArray(itemEncontrado.resultados)) {
        resultados = itemEncontrado.resultados;
        esEstructuraDirecta = true;
      }
      
      if (!resultados) throw new Error('No se encontraron resultados');
      
      const preguntaIndex = resultados.findIndex(r => r.pregunta === aciertoActual.pregunta);
      if (preguntaIndex === -1) throw new Error('Pregunta no encontrada');
      
      // Actualizar campos de repetición espaciada
      resultados[preguntaIndex].estado_repaso = nuevoEstado;
      resultados[preguntaIndex].proximaRevision = nuevaProximaRevision.toISOString();
      resultados[preguntaIndex].ultimaRevision = ahora.toISOString();
      resultados[preguntaIndex].intervalo = nuevoIntervalo;
      resultados[preguntaIndex].repeticiones = nuevasRepeticiones;
      resultados[preguntaIndex].facilidad = nuevaFacilidad;
      
      // Si falló, también marcar como error para que aparezca en fase de errores
      if (!esCorrecta) {
        resultados[preguntaIndex].estado_error = 'fallo';
        resultados[preguntaIndex].veces_fallada = (resultados[preguntaIndex].veces_fallada || 0) + 1;
        resultados[preguntaIndex].proximaRevisionError = nuevaProximaRevision.toISOString();
        // NO marcar como corregido, así aparece en errores
        resultados[preguntaIndex].corregido = false;
      }
      
      console.log('   📝 Pregunta actualizada:', {
        estado_repaso: nuevoEstado,
        proximaRevision: nuevaProximaRevision.toISOString().split('T')[0],
        intervalo: nuevoIntervalo,
        repeticiones: nuevasRepeticiones
      });
      
      // Guardar
      if (esExamen) {
        await guardarExamenEnCarpeta(itemEncontrado);
      } else {
        await guardarPracticaEnCarpeta(itemEncontrado, imagenesLocales);
      }
      
      console.log('✅ Acierto actualizado y guardado');
      
    } catch (error) {
      console.error('❌ Error actualizando acierto:', error);
    }
    
    // Avanzar al siguiente acierto
    const nuevosAciertos = aciertosRepaso.filter((_, idx) => idx !== indiceAciertoActual);
    setAciertosRepaso(nuevosAciertos);
    
    if (nuevosAciertos.length === 0) {
      setMensaje({
        tipo: 'success',
        texto: '🎉 ¡Has repasado todos los aciertos!'
      });
      setRespuestaAciertoSeleccionada(null);
      setAciertoYaRespondido(false);
      setRespuestaTextualAcierto('');
      setHistorialIntentosAcierto([]);
      setFeedbackIAAcierto(null);
      avanzarFase();
      return;
    }
    
    if (indiceAciertoActual >= nuevosAciertos.length) {
      setIndiceAciertoActual(nuevosAciertos.length - 1);
    }
    
    // Resetear estados
    setRespuestaAciertoSeleccionada(null);
    setAciertoYaRespondido(false);
    setRespuestaTextualAcierto('');
    setHistorialIntentosAcierto([]);
    setFeedbackIAAcierto(null);
  };
  
  const siguienteAcierto = () => {
    if (indiceAciertoActual < aciertosRepaso.length - 1) {
      setIndiceAciertoActual(indiceAciertoActual + 1);
      setRespuestaAciertoSeleccionada(null);
      setAciertoYaRespondido(false);
      setRespuestaTextualAcierto('');
      setHistorialIntentosAcierto([]);
      setFeedbackIAAcierto(null);
    } else {
      avanzarFase();
    }
  };
  
  // ============================================
  // 🧠 ALGORITMO SM-2 DE REPETICIÓN ESPACIADA
  // ============================================
  
  /**
   * Calcula la próxima revisión según el algoritmo SM-2 (SuperMemo 2)
   * @param {Object} item - Item a evaluar (flashcard, nota, práctica, etc.)
   * @param {String} dificultad - 'facil', 'medio', 'dificil'
   * @returns {Object} Item actualizado con nuevos valores de revisión
   */
  const calcularProximaRevision = (item, dificultad) => {
    // dificultad: 'facil', 'medio', 'dificil'
    let { intervalo, repeticiones, facilidad } = item;
    let nuevoIntervalo = intervalo || 1;
    let nuevasRepeticiones = repeticiones || 0;
    let nuevaFacilidad = facilidad || 2.5;
    
    const ahora = new Date();
    
    console.log('📊 calcularProximaRevision:', {
      titulo: item.titulo || item.frente || item.pregunta,
      dificultad,
      intervaloActual: intervalo,
      repeticionesActuales: repeticiones
    });
    
    // 🔥 LÓGICA SIMPLIFICADA SEGÚN BOTÓN PRESIONADO
    if (dificultad === 'dificil') {
      // 😰 Lo Olvidé - Revisar pronto (mañana)
      nuevoIntervalo = 1;
      nuevasRepeticiones = 0; // Reiniciar contador
      nuevaFacilidad = Math.max(1.3, nuevaFacilidad - 0.2);
    } else if (dificultad === 'medio') {
      // 🤔 Me Costó - Intervalo medio
      if (nuevasRepeticiones === 0) {
        nuevoIntervalo = 3; // 3 días
      } else {
        nuevoIntervalo = Math.round((intervalo || 1) * 1.5); // 1.5x intervalo anterior
      }
      nuevasRepeticiones += 1;
      nuevaFacilidad = Math.max(1.3, nuevaFacilidad - 0.1);
    } else if (dificultad === 'facil') {
      // 😎 Lo Recordé Fácil - Intervalo largo
      if (nuevasRepeticiones === 0) {
        nuevoIntervalo = 7; // 7 días
      } else if (nuevasRepeticiones === 1) {
        nuevoIntervalo = 14; // 14 días
      } else {
        nuevoIntervalo = Math.round((intervalo || 1) * nuevaFacilidad); // Factor de facilidad
      }
      nuevasRepeticiones += 1;
      nuevaFacilidad = nuevaFacilidad + 0.1;
    }
    
    // Límites de intervalo
    nuevoIntervalo = Math.max(1, Math.min(nuevoIntervalo, 365));
    nuevaFacilidad = Math.max(1.3, Math.min(nuevaFacilidad, 3.0));
    
    // Calcular próxima fecha de revisión (inicio del día)
    const proximaFecha = new Date(ahora);
    proximaFecha.setHours(0, 0, 0, 0);
    proximaFecha.setDate(proximaFecha.getDate() + nuevoIntervalo);
    
    const itemActualizado = {
      ...item,
      ultima_revision: ahora.toISOString(),
      fechaRevision: ahora.toISOString(),
      proximaRevision: proximaFecha.toISOString(),
      intervalo: nuevoIntervalo,
      repeticiones: nuevasRepeticiones,
      facilidad: nuevaFacilidad,
      estadoRevision: nuevasRepeticiones >= 5 ? 'dominada' : nuevasRepeticiones >= 2 ? 'en_progreso' : 'nueva',
      vistasHoy: 1 // 🔥 Marcar que ya se vio hoy
    };
    
    console.log('📊 Resultado:', {
      nuevoIntervalo,
      nuevasRepeticiones,
      proximaFecha: proximaFecha.toISOString().split('T')[0]
    });
    
    return itemActualizado;
  };
  
  /**
   * 🔥 FILTRA FLASHCARDS QUE SE PUEDEN VER HOY
   * Reglas:
   * 1. Solo 1 vez al día por flashcard
   * 2. Si es nueva, esperar 45 minutos desde creación
   * 3. Si tiene proximaRevision, solo si la fecha ya llegó o pasó
   */
  const filtrarItemsParaRepasar = (items) => {
    const ahora = new Date();
    const hoyInicio = new Date(ahora.getFullYear(), ahora.getMonth(), ahora.getDate(), 0, 0, 0);
    
    console.log('🔍 Filtrando flashcards para hoy:', {
      total: items.length,
      hora: ahora.toLocaleTimeString()
    });
    
    const itemsParaRepasar = items.filter(item => {
      const titulo = item.titulo || item.frente || item.id;
      
      // 🔥 REGLA 1: Si ya se vio hoy, NO mostrar
      const ultimaRevision = item.ultima_revision || item.ultimaRevision || item.fechaRevision;
      if (ultimaRevision) {
        const fechaUltima = new Date(ultimaRevision);
        const mismodia = fechaUltima >= hoyInicio;
        
        if (mismodia) {
          console.log(`🚫 Ya vista hoy: ${titulo}`);
          return false;
        }
      }
      
      // 🔥 REGLA 2: Si es nueva (sin proximaRevision), esperar 45 minutos desde creación
      if (!item.proximaRevision) {
        const fechaCreacion = item.fecha_creacion || item.fecha;
        if (fechaCreacion) {
          const creacion = new Date(fechaCreacion);
          const minutosDesdeCreacion = (ahora - creacion) / (1000 * 60);
          
          if (minutosDesdeCreacion < 45) {
            const minutosRestantes = Math.ceil(45 - minutosDesdeCreacion);
            console.log(`⏳ Esperar ${minutosRestantes} min más: ${titulo}`);
            return false;
          }
        }
        console.log(`✅ Nueva lista para revisar: ${titulo}`);
        return true;
      }
      
      // 🔥 REGLA 3: Si tiene proximaRevision, verificar si la fecha ya llegó
      const fechaRevision = new Date(item.proximaRevision);
      const diaRevision = new Date(fechaRevision.getFullYear(), fechaRevision.getMonth(), fechaRevision.getDate());
      
      if (diaRevision <= hoyInicio) {
        console.log(`✅ Toca hoy o antes: ${titulo}`);
        return true;
      } else {
        console.log(`⏭️ Programada para después: ${titulo} (${diaRevision.toISOString().split('T')[0]})`);
        return false;
      }
    });
    
    console.log(`📊 Resultado: ${itemsParaRepasar.length}/${items.length} flashcards para hoy`);
    
    return itemsParaRepasar;
  };
  
  /**
   * Calcula el rendimiento de una carpeta basado en el estado de sus items
   * @param {String} rutaCarpeta - Ruta de la carpeta
   * @returns {Object} Estadísticas de rendimiento
   */
  const calcularRendimientoCarpeta = async (rutaCarpeta) => {
    const flashcards = await cargarTodasFlashcards();
    const notas = await getDatos('notas');
    const practicas = await getDatos('practicas');
    
    const itemsCarpeta = [
      ...flashcards.filter(f => f.carpeta && f.carpeta.includes(rutaCarpeta)),
      ...notas.filter(n => n.carpeta && n.carpeta.includes(rutaCarpeta)),
      ...practicas.filter(p => p.carpeta && p.carpeta.includes(rutaCarpeta))
    ];
    
    const total = itemsCarpeta.length;
    const dominadas = itemsCarpeta.filter(i => i.estadoRevision === 'dominada').length;
    const enProgreso = itemsCarpeta.filter(i => i.estadoRevision === 'en_progreso').length;
    const nuevas = itemsCarpeta.filter(i => !i.estadoRevision || i.estadoRevision === 'nueva').length;
    
    const porcentajeDominado = total > 0 ? Math.round((dominadas / total) * 100) : 0;
    
    return {
      total,
      dominadas,
      enProgreso,
      nuevas,
      porcentajeDominado
    };
  };
  
  /**
   * Genera un mapa de repeticiones futuras para un item
   * Simula las próximas 10 repeticiones con diferentes escenarios
   * @param {Object} item - Item a analizar
   * @returns {Object} Mapa con escenarios de repetición
   */
  const generarMapaRepeticiones = (item) => {
    const fechaInicial = item.proximaRevision ? new Date(item.proximaRevision) : new Date();
    const intervaloActual = item.intervalo || 1;
    const facilidadActual = item.facilidad || 2.5;
    const repeticionesActuales = item.repeticiones || 0;
    
    // Generar 3 escenarios: siempre fácil, siempre medio, siempre difícil
    const escenarios = {
      facil: [],
      medio: [],
      dificil: []
    };
    
    // Simular cada escenario
    ['facil', 'medio', 'dificil'].forEach(dificultad => {
      let fecha = new Date(fechaInicial);
      let intervalo = intervaloActual;
      let facilidad = facilidadActual;
      let repeticiones = repeticionesActuales;
      
      for (let i = 0; i < 10; i++) {
        // Calcular siguiente intervalo según dificultad
        let nuevoIntervalo;
        let nuevaFacilidad = facilidad;
        
        if (repeticiones === 0) {
          nuevoIntervalo = 1;
        } else if (repeticiones === 1) {
          nuevoIntervalo = 6;
        } else {
          if (dificultad === 'facil') {
            nuevaFacilidad = Math.min(facilidad + 0.15, 2.5);
            nuevoIntervalo = Math.round(intervalo * nuevaFacilidad);
          } else if (dificultad === 'medio') {
            nuevoIntervalo = Math.round(intervalo * facilidad);
          } else { // difícil
            nuevaFacilidad = Math.max(facilidad - 0.2, 1.3);
            nuevoIntervalo = Math.max(1, Math.round(intervalo * 0.5));
          }
        }
        
        // Calcular próxima fecha
        const proximaFecha = new Date(fecha.getTime() + nuevoIntervalo * 24 * 60 * 60 * 1000);
        
        escenarios[dificultad].push({
          repeticion: repeticiones + 1,
          fecha: proximaFecha,
          intervalo: nuevoIntervalo,
          facilidad: nuevaFacilidad,
          diasDesdeHoy: Math.ceil((proximaFecha - new Date()) / (1000 * 60 * 60 * 24))
        });
        
        // Actualizar para siguiente iteración
        fecha = proximaFecha;
        intervalo = nuevoIntervalo;
        facilidad = nuevaFacilidad;
        repeticiones++;
      }
    });
    
    return {
      item,
      fechaInicial,
      escenarios
    };
  };
  
  // ============================================
  // 🎴 FUNCIONES FASE 3 - FLASHCARDS
  // ============================================

  // Función auxiliar para guardar flashcards en su carpeta correspondiente
  const guardarFlashcardEnCarpeta = async (flashcard) => {
    const carpeta = flashcard.carpeta || '';
    
    if (!carpeta) {
      console.warn('⚠️ Flashcard sin carpeta, usando "Sin carpeta":', flashcard.id);
      flashcard.carpeta = 'Sin carpeta';
    }
    
    try {
      const response = await fetch(`${API_URL}/datos/flashcards/carpeta`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          flashcard: flashcard,
          carpeta: flashcard.carpeta
        })
      });

      if (!response.ok) throw new Error('Error al guardar flashcard');
      
      return await response.json();
    } catch (error) {
      console.error('Error guardando flashcard en carpeta:', error);
      throw error;
    }
  };

  // 🖼️ FUNCIÓN PARA GUARDAR IMAGEN INMEDIATAMENTE AL CARGAR
  // Esta función se llama cuando el usuario carga una imagen en picture_description
  const guardarImagenInmediata = async (base64Data, preguntaIndex, pregunta) => {
    try {
      // Obtener la carpeta de la práctica actual
      const carpeta = examenActivo?.carpeta || 
                      carpetaSeleccionada?.nombre || 
                      practicas[practicaIndex]?.carpeta ||
                      'Sin carpeta';
      
      console.log(`📸 Guardando imagen inmediatamente...`);
      console.log(`   Carpeta: ${carpeta}`);
      console.log(`   Pregunta index: ${preguntaIndex}`);
      
      // Obtener nombre del archivo
      const nombreArchivo = pregunta?.metadata?.imagen?.nombre_archivo_sugerido || 
                           pregunta?.imagen?.nombre_archivo_sugerido ||
                           `imagen_pregunta_${preguntaIndex}.png`;
      
      console.log(`   Nombre archivo: ${nombreArchivo}`);
      
      // Enviar al servidor
      const response = await fetch(`${API_URL}/api/guardar-imagen-practica`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          carpeta: carpeta,
          base64: base64Data,
          nombre_archivo: nombreArchivo
        })
      });
      
      if (response.ok) {
        const datos = await response.json();
        console.log(`✅ Imagen guardada en: ${datos.ruta}`);
        
        // Actualizar la pregunta en el estado para persistir la ruta
        const preguntasActualizadas = [...preguntasExamen];
        if (preguntasActualizadas[preguntaIndex]) {
          if (!preguntasActualizadas[preguntaIndex].metadata) {
            preguntasActualizadas[preguntaIndex].metadata = {};
          }
          if (!preguntasActualizadas[preguntaIndex].metadata.imagen) {
            preguntasActualizadas[preguntaIndex].metadata.imagen = {};
          }
          preguntasActualizadas[preguntaIndex].metadata.imagen.url = datos.ruta;
          setPreguntasExamen(preguntasActualizadas);
          
          // También actualizar en la práctica si está disponible
          if (examenActivo && examenActivo.preguntas) {
            const practicaActualizada = {
              ...examenActivo,
              preguntas: preguntasActualizadas
            };
            // Guardar la práctica actualizada
            await guardarPracticaEnCarpeta(practicaActualizada, {[preguntaIndex]: base64Data});
            console.log(`✅ Práctica actualizada con la nueva imagen`);
          }
        }
        
        return datos.ruta;
      } else {
        console.error(`❌ Error guardando imagen: ${response.status}`);
        const errorText = await response.text();
        console.error(`   Detalle: ${errorText}`);
        return null;
      }
    } catch (error) {
      console.error('❌ Error al guardar imagen inmediata:', error);
      return null;
    }
  };

  // Función auxiliar para guardar prácticas en su carpeta correspondiente
  // 🖼️ NUEVA FUNCIÓN: Procesar imágenes de picture_description
  const procesarImagenesPractica = async (practica, imagenesGuardadas = {}) => {
    try {
      console.log('🖼️ Procesando imágenes de picture_description...');
      console.log('   Imágenes recibidas:', Object.keys(imagenesGuardadas).length);
      console.log('   Índices de imágenes:', Object.keys(imagenesGuardadas));
      console.log('   Total de preguntas:', practica.preguntas?.length);
      
      // Log detallado de cada pregunta
      practica.preguntas?.forEach((p, idx) => {
        console.log(`   Pregunta ${idx}: tipo=${p.tipo}, imagen=${!!imagenesGuardadas[idx]}`);
      });
      
      if (!practica.preguntas || Object.keys(imagenesGuardadas).length === 0) {
        console.log('ℹ️ No hay imágenes que procesar');
        return practica;
      }
      
      const practicaProcessada = JSON.parse(JSON.stringify(practica)); // Deep copy
      
      for (let i = 0; i < practicaProcessada.preguntas.length; i++) {
        const pregunta = practicaProcessada.preguntas[i];
        
        // Solo procesar preguntas de tipo picture_description
        if (pregunta.tipo !== 'picture_description') {
          continue;
        }
        
        // Si hay una imagen local (base64) para esta pregunta
        if (imagenesGuardadas[i]) {
          console.log(`📸 Pregunta ${i}: Encontrada imagen local, procesando...`);
          
          // Obtener nombre del archivo sugerido
          const nombreArchivo = pregunta.metadata?.imagen?.nombre_archivo_sugerido || 
                               pregunta.imagen?.nombre_archivo_sugerido ||
                               `imagen_pregunta_${i}.png`;
          
          try {
            // Enviar imagen al servidor para guardarla
            const responseImagen = await fetch(`${API_URL}/api/guardar-imagen-practica`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                carpeta: practica.carpeta || 'Sin carpeta',
                base64: imagenesGuardadas[i],
                nombre_archivo: nombreArchivo
              })
            });
            
            if (responseImagen.ok) {
              const datosImagen = await responseImagen.json();
              const rutaImagen = datosImagen.ruta; // p.ej: "extracciones/🌐 Plataforma - Cosas/imagen.png"
              
              console.log(`✅ Imagen guardada en: ${rutaImagen}`);
              
              // Actualizar la URL en la pregunta (en metadata.imagen.url e imagen.url)
              if (pregunta.metadata?.imagen) {
                pregunta.metadata.imagen.url = rutaImagen;
              }
              if (pregunta.imagen) {
                pregunta.imagen.url = rutaImagen;
              }
            } else {
              console.warn(`⚠️ Error guardando imagen para pregunta ${i}: ${responseImagen.status}`);
            }
          } catch (errorImagen) {
            console.warn(`⚠️ Error al procesar imagen pregunta ${i}:`, errorImagen);
            // Continuar con las demás imágenes
          }
        }
      }
      
      console.log('✅ Procesamiento de imágenes completado');
      return practicaProcessada;
    } catch (error) {
      console.error('❌ Error en procesarImagenesPractica:', error);
      return practica; // Retornar la práctica original si hay error
    }
  };

  const guardarPracticaEnCarpeta = async (practica, imagenesGuardadas = null) => {
    const carpeta = practica.carpeta || '';
    
    if (!carpeta) {
      console.warn('⚠️ Práctica sin carpeta, usando "Sin carpeta":', practica.id);
      practica.carpeta = 'Sin carpeta';
    }
    
    try {
      // 🔥 PROCESAR IMÁGENES ANTES DE GUARDAR
      // Si no se pasan imágenes, usar imagenesLocales (fallback)
      const imagenesAux = imagenesGuardadas || imagenesLocales || {};
      console.log('🖼️ Procesando imágenes de la práctica...');
      console.log('   Imágenes disponibles:', Object.keys(imagenesAux).length);
      practica = await procesarImagenesPractica(practica, imagenesAux);
      console.log('✅ Imágenes procesadas');
      
      // 🔥 VERIFICAR SI ES ARCHIVO INDIVIDUAL (resultados_practicas/examen_*.json)
      const esArchivoIndividual = practica.carpeta_ruta && practica.archivo;
      
      if (esArchivoIndividual) {
        // Usar endpoint para actualizar archivo individual
        console.log('📝 Actualizando archivo individual de práctica:');
        console.log('   archivo:', practica.archivo);
        console.log('   carpeta_ruta:', practica.carpeta_ruta);
        console.log('   id:', practica.id);
        
        const response = await fetch(`${API_URL}/datos/practicas/actualizar_archivo`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            practica: practica
          })
        });

        if (!response.ok) {
          const errorText = await response.text();
          console.error('❌ Error del backend:', errorText);
          console.error('❌ Status:', response.status);
          console.error('❌ StatusText:', response.statusText);
          throw new Error('Error al actualizar archivo de práctica');
        }
        
        const resultado = await response.json();
        console.log('✅ Respuesta del backend:', resultado);
        return resultado;
      } else {
        // Usar endpoint legacy para practicas.json
        const response = await fetch(`${API_URL}/datos/practicas/carpeta`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            practica: practica,
            carpeta: practica.carpeta
          })
        });

        if (!response.ok) throw new Error('Error al guardar práctica');
        
        return await response.json();
      }
    } catch (error) {
      console.error('Error guardando práctica en carpeta:', error);
      throw error;
    }
  };

