  // Renderizar contenido estilo Notion
  const renderizarContenidoNotion = (texto) => {
    if (!texto) return '';
    
    let html = texto;
    
    // Headers
    html = html.replace(/^### (.+)$/gm, '<h3 class="notion-h3">$1</h3>');
    html = html.replace(/^## (.+)$/gm, '<h2 class="notion-h2">$1</h2>');
    html = html.replace(/^# (.+)$/gm, '<h1 class="notion-h1">$1</h1>');
    
    // Listas
    html = html.replace(/^• (.+)$/gm, '<li class="notion-li">$1</li>');
    html = html.replace(/^- \[ \] (.+)$/gm, '<div class="notion-todo"><input type="checkbox" disabled /> <span>$1</span></div>');
    html = html.replace(/^- \[x\] (.+)$/gm, '<div class="notion-todo done"><input type="checkbox" checked disabled /> <span>$1</span></div>');
    html = html.replace(/^\d+\. (.+)$/gm, '<li class="notion-ol">$1</li>');
    
    // Callout
    html = html.replace(/💡 \*\*(.+?):\*\*\n(.+)/g, '<div class="notion-callout"><div class="callout-icon">💡</div><div class="callout-content"><strong>$1</strong><br/>$2</div></div>');
    
    // Quote
    html = html.replace(/^> (.+)$/gm, '<blockquote class="notion-quote">$1</blockquote>');
    
    // Divider
    html = html.replace(/^---$/gm, '<hr class="notion-divider" />');
    
    // Code block
    html = html.replace(/```(\w+)?\n([\s\S]+?)```/g, '<pre class="notion-code"><code>$2</code></pre>');
    
    // Inline code
    html = html.replace(/`([^`]+)`/g, '<code class="notion-inline-code">$1</code>');
    
    // Bold
    html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
    
    // Italic
    html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');
    
    // Links
    html = html.replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2" class="notion-link" target="_blank">$1</a>');
    
    // Paragraphs
    html = html.replace(/^(?!<[h|l|d|b|p])(.+)$/gm, '<p class="notion-p">$1</p>');
    
    return html;
  };
  
  // Auto-save de notas cada 30 segundos
  useEffect(() => {
    if (faseActual === 'contenido' && tabContenidoActivo === 2 && editorNotaContenido.trim()) {
      const timer = setTimeout(() => {
        // Auto-save en localStorage
        localStorage.setItem('nota_autosave', JSON.stringify({
          titulo: editorNotaTitulo,
          contenido: editorNotaContenido,
          tags: editorNotaTags,
          fecha: new Date().toISOString()
        }));
        console.log('Auto-save realizado');
      }, 30000);
      
      return () => clearTimeout(timer);
    }
  }, [editorNotaContenido, editorNotaTitulo, editorNotaTags, faseActual, tabContenidoActivo]);
  
  // Cargar contenido al entrar en Fase 4
  useEffect(() => {
    if (faseActual === 'contenido' && !documentoActual) {
      cargarContenidoFase4();
    }
  }, [faseActual]);
  
  // ============================================
  // 🎯 FUNCIONES FASE 5 - CIERRE/RESUMEN
  // ============================================
  
  const prepararResumenSesion = () => {
    const ahora = Date.now();
    const tiempoFinSesionMs = ahora;
    
    // Calcular tiempo total en minutos
    const tiempoTotalMs = tiempoFinSesionMs - tiempoInicioSesion;
    const tiempoTotalMin = Math.floor(tiempoTotalMs / 60000);
    
    // Calcular tiempo efectivo (sin pausas)
    const tiempoEfectivoMin = tiempoTotalMin - tiempoPausaTotal;
    
    // Filtrar documentos estudiados (progreso > 25%)
    const docsEstudiados = documentoActual && progresoDocumento > 25 ? 1 : 0;
    
    const resumen = {
      tiempoEfectivo: tiempoEfectivoMin,
      tiempoTotal: tiempoTotalMin,
      tiempoPausa: tiempoPausaTotal,
      erroresReforzados: estadisticasSesion.erroresReforzados,
      flashcardsRepasadas: estadisticasSesion.flashcardsRepasadas,
      documentosEstudiados: docsEstudiados,
      notasCreadas: estadisticasSesion.notasTomadas,
      practicasCompletadas: estadisticasSesion.practicasHechas
    };
    
    setResumenSesion(resumen);
    setTiempoFinSesion(ahora);
    
    // Cargar recomendaciones
    cargarRecomendacionesSesion();
  };
  
  const cargarRecomendacionesSesion = async () => {
    try {
      // Simulación de recomendaciones basadas en la sesión
      // En producción: GET /api/session/recommendations
      
      const recomendaciones = [];
      
      // Si hay errores no trabajados, recomendar
      if (estadisticasSesion.erroresReforzados < erroresActuales.length) {
        const pendientes = erroresActuales.length - estadisticasSesion.erroresReforzados;
        recomendaciones.push({
          tipo: 'errores',
          texto: `Repasar ${pendientes} errores pendientes`,
          prioridad: 'alta'
        });
      }
      
      // Si hay flashcards en el sistema, recomendar revisión
      const flashcardsTotal = JSON.parse(localStorage.getItem('flashcards') || '[]').length;
      if (flashcardsTotal > 0) {
        recomendaciones.push({
          tipo: 'flashcards',
          texto: `${flashcardsTotal} flashcards disponibles para revisar`,
          cantidad: flashcardsTotal
        });
      }
      
      // Si hay curso actual, recomendar continuar
      if (cursoActual) {
        recomendaciones.push({
          tipo: 'contenido',
          texto: `Continuar "${cursoActual.nombre}" (${cursoActual.progreso_curso}% completado)`,
          curso_id: cursoActual.id,
          progreso: cursoActual.progreso_curso
        });
      }
      
      setRecomendacionesSesion(recomendaciones);
      
    } catch (error) {
      console.error('Error cargando recomendaciones:', error);
    }
  };
  
  const finalizarYGuardarSesion = async () => {
    setGuardandoSesion(true);
    
    try {
      // Construir payload completo
      const payload = {
        sesion_id: `session_${tiempoInicioSesion}`,
        usuario_id: 'user_123', // En producción vendría del contexto de usuario
        fecha_inicio: new Date(tiempoInicioSesion).toISOString(),
        fecha_fin: new Date(tiempoFinSesion || Date.now()).toISOString(),
        configuracion: {
          duracion_planificada: tiempoSesion,
          prioridad: prioridadSesion
        },
        tiempos: {
          total_minutos: resumenSesion.tiempoTotal,
          pausa_minutos: resumenSesion.tiempoPausa,
          efectivo_minutos: resumenSesion.tiempoEfectivo
        },
        actividades: {
          errores_reforzados: resumenSesion.erroresReforzados,
          flashcards_repasadas: resumenSesion.flashcardsRepasadas,
          documentos_estudiados: documentoActual ? [{
            id: documentoActual.id,
            titulo: documentoActual.titulo,
            progreso: progresoDocumento
          }] : [],
          notas_creadas: resumenSesion.notasCreadas,
          practicas_completadas: resumenSesion.practicasCompletadas
        },
        reflexion: {
          dificil: reflexionDificil,
          revisar_manana: reflexionManana
        }
      };
      
      // Guardar en archivo (en producción: POST /api/session/finalize)
      const sesionesGuardadas = await getSesionesCompletadas();
      sesionesGuardadas.push(payload);
      await setSesionesCompletadas(sesionesGuardadas);
      
      // Simular delay de red
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      setMensaje({
        tipo: 'success',
        texto: '✅ Sesión guardada exitosamente'
      });
      
      // Esperar 1 segundo antes de redirect
      setTimeout(() => {
        redirigirAInicioDesdeResumen();
      }, 1000);
      
    } catch (error) {
      console.error('Error guardando sesión:', error);
      setMensaje({
        tipo: 'error',
        texto: 'Error al guardar sesión. Intenta nuevamente.'
      });
    } finally {
      setGuardandoSesion(false);
    }
  };
  
  const redirigirAInicioDesdeResumen = async () => {
    console.log('🏁 Finalizando sesión y limpiando todo...');
    
    // 🔥 CRÍTICO: Detener PRIMERO sesionActiva para que los useEffect dejen de ejecutarse
    setSesionActiva(false);
    
    // Pequeña espera para que React procese el cambio de estado
    await new Promise(resolve => setTimeout(resolve, 100));
    
    // 1️⃣ Cambiar menú para ocultar indicadores visuales
    setSelectedMenu('inicio');
    
    // 2️⃣ Limpiar estado de sesión completo (igual que detenerSesion)
    setTiempoRestante(0);
    setFaseActual(null);
    setIndiceFaseActual(0);
    setSesionPausada(false);
    setTiempoHastaDescanso(1500); // Resetear contador de descanso
    setEnDescanso(false);
    setTimestampInicioPausa(null);
    setTiempoFaseActual(0);
    setTiempoTotalEfectivo(0);
    setTiempoAcumuladoEstudio(0);
    setTiempoPausaRestante(0);
    
    // 3️⃣ Limpiar estadísticas
    setEstadisticasSesion({
      erroresReforzados: 0,
      flashcardsRepasadas: 0,
      practicasHechas: 0,
      notasTomadas: 0
    });
    
    // 4️⃣ Limpiar datos de fases
    setErroresActuales([]);
    setFlashcardsSesion([]);
    setDocumentoActual(null);
    setCursoActual(null);
    setNotasVinculadas([]);
    setFasesSesion([]);
    setIndiceErrorActual(0);
    setIndiceFlashcardActual(0);
    
    // 5️⃣ Limpiar datos de resumen
    setResumenSesion(null);
    setReflexionDificil('');
    setReflexionManana('');
    setRecomendacionesSesion([]);
    setTiempoInicioSesion(null);
    setTiempoFinSesion(null);
    setTiempoPausaTotal(0);
    
    // 6️⃣ ELIMINAR SESIÓN GUARDADA DEL BACKEND Y LOCALSTORAGE
    try {
      // Eliminar del backend
      const response = await fetch(`${API_URL}/sesion`, {
        method: 'DELETE'
      });
      
      if (response.ok) {
        console.log('✅ Sesión eliminada del backend');
      }
      
      // Eliminar de localStorage
      localStorage.removeItem('examinator_sesion_activa');
      setSesionPersistente(null);
      
      console.log('✅ Sesión finalizada y eliminada completamente');
    } catch (error) {
      console.error('❌ Error eliminando sesión al finalizar:', error);
      // Aunque falle el backend, limpiamos localStorage
      localStorage.removeItem('examinator_sesion_activa');
      setSesionPersistente(null);
    }
  };
  
  // Tracking de pausas para cálculo de tiempo efectivo
  useEffect(() => {
    if (sesionPausada && !timestampInicioPausa) {
      // Usuario acaba de pausar
      setTimestampInicioPausa(Date.now());
    } else if (!sesionPausada && timestampInicioPausa) {
      // Usuario acaba de reanudar
      const tiempoPausaMs = Date.now() - timestampInicioPausa;
      const tiempoPausaMin = Math.floor(tiempoPausaMs / 60000);
      setTiempoPausaTotal(prev => prev + tiempoPausaMin);
      setTimestampInicioPausa(null);
    }
  }, [sesionPausada]);
  
  // Actualizar contador de pausa cada segundo
  useEffect(() => {
    if (sesionPausada && timestampInicioPausa) {
      const intervalo = setInterval(() => {
        setContadorPausaActualizado(Date.now());
      }, 1000);
      return () => clearInterval(intervalo);
    }
  }, [sesionPausada, timestampInicioPausa]);

  // Cargar estado del índice del buscador al inicio
  useEffect(() => {
    if (selectedMenu === 'buscar') {
      cargarEstadoIndice();
    }
  }, [selectedMenu]);
  
  // Preparar resumen al entrar en Fase 5
  useEffect(() => {
    if (faseActual === 'cierre' && !resumenSesion) {
      prepararResumenSesion();
    }
  }, [faseActual]);
  
  // Guardar timestamp de inicio de sesión
  useEffect(() => {
    if (sesionActiva && !tiempoInicioSesion) {
      setTiempoInicioSesion(Date.now());
    }
  }, [sesionActiva]);
  
  // ============================================
  // FIN FUNCIONES FASE 5
  // ============================================
  
  // ============================================
  // FUNCIONES DE PERSISTENCIA DE SESIÓN
  // ============================================
  
  const guardarEstadoSesion = async () => {
    if (!sesionActiva) return;
    
    const estadoCompleto = {
      version: '1.0',
      timestamp: Date.now(),
      expiracion: Date.now() + (24 * 60 * 60 * 1000), // 24 horas
      
      // Configuración básica
      configuracion: {
        tiempoSesion,
        tiempoPersonalizado,
        modoLibreActivo,
        prioridadSesion
      },
      
      // Estado de la sesión
      estado: {
        sesionActiva,
        sesionPausada,
        faseActual,
        indiceFaseActual,
        tiempoRestante,
        tiempoFaseActual,
        tiempoTotalEfectivo,
        tiempoPausaTotal,
        tiempoInicioSesion,
        timestampInicioPausa
      },
      
      // Fases planificadas
      fases: fasesSesion,
      
      // Estadísticas
      estadisticas: estadisticasSesion,
      
      // Datos de cada fase
      datos: {
        calentamiento: datosCalentamiento,
        errores: {
          lista: erroresActuales,
          indiceActual: indiceErrorActual
        },
        flashcards: {
          lista: flashcardsSesion,
          indiceActual: indiceFlashcardActual
        },
        contenido: {
          tab: tabContenidoActivo,
          documento: documentoActual,
          curso: cursoActual,
          notasVinculadas,
          practicaGenerada,
          historialPracticas,
          progresoDocumento,
          scrollPositions
        },
        cierre: {
          resumen: resumenSesion,
          reflexionDificil,
          reflexionManana,
          recomendaciones: recomendacionesSesion
        }
      },
      
      // Notas en progreso
      notasEnProgreso: {
        titulo: editorNotaTitulo,
        contenido: editorNotaContenido,
        tags: editorNotaTags
      }
    };
    
    try {
      await setSesionActiva(estadoCompleto);
      setEstadoGuardado(true);
      setTimeout(() => setEstadoGuardado(false), 2000);
      console.log('✅ Estado de sesión guardado correctamente');
    } catch (error) {
      console.error('❌ Error guardando estado de sesión:', error);
    }
  };
  
  const cargarEstadoSesion = async () => {
    try {
      const estado = await getSesionActiva();
      if (!estado || Object.keys(estado).length === 0) return null;
      
      // Verificar expiración (24 horas)
      if (Date.now() > estado.expiracion) {
        console.log('⏰ Sesión expirada, eliminando...');
        await setSesionActiva({});
        return null;
      }
      
      return estado;
    } catch (error) {
      console.error('❌ Error cargando estado de sesión:', error);
      return null;
    }
  };
  
  const restaurarSesion = (estado) => {
    if (!estado) return;
    
    try {
      // Restaurar configuración
      setTiempoSesion(estado.configuracion.tiempoSesion);
      setTiempoPersonalizado(estado.configuracion.tiempoPersonalizado || '');
      setModoLibreActivo(estado.configuracion.modoLibreActivo || false);
      setPrioridadSesion(estado.configuracion.prioridadSesion);
      
      // Restaurar estado de sesión
      setSesionActiva(estado.estado.sesionActiva);
      setSesionPausada(estado.estado.sesionPausada);
      setFaseActual(estado.estado.faseActual);
      setIndiceFaseActual(estado.estado.indiceFaseActual);
      setTiempoRestante(estado.estado.tiempoRestante);
      setTiempoFaseActual(estado.estado.tiempoFaseActual);
      setTiempoTotalEfectivo(estado.estado.tiempoTotalEfectivo);
      setTiempoPausaTotal(estado.estado.tiempoPausaTotal || 0);
      setTiempoInicioSesion(estado.estado.tiempoInicioSesion);
      setTimestampInicioPausa(estado.estado.timestampInicioPausa);
      
      // Restaurar fases
      setFasesSesion(estado.fases || []);
      
      // Restaurar estadísticas
      setEstadisticasSesion(estado.estadisticas || {
        erroresReforzados: 0,
        flashcardsRepasadas: 0,
        practicasHechas: 0,
        notasTomadas: 0
      });
      
      // Restaurar datos de fases
      if (estado.datos) {
        setDatosCalentamiento(estado.datos.calentamiento);
        
        if (estado.datos.errores) {
          setErroresActuales(estado.datos.errores.lista || []);
          setIndiceErrorActual(estado.datos.errores.indiceActual || 0);
        }
        
        if (estado.datos.flashcards) {
          setFlashcardsSesion(estado.datos.flashcards.lista || []);
          setIndiceFlashcardActual(estado.datos.flashcards.indiceActual || 0);
        }
        
        if (estado.datos.contenido) {
          setTabContenidoActivo(estado.datos.contenido.tab || 0);
          setDocumentoActual(estado.datos.contenido.documento);
          setCursoActual(estado.datos.contenido.curso);
          setNotasVinculadas(estado.datos.contenido.notasVinculadas || []);
          setPracticaGenerada(estado.datos.contenido.practicaGenerada);
          setHistorialPracticas(estado.datos.contenido.historialPracticas || []);
          setProgresoDocumento(estado.datos.contenido.progresoDocumento || 0);
          setScrollPositions(estado.datos.contenido.scrollPositions || { 0: 0, 1: 0, 2: 0 });
        }
        
        if (estado.datos.cierre) {
          setResumenSesion(estado.datos.cierre.resumen);
          setReflexionDificil(estado.datos.cierre.reflexionDificil || '');
          setReflexionManana(estado.datos.cierre.reflexionManana || '');
          setRecomendacionesSesion(estado.datos.cierre.recomendaciones || []);
        }
      }
      
      // Restaurar notas en progreso
      if (estado.notasEnProgreso) {
        setEditorNotaTitulo(estado.notasEnProgreso.titulo || '');
        setEditorNotaContenido(estado.notasEnProgreso.contenido || '');
        setEditorNotaTags(estado.notasEnProgreso.tags || '');
      }
      
      // Cambiar a vista de sesión
      setSelectedMenu('sesion');
      setSesionPersistente(estado);
      
      console.log('✅ Sesión restaurada correctamente');
      
    } catch (error) {
      console.error('❌ Error restaurando sesión:', error);
    }
  };
  
  const eliminarSesionGuardada = async () => {
    try {
      // Eliminar del backend (getDatos/setDatos)
      await setSesionActiva({});
      // Eliminar del localStorage (legacy)
      localStorage.removeItem('examinator_sesion_activa');
      // Limpiar estado local
      setSesionPersistente(null);
      console.log('🗑️ Sesión guardada eliminada completamente');
    } catch (error) {
      console.error('❌ Error eliminando sesión:', error);
    }
  };
  
  // Auto-guardado cada 2 minutos cuando hay sesión activa
  useEffect(() => {
    let intervalo;
    
    // 🔥 CRÍTICO: Solo ejecutar si sesionActiva es true
    if (!sesionActiva) {
      if (intervalo) clearInterval(intervalo);
      return;
    }
    
    if (sesionActiva && !sesionPausada) {
      intervalo = setInterval(() => {
        guardarEstadoSesion();
      }, 120000); // 120000ms = 2 minutos
    }
    
    return () => {
      if (intervalo) {
        clearInterval(intervalo);
        console.log('⏹️ Auto-guardado detenido');
      }
    };
  }, [sesionActiva, sesionPausada, faseActual, tiempoRestante, estadisticasSesion]);
  
  // Guardar estado cuando cambia de fase o se pausa
  useEffect(() => {
    if (sesionActiva) {
      guardarEstadoSesion();
    }
  }, [faseActual, sesionPausada]);

  // 🔥 GUARDAR ESTADO AL CAMBIAR DE MENÚ (para no perder progreso)
  useEffect(() => {
    if (sesionActiva && selectedMenu !== 'sesion') {
      console.log('💾 Guardando sesión antes de cambiar de menú...');
      guardarEstadoSesion();
    }
  }, [selectedMenu]);
  
  // Detectar sesión guardada al montar el componente
  useEffect(() => {
    const sesionGuardada = cargarEstadoSesion();
    if (sesionGuardada) {
      setSesionPersistente(sesionGuardada);
      // Mostrar modal de confirmación en el UI
      console.log('🔄 Sesión guardada detectada');
    }
  }, []);
  
  // ============================================
  // FIN FUNCIONES DE PERSISTENCIA
  // ============================================
  
  // ============================================
  // FIN FUNCIONES FASE 4
  // ============================================
  
  const evaluarFlashcard_old = (dificultad) => {
    // dificultad: 'facil', 'medio', 'dificil'
    setEstadisticasSesion(prev => ({
      ...prev,
      flashcardsRepasadas: prev.flashcardsRepasadas + 1
    }));
    
    // Resetear estado de volteo para la siguiente flashcard
    setFlashcardsVolteadas({});
    
    if (indiceFlashcardActual < flashcardsSesion.length - 1) {
      setIndiceFlashcardActual(indiceFlashcardActual + 1);
    } else {
      // No hay más flashcards, avanzar fase
      avanzarFase();
    }
  };
  
  // ============================================
  // FIN FUNCIONES DEL MODO SESIÓN
  // ============================================
  
  // Obtener todos los archivos recursivamente de una carpeta
  const obtenerArchivosRecursivos = async (ruta) => {
    try {
      const response = await fetch(`${API_URL}/api/carpetas/archivos-recursivos?ruta=${encodeURIComponent(ruta)}`);
      const data = await response.json();
      return data.archivos || [];
    } catch (error) {
      console.error('Error obteniendo archivos:', error);
      return [];
    }
  };
  
  // Abrir modal de selección de archivos para generar examen
  const abrirGenerarExamenCarpeta = async (ruta, tipo) => {
    setMenuDropdownAbierto(false);
    setGenerandoExamen(true);
    setMensaje({
      tipo: 'info',
      texto: '🔍 Buscando archivos en todas las subcarpetas...'
    });
    
    // Obtener todos los archivos recursivamente
    const archivos = await obtenerArchivosRecursivos(ruta);
    
    if (archivos.length === 0) {
      setMensaje({
        tipo: 'error',
        texto: '❌ No se encontraron archivos en esta carpeta'
      });
      setGenerandoExamen(false);
      return;
    }
    
    // Extraer nombre de carpeta desde la ruta
    const nombreCarpeta = ruta.split(/[/\\]/).filter(Boolean).pop() || 'Sin nombre';
    
    setArchivosEncontrados(archivos);
    setArchivosExcluidos([]);
    setTipoCarpeta(tipo);
    // 🔥 GUARDAR INFO COMPLETA DE CARPETA PARA USAR AL GUARDAR EXAMEN
    setCarpetaExamen({ 
      ruta,  // Ruta completa para guardar en la misma ubicación
      nombre: nombreCarpeta,
      tipo: tipo  // curso, capitulo, clase, leccion
    });
    setModalSeleccionArchivos(true);
    setGenerandoExamen(false);
    
    setMensaje({
      tipo: 'success',
      texto: `✅ Se encontraron ${archivos.length} archivos`
    });
  };
  
  // Generar examen por bloques
  const generarExamenPorBloques = async () => {
    setModalSeleccionArchivos(false);
    setGenerandoExamenPorBloques(true);
    setProgresoGeneracion(0);
    
    // Filtrar archivos no excluidos
    const archivosIncluidos = archivosEncontrados.filter(
      archivo => !archivosExcluidos.includes(archivo.ruta)
    );
    
    if (archivosIncluidos.length === 0) {
      setMensaje({
        tipo: 'error',
        texto: '❌ Debes seleccionar al menos un archivo'
      });
      setGenerandoExamenPorBloques(false);
      return;
    }
    
    try {
      const totalPreguntasDeseadas = configExamenCarpeta.num_multiple + 
                                     configExamenCarpeta.num_corta + 
                                     configExamenCarpeta.num_vf + 
                                     configExamenCarpeta.num_desarrollo;
      
      // Si hay pocos archivos (<=10), generar todo de una vez
      if (archivosIncluidos.length <= 10) {
        setTotalBloques(1);
        setBloqueActual(1);
        setMensajeProgreso(`Generando ${totalPreguntasDeseadas} preguntas desde ${archivosIncluidos.length} archivos...`);
        setProgresoGeneracion(50);
        
        // Llamar al endpoint con TODOS los archivos
        const response = await fetch(`${API_URL}/api/generar_examen_bloque`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            archivos: archivosIncluidos.map(a => a.ruta),
            config: {
              num_multiple: configExamenCarpeta.num_multiple,
              num_corta: configExamenCarpeta.num_corta,
              num_vf: configExamenCarpeta.num_vf,
              num_desarrollo: configExamenCarpeta.num_desarrollo
            }
          })
        });
        
        if (!response.ok) {
          throw new Error('Error generando examen');
        }
        
        const data = await response.json();
        setProgresoGeneracion(100);
        
        setPreguntasExamen(data.preguntas || []);
        setRespuestasUsuario({});
        setExamenCompletado(false);
        setModalExamenAbierto(true);
        
        setMensaje({
          tipo: 'success',
          texto: `✅ Examen generado con ${data.preguntas?.length || 0} preguntas`
        });
        
        return;
      }
      
      // Para muchos archivos (>10), dividir en bloques
      const tamañoBloque = 5;
      const bloques = [];
      for (let i = 0; i < archivosIncluidos.length; i += tamañoBloque) {
        bloques.push(archivosIncluidos.slice(i, i + tamañoBloque));
      }
      
      setTotalBloques(bloques.length);
      const todasLasPreguntas = [];
      
      // Usar la variable ya declarada arriba
      const preguntasPorBloque = Math.ceil(totalPreguntasDeseadas / bloques.length);
      
      // Ajustar config para cada bloque (floor para evitar exceso)
      const configPorBloque = {
        num_multiple: Math.floor(configExamenCarpeta.num_multiple / bloques.length),
        num_corta: Math.floor(configExamenCarpeta.num_corta / bloques.length),
        num_vf: Math.floor(configExamenCarpeta.num_vf / bloques.length),
        num_desarrollo: Math.floor(configExamenCarpeta.num_desarrollo / bloques.length)
      };
      
      // Calcular residuos para distribuir en los primeros bloques
      const residuos = {
        num_multiple: configExamenCarpeta.num_multiple % bloques.length,
        num_corta: configExamenCarpeta.num_corta % bloques.length,
        num_vf: configExamenCarpeta.num_vf % bloques.length,
        num_desarrollo: configExamenCarpeta.num_desarrollo % bloques.length
      };
      
      // Procesar cada bloque
      for (let i = 0; i < bloques.length; i++) {
        setBloqueActual(i + 1);
        setMensajeProgreso(`Procesando bloque ${i + 1} de ${bloques.length}...`);
        setProgresoGeneracion(Math.round(((i + 1) / bloques.length) * 100));
        
        const bloque = bloques[i];
        
        // Config para este bloque específico (agregar residuos a los primeros bloques)
        const configBloqueActual = {
          num_multiple: configPorBloque.num_multiple + (i < residuos.num_multiple ? 1 : 0),
          num_corta: configPorBloque.num_corta + (i < residuos.num_corta ? 1 : 0),
          num_vf: configPorBloque.num_vf + (i < residuos.num_vf ? 1 : 0),
          num_desarrollo: configPorBloque.num_desarrollo + (i < residuos.num_desarrollo ? 1 : 0)
        };
        
        // Llamar al endpoint para generar preguntas de este bloque
        const response = await fetch(`${API_URL}/api/generar_examen_bloque`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            archivos: bloque.map(a => a.ruta),
            config: configBloqueActual  // Usar config ajustada para este bloque
          })
        });
        
        if (!response.ok) {
          throw new Error(`Error en bloque ${i + 1}`);
        }
        
        const data = await response.json();
        if (data.preguntas) {
          todasLasPreguntas.push(...data.preguntas);
        }
      }
      
      // Seleccionar las mejores preguntas
      setMensajeProgreso('Seleccionando las mejores preguntas...');
      const totalDeseado = configExamenCarpeta.num_multiple + 
                          configExamenCarpeta.num_corta + 
                          configExamenCarpeta.num_vf + 
                          configExamenCarpeta.num_desarrollo;
      
      const preguntasSeleccionadas = seleccionarMejoresPreguntas(todasLasPreguntas, totalDeseado, configExamenCarpeta);
      
      setPreguntasExamen(preguntasSeleccionadas);
      setRespuestasUsuario({});
      setExamenCompletado(false);
      setModalExamenAbierto(true);
      
      setMensaje({
        tipo: 'success',
        texto: `✅ Examen generado con ${preguntasSeleccionadas.length} preguntas`
      });
      
    } catch (error) {
      console.error('Error generando examen:', error);
      setMensaje({
        tipo: 'error',
        texto: `❌ Error: ${error.message}`
      });
    } finally {
      setGenerandoExamenPorBloques(false);
      setBloqueActual(0);
      setTotalBloques(0);
      setProgresoGeneracion(0);
    }
  };
  
  // Seleccionar las mejores preguntas (diversidad y relevancia)
  const seleccionarMejoresPreguntas = (preguntas, total, config) => {
    const seleccionadas = [];
    
    // Separar por tipo (aceptando variantes normalizadas del backend)
    const porTipo = {
      'multiple': preguntas.filter(p => p.tipo === 'multiple' || p.tipo === 'mcq'),
      'corta': preguntas.filter(p => p.tipo === 'corta' || p.tipo === 'short_answer'),
      'verdadero-falso': preguntas.filter(p => p.tipo === 'verdadero-falso' || p.tipo === 'true_false'),
      'desarrollo': preguntas.filter(p => p.tipo === 'desarrollo' || p.tipo === 'open_question')
    };
    
    // Seleccionar aleatoriamente de cada tipo
    if (config.num_multiple > 0) {
      seleccionadas.push(...seleccionarAleatorias(porTipo['multiple'], config.num_multiple));
    }
    if (config.num_corta > 0) {
      seleccionadas.push(...seleccionarAleatorias(porTipo['corta'], config.num_corta));
    }
    if (config.num_vf > 0) {
      seleccionadas.push(...seleccionarAleatorias(porTipo['verdadero-falso'], config.num_vf));
    }
    if (config.num_desarrollo > 0) {
      seleccionadas.push(...seleccionarAleatorias(porTipo['desarrollo'], config.num_desarrollo));
    }
    
    return seleccionadas;
  };
  
  // Seleccionar N elementos aleatorios de un array
  const seleccionarAleatorias = (array, n) => {
    const copia = [...array];
    const resultado = [];
    const cantidad = Math.min(n, copia.length);
    
    for (let i = 0; i < cantidad; i++) {
      const indice = Math.floor(Math.random() * copia.length);
      resultado.push(copia[indice]);
      copia.splice(indice, 1);
    }
    
    return resultado;
  };

  // Eliminar carpeta de exámenes
  const eliminarCarpetaExamenes = async (ruta, nombre) => {
    const confirmMsg = `¿Eliminar la carpeta de exámenes "${nombre}"?\n\nSe eliminarán TODOS los exámenes dentro (completados y en progreso).`
    if (!confirm(confirmMsg)) return

    try {
      const response = await fetch(`${API_URL}/api/examenes/carpeta?ruta=${encodeURIComponent(ruta)}&forzar=true`, {
        method: 'DELETE'
      })

      const data = await response.json()
      if (data.success) {
        setMensaje({
          tipo: 'success',
          texto: '✅ Carpeta de exámenes eliminada'
        })
        cargarCarpetasExamenes(rutaActualExamenes)
      }
    } catch (error) {
      setMensaje({
        tipo: 'error',
        texto: `❌ ${error.message}`
      })
    }
  }

  // Eliminar examen individual
  // Eliminar práctica individual
  const eliminarPractica = async (practica) => {
    const confirmMsg = `¿Eliminar la práctica "${practica.titulo || 'Sin título'}"?`
    if (!confirm(confirmMsg)) return

    try {
      console.log('🗑️ Eliminando práctica:', practica);
      
      const archivo = practica.archivo || '';
      const carpeta_ruta = practica.carpeta_ruta || practica.carpeta || '';
      const practica_id = practica.id;
      
      // Ya no requerimos archivo y carpeta_ruta obligatorios
      // El backend puede buscar por ID en archivos centralizados
      
      console.log('📁 Archivo:', archivo);
      console.log('📁 Carpeta:', carpeta_ruta);
      console.log('🆔 ID:', practica_id);
      
      const response = await fetch(`${API_URL}/datos/practicas/eliminar`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          archivo: archivo,
          carpeta_ruta: carpeta_ruta,
          id: practica_id
        })
      });
      
      if (!response.ok) {
        const errorText = await response.text()
        throw new Error(`Error ${response.status}: ${errorText}`)
      }
      
      const data = await response.json()
      if (data.success) {
        setMensaje({
          tipo: 'success',
          texto: '✅ Práctica eliminada'
        })
        
        // 🔥 RECARGAR PRÁCTICAS desde el servidor para actualizar la lista
        const practicasActualizadas = await getDatos('practicas');
        if (practicasActualizadas) {
          setPracticas(practicasActualizadas);
        }
        
        // Recargar calendario para reflejar cambios
        await recargarCalendarioRepasos()
        
        // Recargar las carpetas de prácticas si estamos en esa vista
        if (rutaPracticasActual !== undefined) {
          await cargarCarpetasPracticas(rutaPracticasActual)
        }
      } else {
        throw new Error(data.message || 'Error desconocido')
      }
    } catch (error) {
      console.error('Error eliminando práctica:', error)
      setMensaje({
        tipo: 'error',
        texto: `❌ Error eliminando práctica: ${error.message}`
      })
    }
  }

  // 🔥 Eliminar una pregunta específica de una práctica
  const eliminarPreguntaPractica = async (preguntaIndex, practicaOverride = null) => {
    const confirmMsg = `¿Eliminar la pregunta ${preguntaIndex + 1}? Esta acción no se puede deshacer.`;
    if (!confirm(confirmMsg)) return;

    try {
      // Usar practicaOverride si se proporciona (para viendoExamen), sino usar examenActivo o viendoExamen
      const practica = practicaOverride || examenActivo || viendoExamen;
      console.log('🗑️ Eliminando pregunta:', preguntaIndex, 'de práctica:', practica);
      
      const response = await fetch(`${API_URL}/datos/practicas/eliminar-pregunta`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          practica_id: practica?.id,
          pregunta_index: preguntaIndex,
          archivo: practica?.archivo,
          carpeta_ruta: carpetaExamen?.ruta || practica?.carpeta_ruta
        })
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Error ${response.status}: ${errorText}`);
      }

      const data = await response.json();
      
      // Si la práctica fue eliminada completamente (no quedaban preguntas)
      if (data.practica_eliminada) {
        setMensaje({
          tipo: 'success',
          texto: '✅ Práctica eliminada (no quedaban preguntas)'
        });
        // Cerrar el modal
        setModalExamenAbierto(false);
        setViendoExamen(null);
        setExamenActivo(null);
        setPreguntasExamen([]);
        setRespuestasUsuario({});
        setExamenCompletado(false);
        setResultadoExamen(null);
        // Recargar prácticas
        const practicasActualizadas = await getDatos('practicas');
        if (practicasActualizadas) {
          setPracticas(practicasActualizadas);
        }
        return;
      }

      // Actualizar las preguntas localmente
      const nuevasPreguntas = [...preguntasExamen];
      nuevasPreguntas.splice(preguntaIndex, 1);
      setPreguntasExamen(nuevasPreguntas);

      // Si estamos viendo resultados, actualizar también el resultado
      if (resultadoExamen) {
        const nuevosResultados = [...resultadoExamen.resultados];
        if (preguntaIndex < nuevosResultados.length) {
          nuevosResultados.splice(preguntaIndex, 1);
        }
        setResultadoExamen({
          ...resultadoExamen,
          resultados: nuevosResultados,
          puntos_totales: data.practica_actualizada?.puntos_totales || resultadoExamen.puntos_totales,
          puntos_obtenidos: data.practica_actualizada?.puntos_obtenidos || resultadoExamen.puntos_obtenidos,
          porcentaje: data.practica_actualizada?.porcentaje || resultadoExamen.porcentaje
        });
      }

      // Actualizar respuestas del usuario (reindexar)
      const nuevasRespuestas = {};
      Object.keys(respuestasUsuario).forEach(key => {
        const idx = parseInt(key);
        if (idx < preguntaIndex) {
          nuevasRespuestas[idx] = respuestasUsuario[idx];
        } else if (idx > preguntaIndex) {
          nuevasRespuestas[idx - 1] = respuestasUsuario[idx];
        }
      });
      setRespuestasUsuario(nuevasRespuestas);

      // 🔥 Si estamos viendo un examen guardado (viendoExamen), actualizar también
      if (viendoExamen) {
        const nuevosResultadosViendo = [...(viendoExamen.resultados || [])];
        if (preguntaIndex < nuevosResultadosViendo.length) {
          nuevosResultadosViendo.splice(preguntaIndex, 1);
        }
        setViendoExamen({
          ...viendoExamen,
          resultados: nuevosResultadosViendo,
          preguntas: viendoExamen.preguntas?.filter((_, i) => i !== preguntaIndex),
          puntos_totales: data.practica_actualizada?.puntos_totales || viendoExamen.puntos_totales,
          puntos_obtenidos: data.practica_actualizada?.puntos_obtenidos || viendoExamen.puntos_obtenidos,
          porcentaje: data.practica_actualizada?.porcentaje || viendoExamen.porcentaje
        });
      }

      setMensaje({
        tipo: 'success',
        texto: `✅ Pregunta ${preguntaIndex + 1} eliminada. Quedan ${data.preguntas_restantes} preguntas.`
      });

      // Recargar prácticas para mantener sincronizado
      const practicasActualizadas = await getDatos('practicas');
      if (practicasActualizadas) {
        setPracticas(practicasActualizadas);
      }

    } catch (error) {
      console.error('Error eliminando pregunta:', error);
      setMensaje({
        tipo: 'error',
        texto: `❌ Error eliminando pregunta: ${error.message}`
      });
    }
  };

  // 🔄 Abrir modal para regenerar una pregunta
  const abrirModalRegenerar = (preguntaIndex, pregunta, practicaOverride = null) => {
    setPreguntaARegenerar({
      index: preguntaIndex,
      pregunta: pregunta,
      practica: practicaOverride || examenActivo || viendoExamen
    });
    setInstruccionesRegenerar('');
    setModalRegenerarAbierto(true);
  };

  // 🔄 Regenerar una pregunta específica de una práctica
  const regenerarPreguntaPractica = async () => {
    if (!preguntaARegenerar) return;
    
    setRegenerandoPregunta(true);
    
    try {
      const { index, pregunta, practica } = preguntaARegenerar;
      console.log('🔄 Regenerando pregunta:', index, 'de práctica:', practica);
      
      const response = await fetch(`${API_URL}/datos/practicas/regenerar-pregunta`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          practica_id: practica?.id,
          pregunta_index: index,
          archivo: practica?.archivo,
          carpeta_ruta: carpetaExamen?.ruta || practica?.carpeta_ruta,
          instrucciones: instruccionesRegenerar,
          pregunta_actual: pregunta
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || `Error ${response.status}`);
      }

      const data = await response.json();
      
      // Actualizar las preguntas localmente
      if (preguntasExamen.length > 0) {
        const nuevasPreguntas = [...preguntasExamen];
        nuevasPreguntas[index] = data.pregunta_nueva;
        setPreguntasExamen(nuevasPreguntas);
      }

      // Si estamos viendo resultados, actualizar también
      if (resultadoExamen) {
        const nuevosResultados = [...resultadoExamen.resultados];
        if (index < nuevosResultados.length) {
          nuevosResultados[index] = {
            ...nuevosResultados[index],
            pregunta: data.pregunta_nueva.pregunta,
            respuesta_correcta: data.pregunta_nueva.respuesta_correcta,
            opciones: data.pregunta_nueva.opciones || []
          };
        }
        setResultadoExamen({
          ...resultadoExamen,
          resultados: nuevosResultados
        });
      }

      // Si estamos viendo un examen guardado
      if (viendoExamen) {
        const nuevosResultadosViendo = [...(viendoExamen.resultados || [])];
        if (index < nuevosResultadosViendo.length) {
          nuevosResultadosViendo[index] = {
            ...nuevosResultadosViendo[index],
            pregunta: data.pregunta_nueva.pregunta,
            respuesta_correcta: data.pregunta_nueva.respuesta_correcta,
            opciones: data.pregunta_nueva.opciones || []
          };
        }
        const nuevasPreguntas = [...(viendoExamen.preguntas || [])];
        if (index < nuevasPreguntas.length) {
          nuevasPreguntas[index] = data.pregunta_nueva;
        }
        setViendoExamen({
          ...viendoExamen,
          resultados: nuevosResultadosViendo,
          preguntas: nuevasPreguntas
        });
      }

      // Actualizar respuestas del usuario para esta pregunta
      setRespuestasUsuario(prev => {
        const nuevas = { ...prev };
        delete nuevas[index]; // Limpiar respuesta anterior
        return nuevas;
      });

      setMensaje({
        tipo: 'success',
        texto: `✅ Pregunta ${index + 1} regenerada exitosamente`
      });

      // Cerrar modal
      setModalRegenerarAbierto(false);
      setPreguntaARegenerar(null);

      // Recargar prácticas para mantener sincronizado
      const practicasActualizadas = await getDatos('practicas');
      if (practicasActualizadas) {
        setPracticas(practicasActualizadas);
      }

    } catch (error) {
      console.error('Error regenerando pregunta:', error);
      setMensaje({
        tipo: 'error',
        texto: `❌ Error regenerando pregunta: ${error.message}`
      });
    } finally {
      setRegenerandoPregunta(false);
    }
  };

  // ⚖️ Abrir modal para apelar una respuesta
  const abrirModalApelar = (preguntaIndex, resultado, practicaOverride = null) => {
    setPreguntaAApelar({
      index: preguntaIndex,
      resultado: resultado,
      practica: practicaOverride || examenActivo || viendoExamen
    });
    setArgumentoApelacion('');
    setModalApelarAbierto(true);
  };

  // ⚖️ Apelar una respuesta para recalificar
  const apelarRespuesta = async () => {
    if (!preguntaAApelar) return;
    
    setApelandoPregunta(true);
    
    try {
      const { index, resultado, practica } = preguntaAApelar;
      console.log('⚖️ Apelando respuesta:', index, 'de práctica:', practica);
      
      const response = await fetch(`${API_URL}/datos/practicas/apelar-respuesta`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          practica_id: practica?.id,
          pregunta_index: index,
          archivo: practica?.archivo,
          carpeta_ruta: carpetaExamen?.ruta || practica?.carpeta_ruta,
          argumento: argumentoApelacion,
          respuesta_usuario: resultado.respuesta_usuario,
          respuesta_correcta: resultado.respuesta_correcta,
          pregunta: resultado.pregunta
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || `Error ${response.status}`);
      }

      const data = await response.json();
      
      if (data.apelacion_aceptada) {
        // Actualizar los resultados localmente
        if (resultadoExamen) {
          const nuevosResultados = [...resultadoExamen.resultados];
          nuevosResultados[index] = {
            ...nuevosResultados[index],
            puntos: data.nuevos_puntos,
            feedback: data.nuevo_feedback,
            apelacion_aceptada: true,
            proximaRevision: data.proximaRevision,
            intervalo: data.intervalo
          };
          
          // Recalcular puntos totales
          const nuevosPuntosObtenidos = nuevosResultados.reduce((sum, r) => sum + (r.puntos || 0), 0);
          const nuevosPuntosTotales = nuevosResultados.reduce((sum, r) => sum + (r.puntos_maximos || 10), 0);
          const nuevoPorcentaje = nuevosPuntosTotales > 0 ? (nuevosPuntosObtenidos / nuevosPuntosTotales) * 100 : 0;
          
          setResultadoExamen({
            ...resultadoExamen,
            resultados: nuevosResultados,
            puntos_obtenidos: nuevosPuntosObtenidos,
            porcentaje: nuevoPorcentaje
          });
        }

        // Si estamos viendo un examen guardado
        if (viendoExamen) {
          const nuevosResultadosViendo = [...(viendoExamen.resultados || [])];
          nuevosResultadosViendo[index] = {
            ...nuevosResultadosViendo[index],
            puntos: data.nuevos_puntos,
            feedback: data.nuevo_feedback,
            apelacion_aceptada: true,
            proximaRevision: data.proximaRevision,
            intervalo: data.intervalo
          };
          
          const nuevosPuntosObtenidos = nuevosResultadosViendo.reduce((sum, r) => sum + (r.puntos || 0), 0);
          const nuevosPuntosTotales = nuevosResultadosViendo.reduce((sum, r) => sum + (r.puntos_maximos || 10), 0);
          const nuevoPorcentaje = nuevosPuntosTotales > 0 ? (nuevosPuntosObtenidos / nuevosPuntosTotales) * 100 : 0;
          
          setViendoExamen({
            ...viendoExamen,
            resultados: nuevosResultadosViendo,
            puntos_obtenidos: nuevosPuntosObtenidos,
            porcentaje: nuevoPorcentaje
          });
        }

        setMensaje({
          tipo: 'success',
          texto: `✅ ¡Apelación aceptada! Tu respuesta era correcta. Intervalo de repaso mejorado a ${data.intervalo} días.`
        });
      } else {
        setMensaje({
          tipo: 'warning',
          texto: `❌ Apelación rechazada: ${data.razon || 'La respuesta no es equivalente a la correcta.'}`
        });
      }

      // Cerrar modal
      setModalApelarAbierto(false);
      setPreguntaAApelar(null);

      // Recargar prácticas para mantener sincronizado
      const practicasActualizadas = await getDatos('practicas');
      if (practicasActualizadas) {
        setPracticas(practicasActualizadas);
      }

    } catch (error) {
      console.error('Error apelando respuesta:', error);
      setMensaje({
        tipo: 'error',
        texto: `❌ Error al apelar: ${error.message}`
      });
    } finally {
      setApelandoPregunta(false);
    }
  };

  const eliminarExamen = async (examen, tipo) => {
    const tipoTexto = tipo === 'progreso' ? 'en progreso' : 'completado'
    const confirmMsg = `¿Eliminar el examen ${tipoTexto} "${examen.carpeta_nombre}"?`
    if (!confirm(confirmMsg)) return

    try {
      // Determinar el nombre del archivo según el tipo
      let nombreArchivo = examen.archivo || (tipo === 'progreso' ? `examen_progreso_${examen.id}.json` : `examen_${examen.id}.json`)
      const ruta = examen.carpeta_ruta || rutaActualExamenes
      const examenId = examen.id || examen.archivo
      
      console.log('🗑️ Eliminando examen:', { ruta, nombreArchivo, examenId, examen });
      
      const response = await fetch(`${API_URL}/api/examenes/examen?ruta=${encodeURIComponent(ruta)}&archivo=${encodeURIComponent(nombreArchivo)}`, {
        method: 'DELETE'
      })

      if (!response.ok) {
        const errorText = await response.text()
        throw new Error(`Error ${response.status}: ${errorText}`)
      }

      const data = await response.json()
      if (data.success) {
        // Si era un examen en progreso, limpiar también el temporal
        if (tipo === 'progreso') {
          await limpiarExamenLocal()
          // Si es el examen activo, cerrarlo
          if (examenActivo) {
            setExamenActivo(false)
            setModalExamenAbierto(false)
            setPreguntasExamen([])
            setRespuestasUsuario({})
          }
        }
        
        // 🔥 ACTUALIZAR ESTADO LOCAL INMEDIATAMENTE
        // Eliminar del calendario sin esperar recarga
        // Usar múltiples criterios para asegurar eliminación completa
        setDatosCalendarioRepasos(prev => ({
          ...prev,
          examenes: prev.examenes.filter(e => {
            // Eliminar por ID
            if (e.id && e.id === examen.id) return false
            // Eliminar por archivo
            if (e.archivo && e.archivo === nombreArchivo) return false
            // Eliminar por carpeta + fecha (para duplicados)
            if (e.carpeta_ruta === ruta && e.fecha_completado === examen.fecha_completado) return false
            return true
          })
        }))
        
        const mensaje = data.archivos_eliminados > 1 
          ? `✅ Examen eliminado (${data.archivos_eliminados} copias encontradas)`
          : '✅ Examen eliminado'
        
        setMensaje({
          tipo: 'success',
          texto: mensaje
        })
        
        // Recargar la lista de carpetas y exámenes
        cargarCarpetasExamenes(rutaActualExamenes)
        
        // Recargar calendario después de un breve delay para asegurar que el archivo fue eliminado
        setTimeout(() => {
          recargarCalendarioRepasos()
        }, 800)
      }
    } catch (error) {
      console.error('Error eliminando examen:', error)
      setMensaje({
        tipo: 'error',
        texto: `❌ ${error.message}`
      })
    }
  }

  // Mostrar modal con la ruta del archivo
  const mostrarRutaArchivo = (ruta, nombre, tipo = 'archivo') => {
    setRutaArchivoSeleccionado(ruta)
    setNombreArchivoSeleccionado(nombre || 'Sin nombre')
    setModalRutaAbierto(true)
  }

  const copiarRutaAlPortapapeles = () => {
    navigator.clipboard.writeText(rutaArchivoSeleccionado)
      .then(() => {
        setMensaje({
          tipo: 'success',
          texto: '📋 Ruta copiada al portapapeles'
        })
      })
      .catch(() => {
        setMensaje({
          tipo: 'error',
          texto: '❌ Error al copiar ruta'
        })
      })
  }

  // Actualizar rutas en todos los datos almacenados cuando se renombra/mueve una carpeta
  const actualizarRutasEnDatos = async (rutaAntigua, rutaNueva) => {
    const normalizarRuta = (r) => (r || '').replace(/\//g, '\\').replace(/\\\\/g, '\\')
    const rutaAntiguaNorm = normalizarRuta(rutaAntigua)
    const rutaNuevaNorm = normalizarRuta(rutaNueva)
    
    console.log(`🔄 Actualizando rutas:`)
    console.log(`   Antigua: "${rutaAntiguaNorm}"`)
    console.log(`   Nueva: "${rutaNuevaNorm}"`)
    
    // Función para actualizar una ruta (exacta o como prefijo)
    const actualizarRuta = (ruta) => {
      if (!ruta) return ruta
      const rutaNorm = normalizarRuta(ruta)
      
      // Coincidencia exacta
      if (rutaNorm === rutaAntiguaNorm) {
        console.log(`   ✓ Ruta exacta actualizada: "${ruta}" → "${rutaNuevaNorm}"`)
        return rutaNuevaNorm
      }
      
      // Coincidencia como prefijo (subcarpeta)
      if (rutaNorm.startsWith(rutaAntiguaNorm + '\\')) {
        const nuevaRuta = rutaNuevaNorm + rutaNorm.slice(rutaAntiguaNorm.length)
        console.log(`   ✓ Subruta actualizada: "${ruta}" → "${nuevaRuta}"`)
        return nuevaRuta
      }
      
      return ruta
    }
    
    let totalActualizados = 0
    
    try {
      // Actualizar errores
      const errores = await getDatos('errores') || []
      let erroresModificados = 0
      const erroresActualizados = errores.map(e => {
        const nuevaCarpeta = actualizarRuta(e.carpeta)
        const nuevaRutaDoc = actualizarRuta(e.ruta_documento)
        if (nuevaCarpeta !== e.carpeta || nuevaRutaDoc !== e.ruta_documento) erroresModificados++
        return {
          ...e,
          carpeta: nuevaCarpeta,
          ruta_documento: nuevaRutaDoc
        }
      })
      if (erroresModificados > 0) {
        await setDatos('errores', erroresActualizados)
        console.log(`   📝 Errores actualizados: ${erroresModificados}`)
        totalActualizados += erroresModificados
      }
      
      // Actualizar flashcards
      const flashcards = await getDatos('flashcards') || []
      let flashcardsModificadas = 0
      const flashcardsActualizadas = flashcards.map(fc => {
        const nuevaCarpeta = actualizarRuta(fc.carpeta)
        const nuevaRuta = actualizarRuta(fc.ruta)
        if (nuevaCarpeta !== fc.carpeta || nuevaRuta !== fc.ruta) flashcardsModificadas++
        return {
          ...fc,
          carpeta: nuevaCarpeta,
          ruta: nuevaRuta
        }
      })
      if (flashcardsModificadas > 0) {
        await setDatos('flashcards', flashcardsActualizadas)
        console.log(`   🃏 Flashcards actualizadas: ${flashcardsModificadas}`)
        totalActualizados += flashcardsModificadas
      }
      
      // Actualizar exámenes
      const examenes = await getDatos('examenes') || []
      let examenesModificados = 0
      const examenesActualizados = examenes.map(ex => {
        const nuevaCarpeta = actualizarRuta(ex.carpeta)
        const nuevaRuta = actualizarRuta(ex.ruta)
        if (nuevaCarpeta !== ex.carpeta || nuevaRuta !== ex.ruta) examenesModificados++
        return {
          ...ex,
          carpeta: nuevaCarpeta,
          ruta: nuevaRuta
        }
      })
      if (examenesModificados > 0) {
        await setDatos('examenes', examenesActualizados)
        console.log(`   📝 Exámenes actualizados: ${examenesModificados}`)
        totalActualizados += examenesModificados
      }
      
      // Actualizar prácticas
      const practicas = await getDatos('practicas') || []
      let practicasModificadas = 0
      const practicasActualizadas = practicas.map(pr => {
        const nuevaCarpeta = actualizarRuta(pr.carpeta)
        const nuevaCarpetaRuta = actualizarRuta(pr.carpeta_ruta)
        if (nuevaCarpeta !== pr.carpeta || nuevaCarpetaRuta !== pr.carpeta_ruta) practicasModificadas++
        return {
          ...pr,
          carpeta: nuevaCarpeta,
          carpeta_ruta: nuevaCarpetaRuta
        }
      })
      if (practicasModificadas > 0) {
        await setDatos('practicas', practicasActualizadas)
        console.log(`   🧑‍💻 Prácticas actualizadas: ${practicasModificadas}`)
        totalActualizados += practicasModificadas
      }
      
      // Actualizar notas
      const notas = await getDatos('notas') || []
      let notasModificadas = 0
      const notasActualizadas = notas.map(n => {
        const nuevaCarpeta = actualizarRuta(n.carpeta)
        if (nuevaCarpeta !== n.carpeta) notasModificadas++
        return {
          ...n,
          carpeta: nuevaCarpeta
        }
      })
      if (notasModificadas > 0) {
        await setDatos('notas', notasActualizadas)
        console.log(`   📒 Notas actualizadas: ${notasModificadas}`)
        totalActualizados += notasModificadas
      }
      
      console.log(`✅ Total de items actualizados: ${totalActualizados}`)
      
      // Esperar a que el servidor procese los cambios y luego recalcular
      await new Promise(resolve => setTimeout(resolve, 500))
      await calcularRendimientoJerarquias()
      
    } catch (error) {
      console.error('❌ Error actualizando rutas en datos:', error)
    }
  }

  // Renombrar carpeta
  const renombrarCarpeta = async (ruta, nombreActual) => {
    const nuevoNombre = prompt(`Renombrar carpeta "${nombreActual}":`, nombreActual)
    if (!nuevoNombre || nuevoNombre === nombreActual) return

    try {
      const response = await fetch(`${API_URL}/api/carpetas/renombrar`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          ruta_actual: ruta,
          nuevo_nombre: nuevoNombre 
        })
      })

      const data = await response.json()
      if (data.success) {
        // Calcular la nueva ruta
        const partes = ruta.split('\\')
        partes[partes.length - 1] = nuevoNombre
        const nuevaRuta = partes.join('\\')
        
        // Actualizar rutas en todos los datos almacenados
        await actualizarRutasEnDatos(ruta, nuevaRuta)
        
        setMensaje({
          tipo: 'success',
          texto: `✅ Carpeta renombrada a "${nuevoNombre}"`
        })
        cargarCarpeta(rutaActual)
      }
    } catch (error) {
      setMensaje({
        tipo: 'error',
        texto: `❌ ${error.message}`
      })
    }
  }

  // Iniciar proceso de mover carpeta
  const iniciarMoverCarpeta = (carpeta) => {
    setMoverCarpeta(carpeta)
    setMenuAbierto(null)
    setModalMoverAbierto(true)
    setRutaDestinoSeleccionada(rutaActual)
    cargarCarpetasDestino(rutaActual)
  }

  // Cargar carpetas para selector de destino
  const cargarCarpetasDestino = async (ruta = '') => {
    try {
      const response = await fetch(`${API_URL}/api/carpetas?ruta=${encodeURIComponent(ruta)}`)
      const data = await response.json()
      setCarpetasDestino(data.carpetas || [])
      setRutaDestinoSeleccionada(ruta)
    } catch (error) {
      console.error('Error al cargar carpetas destino:', error)
    }
  }

  // Confirmar mover carpeta
  const confirmarMoverCarpeta = async () => {
    if (!moverCarpeta) return

    // Obtener la ruta padre de la carpeta actual
    const rutaPadreOrigen = moverCarpeta.ruta.split('\\').slice(0, -1).join('\\')

    // Validar que no se esté moviendo a su misma ubicación (mismo padre)
    if (rutaPadreOrigen === rutaDestinoSeleccionada) {
      setMensaje({
        tipo: 'error',
        texto: '❌ No puedes mover una carpeta a su misma ubicación actual'
      })
      return
    }

    // Validar que no se esté moviendo dentro de sí misma
    if (rutaDestinoSeleccionada.startsWith(moverCarpeta.ruta + '\\') || 
        rutaDestinoSeleccionada === moverCarpeta.ruta) {
      setMensaje({
        tipo: 'error',
        texto: '❌ No puedes mover una carpeta dentro de sí misma'
      })
      return
    }

    try {
      const response = await fetch(`${API_URL}/api/carpetas/mover`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ruta_origen: moverCarpeta.ruta,
          ruta_destino: rutaDestinoSeleccionada
        })
      })

      const data = await response.json()
      
      if (response.ok && data.success) {
        // Calcular la nueva ruta de la carpeta
        const nombreCarpeta = moverCarpeta.nombre
        const nuevaRuta = rutaDestinoSeleccionada 
          ? `${rutaDestinoSeleccionada}\\${nombreCarpeta}`
          : nombreCarpeta
        
        // Actualizar rutas en todos los datos almacenados
        await actualizarRutasEnDatos(moverCarpeta.ruta, nuevaRuta)
        
        setMensaje({
          tipo: 'success',
          texto: `✅ Carpeta "${moverCarpeta.nombre}" movida exitosamente`
        })
        setMoverCarpeta(null)
        setModalMoverAbierto(false)
        cargarCarpeta(rutaDestinoSeleccionada) // Recargar la carpeta destino
      } else {
        setMensaje({
          tipo: 'error',
          texto: `❌ ${data.detail || data.error || 'Error al mover carpeta'}`
        })
        setModalMoverAbierto(false)
      }
    } catch (error) {
      console.error('Error al mover carpeta:', error)
      setMensaje({
        tipo: 'error',
        texto: `❌ Error de conexión: ${error.message}`
      })
      setModalMoverAbierto(false)
    }
  }

  // Cancelar mover carpeta
  const cancelarMoverCarpeta = () => {
    setMoverCarpeta(null)
    setModalMoverAbierto(false)
    setRutaDestinoSeleccionada('')
    setCarpetasDestino([])
  }

  // Cargar configuración y modelos
  const cargarConfiguracion = async () => {
    setCargandoConfig(true)
    try {
      // Cargar configuración actual
      const configResponse = await fetch(`${API_URL}/api/config`)
      const configData = await configResponse.json()
      console.log('📥 Configuración cargada del servidor:', configData)
      console.log('   - usar_ollama:', configData.usar_ollama)
      console.log('   - gpu_activa:', configData.gpu_activa)
      console.log('   - modelo_cargado:', configData.modelo_cargado)
      console.log('   - tipo_motor:', configData.tipo_motor)
      
      // Verificar qué opción debería estar seleccionada
      if (configData.usar_ollama && configData.gpu_activa) {
        console.log('✅ Debería seleccionarse: Ollama GPU')
      } else if (configData.usar_ollama && !configData.gpu_activa) {
        console.log('✅ Debería seleccionarse: Ollama CPU')
      } else if (!configData.usar_ollama) {
        console.log('✅ Debería seleccionarse: GGUF CPU')
      }
      
      setConfiguracion(configData)
      setModeloSeleccionado(configData.modelo_path || null)
      
      // Cargar ajustes avanzados si existen en la configuración
      if (configData.ajustes_avanzados) {
        setAjustesAvanzados({
          n_ctx: configData.ajustes_avanzados.n_ctx || 4096,
          temperature: configData.ajustes_avanzados.temperature || 0.7,
          max_tokens: configData.ajustes_avanzados.max_tokens || 512,
          top_p: configData.ajustes_avanzados.top_p || 0.9,
          repeat_penalty: configData.ajustes_avanzados.repeat_penalty || 1.15
        })
        console.log('⚙️ Ajustes avanzados cargados:', configData.ajustes_avanzados)
      }

      // Cargar modelos instalados
      const modelosResponse = await fetch(`${API_URL}/api/modelos`)
      const modelosData = await modelosResponse.json()
      console.log('Modelos instalados:', modelosData)
      setModelosDisponibles(modelosData.modelos || [])

      // Cargar modelos disponibles para descargar
      const descargablesResponse = await fetch(`${API_URL}/api/modelos/disponibles`)
      const descargablesData = await descargablesResponse.json()
      console.log('Modelos para descargar:', descargablesData)
      setModelosParaDescargar(descargablesData.modelos || [])
    } catch (error) {
      console.error('Error al cargar configuración:', error)
      setMensaje({
        tipo: 'error',
        texto: `❌ Error al cargar configuración: ${error.message}`
      })
    } finally {
      setCargandoConfig(false)
    }
  }

  // Guardar configuración
  const guardarConfiguracion = async () => {
    if (!modeloSeleccionado) {
      setMensaje({
        tipo: 'error',
        texto: '❌ Debes seleccionar un modelo'
      })
      return
    }

    setCargandoConfig(true)
    try {
      const response = await fetch(`${API_URL}/api/config`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          modelo_path: modeloSeleccionado,
          ajustes_avanzados: ajustesAvanzados
        })
      })

      const data = await response.json()
      if (data.success) {
        setMensaje({
          tipo: 'success',
          texto: '✅ Modelo cambiado exitosamente. Recarga la configuración para verificar.'
        })
        // Recargar configuración para verificar
        cargarConfiguracion()
      } else {
        setMensaje({
          tipo: 'error',
          texto: `❌ ${data.message || 'Error al cambiar modelo'}`
        })
      }
    } catch (error) {
      setMensaje({
        tipo: 'error',
        texto: `❌ Error: ${error.message}`
      })
    } finally {
      setCargandoConfig(false)
    }
  }

  // Guardar solo ajustes avanzados (sin mostrar mensaje)
  const guardarAjustesAvanzados = async () => {
    try {
      // Obtener configuración actual
      const configResponse = await fetch(`${API_URL}/api/config`)
      const configData = await configResponse.json()
      
      // Guardar con ajustes actualizados
      await fetch(`${API_URL}/api/config`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          modelo_path: configData.modelo_path,
          ajustes_avanzados: ajustesAvanzados
        })
      })
      
      console.log('⚙️ Ajustes avanzados guardados:', ajustesAvanzados)
    } catch (error) {
      console.error('Error guardando ajustes:', error)
    }
  }

  // Enviar mensaje al chat
  const enviarMensajeChat = async () => {
    if (!inputChat.trim() || cargandoChat) return

    const mensaje = inputChat.trim()
    setInputChat('')
    
    // Agregar mensaje del usuario
    const horaNueva = new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })
    const mensajeUsuario = {
      tipo: 'usuario',
      texto: mensaje,
      hora: horaNueva
    }
    
    // Si hay archivo de contexto, agregarlo al mensaje
    if (archivoContexto) {
      mensajeUsuario.archivo = nombreArchivoContexto
    }
    
    // Si hay búsqueda web activa, agregarlo
    if (busquedaWebActiva) {
      mensajeUsuario.busqueda_web = true
    }
    
    // Construir historial ANTES de agregar el mensaje actual al estado
    // Esto asegura que el backend reciba el contexto completo
    const historialCompleto = [...mensajesChat, mensajeUsuario]
    
    setMensajesChat(prev => [...prev, mensajeUsuario])

    // Crear AbortController para poder cancelar la petición
    const controller = new AbortController()
    setAbortController(controller)

    setCargandoChat(true)
    try {
      console.log('\n' + '='.repeat(70))
      console.log('💬 ENVIANDO MENSAJE AL BACKEND')
      console.log('='.repeat(70))
      console.log('📝 Mensaje actual:', mensaje)
      console.log('📜 Total mensajes en historial:', historialCompleto.length)
      console.log('⚙️ Configuración:', ajustesAvanzados)
      console.log('\n🔍 DETALLE COMPLETO DEL HISTORIAL:')
      historialCompleto.forEach((msg, idx) => {
        const preview = msg.texto?.substring(0, 80) || ''
        console.log(`  ${idx + 1}. [${msg.tipo.toUpperCase()}] ${preview}${msg.texto?.length > 80 ? '...' : ''}`)
      })
      console.log('='.repeat(70) + '\n')
      
      // Combinar contexto de archivo único + archivos adjuntos
      let contextoFinal = contenidoContexto || null
      
      if (archivosContextoChat.length > 0) {
        console.log('📎 Archivos en contexto:', archivosContextoChat.length)
        archivosContextoChat.forEach((archivo, idx) => {
          console.log(`  ${idx + 1}. ${archivo.nombre} - ${archivo.contenido?.length || 0} caracteres`)
        })
        
        const contextosArchivos = archivosContextoChat.map(archivo => 
          `[Archivo: ${archivo.nombre}]\n${archivo.contenido}\n[Fin de ${archivo.nombre}]\n`
        ).join('\n\n')
        
        console.log('📝 Contexto de archivos combinado:', contextosArchivos.substring(0, 300), '...')
        
        if (contextoFinal) {
          contextoFinal = contextoFinal + '\n\n' + contextosArchivos
        } else {
          contextoFinal = contextosArchivos
        }
      }
      
      console.log('📦 Contexto final a enviar:', contextoFinal ? `${contextoFinal.length} caracteres` : 'null')
      
      const response = await fetch(`${API_URL}/api/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          mensaje,
          contexto: contextoFinal,
          buscar_web: busquedaWebActiva,
          historial: historialCompleto,  // Enviar historial COMPLETO incluyendo mensaje actual
          ajustes: ajustesAvanzados  // Enviar configuración avanzada
        }),
        signal: controller.signal
      })

      const data = await response.json()
      
      // Validar que data no sea null
      if (!data || typeof data !== 'object') {
        throw new Error('El servidor no respondió correctamente.');
      }
      
      if (!data.respuesta) {
        throw new Error('El modelo no generó una respuesta. Verifica la configuración.');
      }
      
      // Si la respuesta contiene un mensaje de error sobre modelos, mostrarlo directamente
      if (data.respuesta.includes('❌')) {
        const nuevaRespuesta = {
          tipo: 'asistente',
          texto: data.respuesta,
          hora: new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })
        }
        setMensajesChat(prev => [...prev, nuevaRespuesta])
        return
      }
      
      // Agregar respuesta del asistente
      const nuevaRespuesta = {
        tipo: 'asistente',
        texto: data.respuesta,
        hora: new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })
      }
      setMensajesChat(prev => {
        const nuevosMensajes = [...prev, nuevaRespuesta]
        // Guardar automáticamente después de cada respuesta
        guardarAutomaticamente(nuevosMensajes)
        return nuevosMensajes
      })
    } catch (error) {
      if (error.name === 'AbortError') {
        setMensajesChat(prev => [...prev, {
          tipo: 'asistente',
          texto: '⚠️ Consulta cancelada por el usuario',
          hora: new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })
        }])
      } else {
        setMensajesChat(prev => [...prev, {
          tipo: 'asistente',
          texto: `❌ Error: ${error.message}`,
          hora: new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })
        }])
      }
    } finally {
      setCargandoChat(false)
      setAbortController(null)
    }
  }

  // Detener/cancelar la consulta
  const detenerConsulta = () => {
    if (abortController) {
      abortController.abort()
      setAbortController(null)
      setCargandoChat(false)
    }
  }

  // Editar mensaje del usuario
  const iniciarEdicionMensaje = (index) => {
    setEditandoMensaje(index)
    setTextoEditado(mensajesChat[index].texto)
  }

  const cancelarEdicion = () => {
    setEditandoMensaje(null)
    setTextoEditado('')
  }

  const guardarEdicionMensaje = async (index) => {
    if (!textoEditado.trim() || cargandoChat) return

    const mensajeEditado = textoEditado.trim()
    
    // Actualizar el mensaje editado
    const nuevosMensajes = [...mensajesChat]
    nuevosMensajes[index].texto = mensajeEditado
    
    // Eliminar mensajes posteriores (respuesta del asistente y mensajes siguientes)
    const mensajesHastaEditado = nuevosMensajes.slice(0, index + 1)
    setMensajesChat(mensajesHastaEditado)
    
    setEditandoMensaje(null)
    setTextoEditado('')
    
    // Crear AbortController para poder cancelar la petición
    const controller = new AbortController()
    setAbortController(controller)
    
    // Reenviar el mensaje editado al asistente
    setCargandoChat(true)
    try {
      const response = await fetch(`${API_URL}/api/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          mensaje: mensajeEditado,
          historial: mensajesHastaEditado  // Enviar historial actualizado
        }),
        signal: controller.signal
      })

      const data = await response.json()
      
      // Agregar nueva respuesta del asistente
      setMensajesChat(prev => [...prev, {
        tipo: 'asistente',
        texto: data.respuesta || 'Error al obtener respuesta',
        hora: new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })
      }])
    } catch (error) {
      if (error.name === 'AbortError') {
        setMensajesChat(prev => [...prev, {
          tipo: 'asistente',
          texto: '⚠️ Consulta cancelada por el usuario',
          hora: new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })
        }])
      } else {
        setMensajesChat(prev => [...prev, {
          tipo: 'asistente',
          texto: `❌ Error: ${error.message}`,
          hora: new Date().toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' })
        }])
      }
    } finally {
      setCargandoChat(false)
      setAbortController(null)
    }
  }

  // Manejar carga de archivo al chat
  const handleArchivoContexto = async (e) => {
    const archivo = e.target.files[0]
    if (!archivo) return

    const extension = archivo.name.split('.').pop().toLowerCase()
    
    if (extension === 'txt') {
      // Leer archivo TXT directamente
      const reader = new FileReader()
      reader.onload = (event) => {
        setContenidoContexto(event.target.result)
        setNombreArchivoContexto(archivo.name)
        setArchivoContexto(archivo)
        setMensaje({
          tipo: 'success',
          texto: `✅ Archivo ${archivo.name} cargado (${(archivo.size / 1024).toFixed(1)} KB)`
        })
      }
      reader.readAsText(archivo)
    } else if (extension === 'pdf') {
      // Procesar PDF en el backend
      const formData = new FormData()
      formData.append('file', archivo)

      try {
        const response = await fetch(`${API_URL}/api/extraer-texto-simple`, {
          method: 'POST',
          body: formData
        })

        const data = await response.json()
        if (data.texto) {
          setContenidoContexto(data.texto)
          setNombreArchivoContexto(archivo.name)
          setArchivoContexto(archivo)
          setMensaje({
            tipo: 'success',
            texto: `✅ PDF ${archivo.name} procesado (${data.caracteres} caracteres)`
          })
        }
      } catch (error) {
        setMensaje({
          tipo: 'error',
          texto: `❌ Error al procesar PDF: ${error.message}`
        })
      }
    } else {
      setMensaje({
        tipo: 'error',
        texto: '❌ Solo se permiten archivos PDF o TXT'
      })
    }
  }

  // Remover archivo de contexto
  const removerArchivoContexto = () => {
    setArchivoContexto(null)
    setContenidoContexto('')
    setNombreArchivoContexto('')
    setMensaje({
      tipo: 'success',
      texto: '✅ Archivo removido del contexto'
    })
  }

  // Cargar historial de chats
  const cargarHistorialChats = async () => {
    try {
      const response = await fetch(`${API_URL}/api/chats/historial`)
      const data = await response.json()
      setHistorialChats(data.chats || [])
    } catch (error) {
      console.error('Error al cargar historial:', error)
    }
  }

  // ===== FUNCIONES PARA NAVEGACIÓN EN MODAL HISTORIAL =====
  
  // Cargar contenido del modal historial
