        "registro": "¿Mantiene el mismo tono (formal/neutral/informal)?",
        "gramatica": "¿Es gramaticalmente correcto para nivel ${nivel}?",
        "naturalidad": "${nivel === 'C1' || nivel === 'C2' ? '¿Suena natural, no forzado o escolar?' : 'Corrección básica'}"
