      const response = await fetch(`${API_URL}/api/carpetas?ruta=${encodeURIComponent(ruta)}`);
      const data = await response.json();
      if (data.carpetas) {
        setCarpetasPracticas(data.carpetas);
        setRutaPracticasActual(ruta);
      }
