                            {flashcard.estadoRevision === 'en_progreso' && '📖'}
                            {flashcard.estadoRevision === 'dominada' && '✅'}
                            {' '}
                            {flashcard.estadoRevision === 'nueva' && 'Nueva'}
                            {flashcard.estadoRevision === 'en_progreso' && 'En Progreso'}
