                                              const numEventos = pregunta.metadata.eventos.length;
                                              const raw = respuestasUsuario[index] || '';
                                              let respuestas = raw ? raw.split('|||') : [];
                                              while (respuestas.length < numEventos) respuestas.push('');
                                              respuestas[eIdx] = e.target.value;
