                                            const raw = respuestasUsuario[index] || '';
                                            let respuestas = raw ? raw.split('|||') : [];
                                            while (respuestas.length < numAf) respuestas.push('::');
                                            const currentParts = (respuestas[afIndex] || '::').split('::');
                                            const currentVf = currentParts[0] || '';
